window.PLAN = {"project": {"org": "Merrowdale Power Networks", "name": "PhaseWise AI - home low-carbon connection review platform", "summary": "Clean five messy extracts, read every technology's requirements from its own standard, screen 40 live applications, train three models, build a searchable knowledge base, run a seven-agent LangGraph review that stops for a Connections Engineer, and serve it through FastAPI and a Streamlit dashboard."}, "people": [{"id": "yashwanth", "name": "Yashwanth", "lead": true, "area": "FastAPI", "focus": "REST service, sign-in & access control, database and records", "colour": "#2E5AAC"}, {"id": "yash", "name": "Yash", "lead": false, "area": "LangGraph", "focus": "Screening tools, the seven agents and the review workflow", "colour": "#7A4FB5"}, {"id": "janavi", "name": "Janavi", "lead": false, "area": "RAG", "focus": "PDF reading, standards, vector index, retrieval and the chat", "colour": "#1F7A5C"}, {"id": "aparna", "name": "Aparna", "lead": false, "area": "Streamlit", "focus": "The dashboard: sign-in, queue, detail, decisions, audit and chat pages", "colour": "#B5562B"}, {"id": "karthik", "name": "Karthik", "lead": false, "area": "ML", "focus": "Data cleaning, quality report, features, the three models and predictions", "colour": "#9A7B12"}], "days": [{"n": 1, "title": "Foundations", "goal": "Lay the base every later file stands on: the database and accounts, the shared cleaning helpers, PDF reading and section splitting, the workflow state and decision rules, and the dashboard's service client.", "check": "python run_database_setup.py", "order": null, "tasks": [{"owner": "yashwanth", "summary": "Database engine, the six tables, the repository and seeded accounts.", "files": [{"path": "persistence/database.py", "explain": "Builds the single SQLAlchemy engine for database/phasewise.db and the session_factory every other module uses. The engine allows several threads (FastAPI answers on its own threads) and waits up to 60 s for a lock. Importing it creates no table - that is run_database_setup.py's job.", "code": "\"\"\"The one connection to the application database and the session factory.\n\nBoth are built once, on import. Importing creates no table and writes nothing;\nrun_database_setup.py creates the tables.\n\"\"\"\n\nfrom sqlalchemy import create_engine\nfrom sqlalchemy.orm import sessionmaker\n\nfrom config import config\n\n# The web framework answers on threads of its own, so the connection is shared\n# across threads; a generous timeout lets concurrent writers wait their turn.\ndatabase_engine = create_engine(\n    config.APPLICATION_DATABASE_URL,\n    connect_args={\"check_same_thread\": False, \"timeout\": 60},\n)\n\nsession_factory = sessionmaker(bind=database_engine, expire_on_commit=False)\n"}, {"path": "persistence/models.py", "explain": "Declares the six tables: user_accounts, agent_runs, application_reviews, review_decisions, llm_calls and chat_turns. Every column the tests and the API read is here with the exact name; only the columns allowed to be empty are nullable (notices, brief, planned days, session token).", "code": "\"\"\"The six tables everything the system is asked to account for is kept in.\"\"\"\n\nfrom sqlalchemy import JSON, Boolean, Column, Float, ForeignKey, Integer, String, Text\nfrom sqlalchemy.orm import declarative_base\n\nfrom config import config\n\nBase = declarative_base()\n\n\nclass UserAccount(Base):\n    \"\"\"One person who signs in, with the stored form of their password.\"\"\"\n\n    __tablename__ = config.USER_ACCOUNTS_TABLE\n\n    username = Column(String, primary_key=True)\n    display_name = Column(String, nullable=False)\n    role = Column(String, nullable=False)\n    password_hash = Column(String, nullable=False)\n    password_salt = Column(String, nullable=False)\n    session_token = Column(String, nullable=True, unique=True)\n\n\nclass AgentRun(Base):\n    \"\"\"One run of the review workflow.\"\"\"\n\n    __tablename__ = config.AGENT_RUNS_TABLE\n\n    run_id = Column(String, primary_key=True)\n    thread_id = Column(String, nullable=False, unique=True)\n    application_reference = Column(String, nullable=False, index=True)\n    coordinator_id = Column(String, nullable=False)\n    coordinator_request = Column(Text, nullable=False)\n    status = Column(String, nullable=False)\n    llm_call_count = Column(Integer, nullable=False)\n\n\nclass ApplicationReview(Base):\n    \"\"\"The review a run stores at the gate, and what its decision led to.\"\"\"\n\n    __tablename__ = config.APPLICATION_REVIEWS_TABLE\n\n    review_id = Column(String, primary_key=True)\n    run_id = Column(String, ForeignKey(f\"{config.AGENT_RUNS_TABLE}.run_id\"), nullable=False)\n    application_reference = Column(String, nullable=False, index=True)\n    technology = Column(String, nullable=False)\n    urgency = Column(String, nullable=True)\n    standard_document = Column(String, nullable=False)\n    coordinator_request = Column(Text, nullable=False)\n    status = Column(String, nullable=False)\n    requirements = Column(JSON, nullable=False)\n    requirements_met_count = Column(Integer, nullable=False)\n    requirements_not_met_count = Column(Integer, nullable=False)\n    requirements_not_documented_count = Column(Integer, nullable=False)\n    network_triggers = Column(JSON, nullable=False)\n    rating_stated = Column(Boolean, nullable=False)\n    assessment = Column(String, nullable=False)\n    decisions_open = Column(JSON, nullable=False)\n    evidence = Column(JSON, nullable=False)\n    disagreements = Column(JSON, nullable=False)\n    network_work_likelihood = Column(Float, nullable=False)\n    likelihood_band = Column(String, nullable=False)\n    expected_working_days = Column(Integer, nullable=False)\n    planned_working_days = Column(Integer, nullable=True)\n    delay_expected = Column(Boolean, nullable=True)\n    duration_text = Column(Text, nullable=False)\n    review_plan_text = Column(Text, nullable=False)\n    requirements_analysis_text = Column(Text, nullable=False)\n    evidence_review_text = Column(Text, nullable=False)\n    prediction_analysis_text = Column(Text, nullable=False)\n    recommendation_text = Column(Text, nullable=False)\n    recommended_decision = Column(String, nullable=False)\n    installer_notice_text = Column(Text, nullable=True)\n    notice_details = Column(JSON, nullable=True)\n    household_notice_text = Column(Text, nullable=True)\n    assessment_brief = Column(JSON, nullable=True)\n\n\nclass ReviewDecision(Base):\n    \"\"\"A Connections Engineer's decision on one review.\"\"\"\n\n    __tablename__ = config.REVIEW_DECISIONS_TABLE\n\n    decision_id = Column(Integer, primary_key=True, autoincrement=True)\n    review_id = Column(\n        String,\n        ForeignKey(f\"{config.APPLICATION_REVIEWS_TABLE}.review_id\"),\n        nullable=False,\n        unique=True,\n    )\n    decision = Column(String, nullable=False)\n    decided_by = Column(String, nullable=False)\n    decided_by_role = Column(String, nullable=False)\n    decision_reason = Column(Text, nullable=False)\n\n\nclass LlmCall(Base):\n    \"\"\"One language model call a run made, and what it cost.\"\"\"\n\n    __tablename__ = config.LLM_CALLS_TABLE\n\n    call_id = Column(Integer, primary_key=True, autoincrement=True)\n    run_id = Column(String, ForeignKey(f\"{config.AGENT_RUNS_TABLE}.run_id\"), nullable=False,\n                    index=True)\n    agent_name = Column(String, nullable=False)\n    model_name = Column(String, nullable=False)\n    prompt_tokens = Column(Integer, nullable=False)\n    response_tokens = Column(Integer, nullable=False)\n    total_tokens = Column(Integer, nullable=False)\n    latency_milliseconds = Column(Integer, nullable=False)\n\n\nclass ChatTurn(Base):\n    \"\"\"One question the chat replied to, refusals included.\"\"\"\n\n    __tablename__ = config.CHAT_TURNS_TABLE\n\n    turn_id = Column(Integer, primary_key=True, autoincrement=True)\n    username = Column(String, nullable=False, index=True)\n    user_role = Column(String, nullable=False)\n    question_text = Column(Text, nullable=False)\n    question_type = Column(String, nullable=False)\n    application_reference = Column(String, nullable=True)\n    substation_reference = Column(String, nullable=True)\n    technology = Column(String, nullable=True)\n    answer_text = Column(Text, nullable=False)\n    source_documents = Column(Text, nullable=False)\n    closest_distance = Column(Float, nullable=True)\n    was_refused = Column(Boolean, nullable=False)\n"}, {"path": "persistence/repository.py", "explain": "The only module that runs queries. insert_/fetch_/update_ helpers for accounts, runs, LLM calls, reviews, decisions and chat turns. Writes flush into the caller's transaction, reads return plain dicts. fetch_review_records joins each review with its run (thread, opener, call count) and its decision.", "code": "\"\"\"Every read and write against the six tables. Reads return plain records.\"\"\"\n\nfrom sqlalchemy import select\n\nfrom persistence.models import (\n    AgentRun,\n    ApplicationReview,\n    ChatTurn,\n    LlmCall,\n    ReviewDecision,\n    UserAccount,\n)\n\n\ndef _record(row, model):\n    return {column.name: getattr(row, column.name) for column in model.__table__.columns}\n\n\ndef insert_user_account(session, account_record):\n    \"\"\"Create one sign-in account in the caller's transaction.\"\"\"\n    session.add(UserAccount(**account_record))\n    session.flush()\n\n\ndef fetch_user_account(session, condition):\n    \"\"\"One account as a plain record, or None.\"\"\"\n    row = session.execute(select(UserAccount).where(condition)).scalars().first()\n    return None if row is None else _record(row, UserAccount)\n\n\ndef update_session_token(session, username, session_token):\n    \"\"\"Start or end one person's session.\"\"\"\n    row = session.get(UserAccount, username)\n    if row is None:\n        raise ValueError(f\"No account has the username {username}\")\n    row.session_token = session_token\n    session.flush()\n\n\ndef insert_agent_run(session, run_record):\n    \"\"\"Open the record of one workflow run.\"\"\"\n    session.add(AgentRun(**run_record))\n    session.flush()\n\n\ndef fetch_agent_run(session, condition):\n    \"\"\"One run as a plain record, or None.\"\"\"\n    row = session.execute(select(AgentRun).where(condition)).scalars().first()\n    return None if row is None else _record(row, AgentRun)\n\n\ndef update_agent_run(session, run_id, status_value, llm_call_count):\n    \"\"\"Move a run on, recording what it has cost.\"\"\"\n    row = session.get(AgentRun, run_id)\n    if row is None:\n        raise ValueError(f\"No agent run has the identifier {run_id}\")\n    row.status = status_value\n    row.llm_call_count = int(llm_call_count)\n    session.flush()\n\n\ndef insert_llm_call(session, run_id, call_record):\n    \"\"\"Record one language model call against its run.\"\"\"\n    session.add(LlmCall(run_id=run_id, **call_record))\n    session.flush()\n\n\ndef fetch_llm_calls(session, run_id):\n    \"\"\"A run's calls, in the order they were made.\"\"\"\n    rows = session.execute(\n        select(LlmCall).where(LlmCall.run_id == run_id).order_by(LlmCall.call_id)\n    ).scalars()\n    return [\n        {\n            \"agent_name\": row.agent_name,\n            \"model_name\": row.model_name,\n            \"prompt_tokens\": row.prompt_tokens,\n            \"response_tokens\": row.response_tokens,\n            \"total_tokens\": row.total_tokens,\n            \"latency_milliseconds\": row.latency_milliseconds,\n        }\n        for row in rows\n    ]\n\n\ndef insert_application_review(session, review_record):\n    \"\"\"Store the review waiting at the gate.\"\"\"\n    session.add(ApplicationReview(**review_record))\n    session.flush()\n\n\ndef fetch_review_records(session, condition):\n    \"\"\"Reviews with their run and their decision, by application reference then identifier.\"\"\"\n    rows = session.execute(\n        select(ApplicationReview, AgentRun, ReviewDecision)\n        .outerjoin(AgentRun, AgentRun.run_id == ApplicationReview.run_id)\n        .outerjoin(ReviewDecision, ReviewDecision.review_id == ApplicationReview.review_id)\n        .where(condition)\n        .order_by(ApplicationReview.application_reference, ApplicationReview.review_id)\n    ).all()\n    records = []\n    for review, run, decision in rows:\n        record = _record(review, ApplicationReview)\n        record[\"thread_id\"] = None if run is None else run.thread_id\n        record[\"coordinator_id\"] = None if run is None else run.coordinator_id\n        record[\"llm_call_count\"] = None if run is None else run.llm_call_count\n        for field in [\"decision\", \"decided_by\", \"decided_by_role\", \"decision_reason\"]:\n            record[field] = None if decision is None else getattr(decision, field)\n        records.append(record)\n    return records\n\n\ndef insert_review_decision(session, decision_record):\n    \"\"\"Record a Connections Engineer's decision, one per review.\"\"\"\n    session.add(ReviewDecision(**decision_record))\n    session.flush()\n\n\ndef record_review_outcome(session, review_id, outcome_record):\n    \"\"\"Write exactly the given columns onto a decided review.\"\"\"\n    row = session.get(ApplicationReview, review_id)\n    if row is None:\n        raise ValueError(f\"No application review has the identifier {review_id}\")\n    for column_name, value in outcome_record.items():\n        setattr(row, column_name, value)\n    session.flush()\n\n\ndef insert_chat_turn(session, turn_record):\n    \"\"\"Record one chat exchange, refusals included.\"\"\"\n    session.add(ChatTurn(**turn_record))\n    session.flush()\n\n\ndef fetch_chat_turns(session, condition, turn_limit):\n    \"\"\"The most recent chat turns meeting the condition, newest first.\"\"\"\n    rows = session.execute(\n        select(ChatTurn).where(condition).order_by(ChatTurn.turn_id.desc()).limit(int(turn_limit))\n    ).scalars()\n    return [_record(row, ChatTurn) for row in rows]\n"}, {"path": "access/password_security.py", "explain": "hash_password(password, salt): PBKDF2-SHA256 with 200,000 rounds, returned as hex text, so the database never stores a password. Same password + same salt = same hash; a different salt gives a different hash.", "code": "\"\"\"Turns a password into the salted, stretched form the database stores.\"\"\"\n\nimport hashlib\n\nfrom config import config\n\n\ndef hash_password(plain_password, password_salt):\n    \"\"\"PBKDF2 over the configured algorithm and rounds, written as hexadecimal text.\"\"\"\n    derived = hashlib.pbkdf2_hmac(\n        config.PASSWORD_HASH_ALGORITHM,\n        plain_password.encode(\"utf-8\"),\n        password_salt.encode(\"utf-8\"),\n        config.PASSWORD_HASH_ROUNDS,\n    )\n    return derived.hex()\n"}, {"path": "run_database_setup.py", "explain": "Entry point 1. Creates database/, all six tables and the 14 seeded staff accounts, each with its own random salt. Safe to run twice: the second run creates 0 accounts. Refuses an old database whose columns differ and tells you to delete it and checkpoint.db.", "code": "\"\"\"Entry point 1: creates the database, its tables and the staff accounts. Safe to run again.\n\nRun from the Project folder:  python run_database_setup.py\n\"\"\"\n\nimport os\nimport secrets\n\nfrom sqlalchemy import inspect\n\nfrom access.password_security import hash_password\nfrom config import config\nfrom persistence.database import database_engine, session_factory\nfrom persistence.models import Base, UserAccount\nfrom persistence.repository import fetch_user_account, insert_user_account\n\n\ndef _refuse_earlier_versions():\n    \"\"\"Refuse a database whose tables were made by an earlier version of the models.\"\"\"\n    inspector = inspect(database_engine)\n    existing = set(inspector.get_table_names())\n    for table in Base.metadata.sorted_tables:\n        if table.name not in existing:\n            continue\n        stored = {\n            column[\"name\"]: bool(column[\"nullable\"])\n            for column in inspector.get_columns(table.name)\n        }\n        declared = {column.name: bool(column.nullable) for column in table.columns}\n        if stored != declared:\n            raise SystemExit(\n                f\"The table {table.name} in {config.APPLICATION_DATABASE_FILE} was made by an \"\n                f\"earlier version: delete {config.APPLICATION_DATABASE_FILE} and \"\n                f\"{config.CHECKPOINT_DATABASE_FILE}, then run this again.\"\n            )\n\n\ndef main():\n    \"\"\"Create the folder, the tables and every seeded account that is not there yet.\"\"\"\n    os.makedirs(config.DATABASE_DIRECTORY, exist_ok=True)\n    _refuse_earlier_versions()\n    Base.metadata.create_all(database_engine)\n    print(f\"database: {config.APPLICATION_DATABASE_FILE}\")\n    print(\"tables: \" + \", \".join(sorted(Base.metadata.tables)))\n    created, present = 0, 0\n    with session_factory() as session:\n        for account in config.SEED_USER_ACCOUNTS:\n            existing = fetch_user_account(session, UserAccount.username == account[\"username\"])\n            if existing is not None:\n                present += 1\n                continue\n            salt = secrets.token_bytes(config.PASSWORD_SALT_BYTES).hex()\n            insert_user_account(\n                session,\n                {\n                    \"username\": account[\"username\"],\n                    \"display_name\": account[\"display_name\"],\n                    \"role\": account[\"role\"],\n                    \"password_salt\": salt,\n                    \"password_hash\": hash_password(account[\"password\"], salt),\n                    \"session_token\": None,\n                },\n            )\n            created += 1\n            print(\n                f\"  account created  {account['username']:<{config.USERNAME_WIDTH}} \"\n                f\"{account['display_name']:<{config.DISPLAY_NAME_WIDTH}} {account['role']}\"\n            )\n        session.commit()\n    print(f\"accounts created: {created}, already present: {present}\")\n\n\nif __name__ == \"__main__\":\n    main()\n"}], "commands": "git config pull.rebase false\ngit pull origin main\nmkdir -p access persistence\n# paste today's files, then:\ngit add persistence/database.py persistence/models.py persistence/repository.py access/password_security.py run_database_setup.py\ngit commit -m \"Day 1 (FastAPI): Database engine, the six tables, the repository and seeded accounts\"\ngit push origin HEAD", "demo": "python run_database_setup.py\npython run_database_setup.py", "show": "First run creates database/phasewise.db, lists the six tables and creates 14 accounts. The second run prints 'accounts created: 0, already present: 14' - it is safe to repeat. Passwords are stored as salted PBKDF2 hashes, never as text."}, {"owner": "yash", "summary": "Workflow state and the rules that refuse a decision before any LLM call.", "files": [{"path": "agentic/state.py", "explain": "ApplicationReviewState - the TypedDict the LangGraph workflow carries between nodes. llm_call_count is Annotated with operator.add so each node's 1 is added up; every other key is replaced by the node that writes it.", "code": "\"\"\"What the review workflow carries from one node to the next.\"\"\"\n\nimport operator\nfrom typing import Annotated, TypedDict\n\n\nclass ApplicationReviewState(TypedDict):\n    \"\"\"The workflow's state. llm_call_count is added to; every other key is replaced.\"\"\"\n\n    application_reference: str\n    coordinator_request: str\n    coordinator_id: str\n    thread_id: str\n    run_id: str\n    review_id: str\n    application_profile: dict\n    application_documents: list\n    screening: dict\n    evidence_findings: list\n    disagreements: list\n    likelihood: dict\n    duration: dict\n    review_plan: dict\n    requirements_analysis: dict\n    evidence_review: dict\n    prediction_analysis: dict\n    review_recommendation: dict\n    review_decision: dict\n    installer_notice: dict\n    notice_details: dict\n    household_notice: dict\n    llm_call_count: Annotated[int, operator.add]\n"}, {"path": "tools/decision_tools.py", "explain": "find_review_conflict: a review already decided, or a different decision still being recorded, is refused. find_decision_refusal: missing fields, an unknown decision, a non-engineer, the engineer who opened the review, or a decision not open for this assessment - each refused in the config's exact words, before any LLM call.", "code": "\"\"\"Why a decision may not be recorded, worked out before any language model call is spent.\"\"\"\n\nfrom config import config\n\n\ndef find_review_conflict(review_status, pending_decision, review_decision,\n                         application_reference):\n    \"\"\"Whether the review's state allows a decision at all.\"\"\"\n    if review_status in config.DECIDED_REVIEW_STATUSES:\n        return config.ALREADY_DECIDED_MESSAGE.format(application_reference=application_reference)\n    if pending_decision:\n        differs = any(\n            pending_decision.get(field) != review_decision.get(field)\n            for field in config.DECISION_RECORD_FIELDS\n        )\n        if differs:\n            return config.DECISION_IN_PROGRESS_MESSAGE.format(\n                pending_decided_by=pending_decision.get(\"decided_by\"),\n                pending_decision=pending_decision.get(\"decision\"),\n                application_reference=application_reference,\n            )\n    return None\n\n\ndef find_decision_refusal(review_decision, screening, opened_by):\n    \"\"\"The first reason this decision may not be recorded on this review, or None.\"\"\"\n    application_reference = screening.get(\"application_reference\")\n    missing = [\n        field\n        for field in config.DECISION_RECORD_FIELDS\n        if not isinstance(review_decision.get(field), str) or not review_decision[field].strip()\n    ]\n    if missing:\n        return config.DECISION_FIELDS_MISSING_MESSAGE.format(\n            application_reference=application_reference, fields=\", \".join(missing)\n        )\n    decision = review_decision[\"decision\"]\n    if decision not in config.DECISIONS:\n        return config.UNKNOWN_DECISION_MESSAGE.format(\n            decision=decision,\n            application_reference=application_reference,\n            decisions=\", \".join(config.DECISIONS),\n        )\n    role = review_decision[\"decided_by_role\"]\n    if role != config.ROLE_CONNECTIONS_ENGINEER:\n        return config.DECIDING_ROLE_MESSAGE.format(\n            role=role,\n            application_reference=application_reference,\n            engineer_role=config.ROLE_CONNECTIONS_ENGINEER,\n        )\n    if review_decision[\"decided_by\"] == opened_by:\n        return config.OWN_REVIEW_MESSAGE.format(\n            decided_by=review_decision[\"decided_by\"],\n            application_reference=application_reference,\n        )\n    if decision not in screening.get(\"decisions_open\", []):\n        return config.DECISION_NOT_OPEN_MESSAGE.format(\n            decision=decision,\n            application_reference=application_reference,\n            reason=config.APPROVE_CLOSED_REASONS.get(screening.get(\"assessment\"), \"\"),\n        )\n    return None\n"}], "commands": "git config pull.rebase false\ngit pull origin main\nmkdir -p agentic tools\n# paste today's files, then:\ngit add agentic/state.py tools/decision_tools.py\ngit commit -m \"Day 1 (LangGraph): Workflow state and the rules that refuse a decision before any LLM call\"\ngit push origin HEAD", "demo": "python - <<'EOF'\nfrom config import config\nfrom tools.decision_tools import find_decision_refusal, find_review_conflict\nscreening = {\"application_reference\": \"LCT0052118\", \"assessment\": config.DECISION_RETURN,\n             \"decisions_open\": config.DECISIONS_OPEN[config.DECISION_RETURN]}\ndecision = {\"decision\": config.DECISION_APPROVE, \"decided_by\": \"lewis\",\n            \"decided_by_role\": config.ROLE_CONNECTIONS_ENGINEER,\n            \"decision_reason\": \"Every requirement is met on the form.\"}\nprint(find_decision_refusal(decision, screening, \"megan\"))\nprint(find_decision_refusal(dict(decision, decided_by=\"megan\"), screening, \"megan\"))\nprint(find_review_conflict(config.REVIEW_STATUS_APPROVED, None, decision, \"LCT0052118\"))\nEOF", "show": "Approving an application assessed RETURN TO INSTALLER is refused with the reason, the engineer who opened a review may not decide it, and a review already decided cannot be decided again - all before any model call is spent."}, {"owner": "janavi", "summary": "Read the 16 PDFs and cut them into sections and passages.", "files": [{"path": "knowledge/pdf_extraction.py", "explain": "extract_text_from_directory reads every .pdf in data/docs (any case of the suffix), in name order, one page per line break. A PDF with no pages or a page that gives no text, or a folder without PDFs, is refused by name.", "code": "\"\"\"Gets the text out of the PDFs and does nothing else with it.\"\"\"\n\nimport os\n\nfrom pypdf import PdfReader\n\nfrom config import config\n\n\ndef extract_text_from_directory(docs_directory):\n    \"\"\"Read every PDF in a folder once, in name order, one page to a line break.\"\"\"\n    names = sorted(\n        name\n        for name in os.listdir(docs_directory)\n        if name.lower().endswith(config.PDF_FILE_SUFFIX.lower())\n        and os.path.isfile(os.path.join(docs_directory, name))\n    )\n    if not names:\n        raise ValueError(f\"The folder {docs_directory} holds no PDF document\")\n    documents = []\n    for name in names:\n        file_path = os.path.join(docs_directory, name)\n        reader = PdfReader(file_path)\n        if len(reader.pages) == 0:\n            raise ValueError(f\"{file_path} has no pages\")\n        page_texts = []\n        for page_number, page in enumerate(reader.pages, start=1):\n            text = page.extract_text() or \"\"\n            if not text.strip():\n                raise ValueError(f\"Page {page_number} of {file_path} gives up no text\")\n            page_texts.append(text)\n        documents.append({\"document_name\": name, \"document_text\": \"\\n\".join(page_texts)})\n    return documents\n"}, {"path": "knowledge/chunk_splitting.py", "explain": "split_documents_into_sections checks each document has exactly one header line and sections numbered 1, 2, 3... and returns each section whole with whitespace normalised. build_chunk_records packs whole sentences into passages of at most 700 characters, each new passage repeating up to 120 characters of the previous one so nothing is cut in half.", "code": "\"\"\"Cuts the documents into numbered sections and overlapping passages of whole sentences.\"\"\"\n\nimport re\n\nfrom config import config\n\n\ndef _normalise(text):\n    return re.sub(config.WHITESPACE_RUN_PATTERN, \" \", text).strip()\n\n\ndef split_documents_into_sections(document_entries):\n    \"\"\"Divide each document at its numbered headings, below its one header line.\"\"\"\n    sections = []\n    for entry in document_entries:\n        document_name = entry[\"document_name\"]\n        text = entry[\"document_text\"]\n        headers = list(re.finditer(config.DOCUMENT_HEADER_PATTERN, text))\n        if len(headers) != 1:\n            raise ValueError(\n                f\"{document_name} carries {len(headers)} header lines where it carries one\"\n            )\n        body = text[headers[0].end():]\n        headings = list(re.finditer(config.SECTION_HEADING_PATTERN, body))\n        numbers = [int(heading.group(1)) for heading in headings]\n        if not numbers or numbers != list(range(1, len(numbers) + 1)):\n            raise ValueError(\n                f\"{document_name} has sections numbered {numbers} where they run from 1 in order\"\n            )\n        for position, heading in enumerate(headings):\n            end = headings[position + 1].start() if position + 1 < len(headings) else len(body)\n            sections.append(\n                {\n                    \"document_name\": document_name,\n                    \"section_number\": numbers[position],\n                    \"section_text\": _normalise(body[heading.start():end]),\n                }\n            )\n    return sections\n\n\ndef _joined_length(sentences):\n    return len(\" \".join(sentences))\n\n\ndef build_chunk_records(section_entries):\n    \"\"\"Cut each section into passages of whole sentences that overlap their neighbours.\"\"\"\n    records = []\n    passage_numbers = {}\n    for section in section_entries:\n        document_name = section[\"document_name\"]\n        sentences = [\n            sentence\n            for sentence in re.split(config.SENTENCE_BOUNDARY_PATTERN, section[\"section_text\"])\n            if sentence\n        ]\n        if not sentences:\n            sentences = [section[\"section_text\"]]\n        index = 0\n        previous = None\n        while index < len(sentences):\n            carried = []\n            if previous is not None:\n                for sentence in reversed(previous):\n                    candidate = [sentence] + carried\n                    if _joined_length(candidate) <= config.CHUNK_OVERLAP_CHARACTERS:\n                        carried = candidate\n                    else:\n                        break\n                while carried and (\n                    _joined_length(carried + [sentences[index]]) > config.CHUNK_SIZE_CHARACTERS\n                ):\n                    carried = carried[1:]\n            current = carried + [sentences[index]]\n            index += 1\n            while index < len(sentences) and (\n                _joined_length(current + [sentences[index]]) <= config.CHUNK_SIZE_CHARACTERS\n            ):\n                current.append(sentences[index])\n                index += 1\n            passage_number = passage_numbers.get(document_name, 0)\n            passage_numbers[document_name] = passage_number + 1\n            records.append(\n                {\n                    \"chunk_id\": f\"{document_name}::passage-{passage_number:04d}\",\n                    \"chunk_text\": \" \".join(current),\n                    \"document_name\": document_name,\n                    \"section_number\": int(section[\"section_number\"]),\n                    \"passage_number\": passage_number,\n                    \"carried_characters\": _joined_length(carried) + 1 if carried else 0,\n                }\n            )\n            previous = current\n    return records\n"}], "commands": "git config pull.rebase false\ngit pull origin main\nmkdir -p knowledge\n# paste today's files, then:\ngit add knowledge/pdf_extraction.py knowledge/chunk_splitting.py\ngit commit -m \"Day 1 (RAG): Read the 16 PDFs and cut them into sections and passages\"\ngit push origin HEAD", "demo": "python - <<'EOF'\nfrom config import config\nfrom knowledge.pdf_extraction import extract_text_from_directory\nfrom knowledge.chunk_splitting import split_documents_into_sections, build_chunk_records\ndocuments = extract_text_from_directory(config.DOCS_DIRECTORY)\nsections = split_documents_into_sections(documents)\npassages = build_chunk_records(sections)\nprint(len(documents), \"documents,\", len(sections), \"sections,\", len(passages), \"passages\")\nprint(\"longest passage:\", max(len(p[\"chunk_text\"]) for p in passages), \"characters\")\nEOF", "show": "16 documents and 136 sections, every passage at most 700 characters, and each passage after the first of a section repeats the end of the previous one (carried_characters) so no requirement is cut in half."}, {"owner": "aparna", "summary": "The single service client, shared styling and the sign-in page.", "files": [{"path": "dashboard/api_client.py", "explain": "call_service - every dashboard request goes through it: base URL, timeout and the session token header are added here. A 401 ends the session and returns to sign-in; any other error shows the service's own message. Also holds the shared Archivo styling, badges and stat cards so every page looks the same.", "code": "\"\"\"Every request the dashboard sends goes through call_service; the shared look lives here too.\n\nNo page holds an address, a timeout or a session token.\n\"\"\"\n\nimport html\n\nimport httpx\nimport streamlit as st\n\nfrom config import config\n\nSESSION_USER_KEY = \"signed_in_user\"\nSESSION_ENDED_KEY = \"session_ended\"\n\nBADGE_STYLES = {\n    \"green\": (\"#E7F4EC\", \"#1E6B3A\"),\n    \"orange\": (\"#FDF0E1\", \"#9A5B13\"),\n    \"violet\": (\"#F0EBFB\", \"#5B3BA8\"),\n    \"blue\": (\"#E6F0FB\", \"#1F5FA8\"),\n    \"red\": (\"#FCE9E8\", \"#A3302A\"),\n    \"yellow\": (\"#FBF5DC\", \"#7D6510\"),\n    \"gray\": (\"#EFEFEC\", \"#55554F\"),\n    \"primary\": (\"#E8EEFB\", \"#2E4FA0\"),\n}\n\nPAGE_STYLE = \"\"\"\n<style>\n@import url('https://fonts.googleapis.com/css2?family=Archivo:wght@400;500;600;700&display=swap');\nhtml, body, [class*=\"css\"], .stMarkdown, .stText, button, input, textarea, select {\n  font-family: 'Archivo', 'Archivo Fallback', system-ui, sans-serif;\n}\n.stApp { background: #F7F6F2; }\n.block-container { padding-top: 2rem; max-width: 1280px; }\n.pw-card { background: #FFFFFF; border: 1px solid #E7E5DF; border-radius: 14px;\n  padding: 18px 20px; height: 100%; }\n.pw-card-head { display: flex; align-items: center; gap: 10px; color: #4B4A45;\n  font-size: 0.95rem; font-weight: 500; }\n.pw-chip { width: 30px; height: 30px; border-radius: 8px; display: inline-flex;\n  align-items: center; justify-content: center; font-size: 15px; }\n.pw-value { font-size: 2rem; font-weight: 700; color: #1C1B18; margin: 10px 0 4px; }\n.pw-caption { color: #6B6A63; font-size: 0.88rem; line-height: 1.35; }\n.pw-badge { display: inline-block; padding: 2px 10px; border-radius: 999px;\n  font-size: 0.78rem; font-weight: 600; margin: 0 6px 6px 0; letter-spacing: 0.01em; }\n.pw-title { font-size: 1.6rem; font-weight: 700; color: #1C1B18; margin-bottom: 0; }\n.pw-sub { color: #6B6A63; margin-top: 2px; margin-bottom: 18px; }\n.pw-row { background: #FFFFFF; border: 1px solid #E7E5DF; border-radius: 12px;\n  padding: 12px 16px; margin-bottom: 8px; }\n.pw-flag { background: #FCE9E8; border-left: 3px solid #A3302A; }\n</style>\n\"\"\"\n\n\ndef apply_page_style():\n    \"\"\"The dashboard's shared look, drawn once per page.\"\"\"\n    st.markdown(PAGE_STYLE, unsafe_allow_html=True)\n\n\ndef badge_html(text, colour):\n    background, foreground = BADGE_STYLES.get(colour, BADGE_STYLES[\"gray\"])\n    return (\n        f'<span class=\"pw-badge\" style=\"background:{background};color:{foreground}\">'\n        f\"{html.escape(str(text))}</span>\"\n    )\n\n\ndef show_badges(pairs):\n    \"\"\"Draw a row of (text, colour) badges.\"\"\"\n    st.markdown(\"\".join(badge_html(text, colour) for text, colour in pairs), unsafe_allow_html=True)\n\n\ndef stat_card(icon, label, value, caption, colour=\"gray\"):\n    \"\"\"One white card: an icon chip, a label, a big figure and a caption.\"\"\"\n    background, foreground = BADGE_STYLES.get(colour, BADGE_STYLES[\"gray\"])\n    st.markdown(\n        f'<div class=\"pw-card\"><div class=\"pw-card-head\"><span class=\"pw-chip\" '\n        f'style=\"background:{background};color:{foreground}\">{icon}</span>'\n        f\"{html.escape(str(label))}</div><div class=\\\"pw-value\\\">{html.escape(str(value))}</div>\"\n        f'<div class=\"pw-caption\">{html.escape(str(caption))}</div></div>',\n        unsafe_allow_html=True,\n    )\n\n\ndef page_heading(title, subtitle):\n    st.markdown(\n        f'<div class=\"pw-title\">{html.escape(title)}</div>'\n        f'<div class=\"pw-sub\">{html.escape(subtitle)}</div>',\n        unsafe_allow_html=True,\n    )\n\n\ndef signed_in_user():\n    \"\"\"The signed-in person's sign-in reply, or None.\"\"\"\n    return st.session_state.get(SESSION_USER_KEY)\n\n\ndef _end_session():\n    st.session_state.pop(SESSION_USER_KEY, None)\n    st.session_state[SESSION_ENDED_KEY] = True\n\n\ndef _send(method, path, query, payload, headers):\n    with httpx.Client(\n        base_url=config.API_BASE_URL, timeout=config.API_REQUEST_TIMEOUT_SECONDS\n    ) as client:\n        return client.request(method, path, params=query, json=payload, headers=headers)\n\n\ndef call_service(method, path, query=None, payload=None, waiting_message=None):\n    \"\"\"Make one call to the service and give the page back its reply.\"\"\"\n    headers = {}\n    user = signed_in_user()\n    if user is not None:\n        headers[config.SESSION_TOKEN_HEADER] = user[\"session_token\"]\n    if waiting_message:\n        try:\n            spinner = st.spinner(waiting_message, show_time=True)\n        except TypeError:\n            spinner = st.spinner(waiting_message)\n        with spinner:\n            reply = _send(method, path, query, payload, headers)\n    else:\n        reply = _send(method, path, query, payload, headers)\n    if reply.status_code == 401 and user is not None:\n        _end_session()\n        st.rerun()\n    if reply.status_code >= 400:\n        try:\n            detail = reply.json().get(\"detail\")\n        except ValueError:\n            detail = None\n        if isinstance(detail, list):\n            detail = \"; \".join(str(item.get(\"msg\", item)) for item in detail)\n        st.error(detail if detail else f\"{reply.status_code}: {reply.text}\")\n        st.stop()\n    return reply.json()\n"}, {"path": "dashboard/sign_in.py", "explain": "render_sign_in_page - title, subtitle, username and password form. Signing in calls the service once with the trimmed username, keeps the reply (token, role, pages) in the browser session, and shows the session-ended message once after a 401.", "code": "\"\"\"The sign-in page.\"\"\"\n\nimport httpx\nimport streamlit as st\n\nfrom config import config\nfrom dashboard.api_client import (\n    SESSION_ENDED_KEY,\n    SESSION_USER_KEY,\n    apply_page_style,\n)\n\n\ndef render_sign_in_page():\n    \"\"\"Let a person sign in; the service decides who they are and what they may reach.\"\"\"\n    apply_page_style()\n    _, middle, _ = st.columns([1, 1.2, 1])\n    with middle:\n        st.markdown(\n            f'<div style=\"margin-top:8vh\" class=\"pw-title\">{config.DASHBOARD_TITLE}</div>'\n            f'<div class=\"pw-sub\">{config.DASHBOARD_SUBTITLE}</div>',\n            unsafe_allow_html=True,\n        )\n        if st.session_state.pop(SESSION_ENDED_KEY, False):\n            st.warning(config.SESSION_ENDED_MESSAGE)\n        with st.form(\"sign_in_form\", border=True):\n            username = st.text_input(\"Username\")\n            password = st.text_input(\"Password\", type=\"password\")\n            submitted = st.form_submit_button(\"Sign in\", type=\"primary\", use_container_width=True)\n        if submitted:\n            try:\n                with httpx.Client(\n                    base_url=config.API_BASE_URL, timeout=config.API_REQUEST_TIMEOUT_SECONDS\n                ) as client:\n                    reply = client.post(\n                        \"/auth/signin\",\n                        json={\"username\": username.strip(), \"password\": password},\n                    )\n            except httpx.HTTPError:\n                st.error(\n                    f\"The service is not answering at {config.API_BASE_URL}. Start it with: \"\n                    \"python run_api_service.py\"\n                )\n                return\n            if reply.status_code == 200:\n                st.session_state[SESSION_USER_KEY] = reply.json()\n                st.rerun()\n            else:\n                try:\n                    st.error(reply.json().get(\"detail\"))\n                except ValueError:\n                    st.error(f\"{reply.status_code}: {reply.text}\")\n"}], "commands": "git config pull.rebase false\ngit pull origin main\nmkdir -p dashboard\n# paste today's files, then:\ngit add dashboard/api_client.py dashboard/sign_in.py\ngit commit -m \"Day 1 (Streamlit): The single service client, shared styling and the sign-in page\"\ngit push origin HEAD", "demo": "printf 'from dashboard.sign_in import render_sign_in_page\\nrender_sign_in_page()\\n' > _preview.py\npython -m streamlit run _preview.py --server.port 8080\n# open http://localhost:8080, then stop with Ctrl+C and remove the preview:\nrm _preview.py", "show": "The sign-in page renders with the title, subtitle and form. Without the service running, signing in shows a clear 'service is not answering' message instead of crashing. Every later page calls the service only through call_service. Do not commit _preview.py."}, {"owner": "karthik", "summary": "Raw loader and every shared repair; forms and statements cleaned.", "files": [{"path": "data_pipeline/dataset_loader.py", "explain": "load_raw_dataset reads a raw CSV with every column as text, trims spaces and turns only the config NULL_TOKENS (N/A, -, TBC, unknown, not recorded...) into NaN. save_processed_dataset writes without an index; load_processed_dataset reads types back.", "code": "\"\"\"Reads raw extracts as text and reads/writes cleaned tables.\n\nThis is the only data preparation module that touches CSV files.\n\"\"\"\n\nimport os\n\nimport numpy as np\nimport pandas as pd\n\nfrom config import config\n\n\ndef load_raw_dataset(file_path):\n    \"\"\"Read one raw file as text, guessing nothing.\n\n    Every value is text without surrounding whitespace; only a value matching\n    one of config.NULL_TOKENS (ignoring case and spaces) becomes NaN.\n    \"\"\"\n    frame = pd.read_csv(file_path, dtype=str, keep_default_na=False, na_filter=False)\n    null_tokens = {token.strip().lower() for token in config.NULL_TOKENS}\n    for column_name in frame.columns:\n        stripped = frame[column_name].astype(str).str.strip()\n        is_missing = stripped.str.lower().isin(null_tokens)\n        frame[column_name] = stripped.where(~is_missing, np.nan).astype(object)\n    return frame\n\n\ndef save_processed_dataset(dataframe, file_path):\n    \"\"\"Write a cleaned table to disk without an index column.\"\"\"\n    folder = os.path.dirname(file_path)\n    if folder:\n        os.makedirs(folder, exist_ok=True)\n    dataframe.to_csv(file_path, index=False)\n\n\ndef load_processed_dataset(file_path):\n    \"\"\"Read a cleaned table, types taken from its contents; only empty cells are missing.\"\"\"\n    return pd.read_csv(file_path, keep_default_na=False, na_values=[\"\"], low_memory=False)\n"}, {"path": "data_pipeline/common_cleaning.py", "explain": "All shared repairs: exact duplicates, required keys, repeated ids, spellings to canonical values, LCT references, identifiers, whole numbers, phases, impossible phase pairs, currents to amps per phase (kW/W/kVA converted exactly with Decimal and rounded half up), powers/power factors/resistances, min/max/size blanking, latest revision, markup to plain text and lowering text written in capitals.", "code": "\"\"\"Repairs shared by every cleaning run, the live files, the tools and the profiles.\n\nEvery function returns a repaired copy and never touches what it was given.\nA value in a notation a function does not recognise is refused with a\nValueError naming the column and the values as written.\n\"\"\"\n\nimport html\nimport re\nfrom decimal import ROUND_HALF_UP, Decimal\n\nimport numpy as np\nimport pandas as pd\n\nfrom config import config\n\n\ndef _is_blank(value):\n    \"\"\"True for None, NaN and pandas' NA.\"\"\"\n    if value is None or value is pd.NA:\n        return True\n    try:\n        return bool(pd.isna(value))\n    except (TypeError, ValueError):\n        return False\n\n\ndef _refuse_values(column_name, values):\n    \"\"\"Raise the refusal every reader uses, naming the column and the values.\"\"\"\n    written = sorted({str(value) for value in values})\n    raise ValueError(\n        f\"{column_name} holds values in no notation the Connection Rules read: \"\n        + \", \".join(written)\n    )\n\n\ndef _round_half_up(number, step):\n    \"\"\"Round an exact decimal once, half up, to the given step.\"\"\"\n    return Decimal(number).quantize(Decimal(step), rounding=ROUND_HALF_UP)\n\n\ndef remove_duplicate_records(dataframe):\n    \"\"\"Drop rows written twice, keeping the first copy, numbered from nought.\"\"\"\n    return dataframe.drop_duplicates(keep=\"first\").reset_index(drop=True)\n\n\ndef refuse_missing_values(dataframe, required_columns):\n    \"\"\"Refuse a table in which a required key is blank.\"\"\"\n    for column_name in required_columns:\n        blank_count = int(dataframe[column_name].isna().sum())\n        if blank_count > 0:\n            raise ValueError(\n                f\"{column_name} is blank on {blank_count} rows, and every row must give it\"\n            )\n    return dataframe\n\n\ndef refuse_repeated_references(dataframe, reference_column):\n    \"\"\"Refuse a table in which two rows claim the same identity.\"\"\"\n    repeated = dataframe[reference_column][\n        dataframe[reference_column].duplicated(keep=False)\n        & dataframe[reference_column].notna()\n    ]\n    if len(repeated) > 0:\n        values = sorted({str(value) for value in repeated})\n        raise ValueError(\n            f\"{reference_column} repeats on more than one row: \" + \", \".join(values)\n        )\n    return dataframe\n\n\ndef remove_rows_missing_target(dataframe, target_column):\n    \"\"\"Keep only the rows that carry an answer, numbered from nought.\"\"\"\n    return dataframe[dataframe[target_column].notna()].reset_index(drop=True)\n\n\ndef normalize_category_values(dataframe, value_mappings):\n    \"\"\"Fold every spelling of a named answer onto its one canonical value.\"\"\"\n    repaired = dataframe.copy()\n    for column_name, value_mapping in value_mappings.items():\n        if column_name not in repaired.columns:\n            continue\n        column = repaired[column_name]\n        given = column.notna()\n        lowered = column[given].astype(str).str.strip().str.lower()\n        unknown = column[given][~lowered.isin(value_mapping.keys())]\n        if len(unknown) > 0:\n            _refuse_values(column_name, unknown)\n        mapped = lowered.map(value_mapping)\n        result = pd.Series(np.nan, index=column.index, dtype=object)\n        result[given] = mapped\n        repaired[column_name] = result\n    return repaired\n\n\ndef convert_application_references(references):\n    \"\"\"Write every application reference as LCT and seven digits.\"\"\"\n    pattern = re.compile(config.APPLICATION_REFERENCE_PATTERN)\n    converted = []\n    unreadable = []\n    for value in references:\n        if _is_blank(value):\n            converted.append(np.nan)\n            continue\n        match = pattern.match(str(value))\n        if match is None:\n            unreadable.append(value)\n            converted.append(np.nan)\n            continue\n        number = match.group(1)\n        converted.append(\n            config.APPLICATION_REFERENCE_PREFIX\n            + number.zfill(config.APPLICATION_REFERENCE_DIGITS)\n        )\n    if unreadable:\n        _refuse_values(references.name, unreadable)\n    return pd.Series(converted, index=references.index, name=references.name, dtype=object)\n\n\ndef refuse_unreadable_identifiers(dataframe, identifier_patterns):\n    \"\"\"Refuse an installer, premises or substation reference in a form no portal uses.\"\"\"\n    for column_name, pattern in identifier_patterns.items():\n        if column_name not in dataframe.columns:\n            continue\n        column = dataframe[column_name]\n        given = column[column.notna()].astype(str)\n        unreadable = given[~given.str.fullmatch(pattern.strip(\"^$\"))]\n        if len(unreadable) > 0:\n            _refuse_values(column_name, unreadable)\n    return dataframe\n\n\ndef convert_whole_numbers(dataframe, number_patterns):\n    \"\"\"Read counts, cut-out ratings and working days as whole numbers.\"\"\"\n    repaired = dataframe.copy()\n    for column_name, pattern in number_patterns.items():\n        if column_name not in repaired.columns:\n            continue\n        compiled = re.compile(pattern)\n        numbers = []\n        unreadable = []\n        for value in repaired[column_name]:\n            if _is_blank(value):\n                numbers.append(pd.NA)\n                continue\n            match = compiled.match(str(value))\n            if match is None:\n                unreadable.append(value)\n                numbers.append(pd.NA)\n                continue\n            numbers.append(int(match.group(1)))\n        if unreadable:\n            _refuse_values(column_name, unreadable)\n        repaired[column_name] = pd.array(numbers, dtype=config.WHOLE_NUMBER_DTYPE)\n    return repaired\n\n\ndef convert_phases(dataframe):\n    \"\"\"Read the supply's and the equipment's phases as 1 or 3.\"\"\"\n    repaired = dataframe.copy()\n    for column_name in config.PHASE_COLUMNS:\n        phases = []\n        unreadable = []\n        for value in repaired[column_name]:\n            if _is_blank(value):\n                phases.append(pd.NA)\n                continue\n            key = str(value).strip().lower()\n            if key not in config.PHASE_MAPPING:\n                unreadable.append(value)\n                phases.append(pd.NA)\n                continue\n            phases.append(config.PHASE_MAPPING[key])\n        if unreadable:\n            _refuse_values(column_name, unreadable)\n        repaired[column_name] = pd.array(phases, dtype=config.WHOLE_NUMBER_DTYPE)\n    return repaired\n\n\ndef treat_impossible_phase_pairs_as_missing(dataframe):\n    \"\"\"Blank the equipment's phases where they exceed the supply's.\"\"\"\n    repaired = dataframe.copy()\n    supply = repaired[config.SUPPLY_PHASES_COLUMN]\n    equipment = repaired[config.EQUIPMENT_PHASES_COLUMN]\n    impossible = (supply.notna() & equipment.notna()).to_numpy(dtype=bool)\n    impossible = impossible & (\n        equipment.astype(\"float64\").to_numpy() > supply.astype(\"float64\").to_numpy()\n    )\n    column = repaired[config.EQUIPMENT_PHASES_COLUMN].copy()\n    column[impossible] = pd.NA\n    repaired[config.EQUIPMENT_PHASES_COLUMN] = column\n    return repaired\n\n\ndef convert_power_to_amps_per_phase(kilowatts, phases):\n    \"\"\"Turn a power in kilowatts into amps per phase, exactly, rounded once half up.\"\"\"\n    amps = (\n        Decimal(kilowatts)\n        * config.WATTS_PER_KILOWATT\n        / config.DECLARED_VOLTS\n        / Decimal(int(phases))\n    )\n    return _round_half_up(amps, config.AMPS_STEP)\n\n\ndef _read_current(value, phases):\n    \"\"\"Read one current as an exact decimal of amps per phase, or None when unconvertible.\n\n    Returns (amps, recognised).\n    \"\"\"\n    text = str(value)\n    amps_match = re.match(config.CURRENT_NOTATIONS[config.AMPS_UNIT], text)\n    if amps_match is not None:\n        return _round_half_up(Decimal(amps_match.group(1)), config.AMPS_STEP), True\n    for notation_name, pattern in config.CURRENT_NOTATIONS.items():\n        if notation_name == config.AMPS_UNIT:\n            continue\n        match = re.match(pattern, text)\n        if match is None:\n            continue\n        number = Decimal(match.group(1).replace(config.THOUSANDS_SEPARATOR, \"\"))\n        kilowatts = number * config.POWER_UNITS[notation_name]\n        if _is_blank(phases):\n            return None, True\n        return convert_power_to_amps_per_phase(kilowatts, int(phases)), True\n    return None, False\n\n\ndef convert_currents(dataframe, current_phases):\n    \"\"\"Read every current, in amps or written as a power, as amps per phase.\"\"\"\n    repaired = dataframe.copy()\n    for column_name, phases_column in current_phases.items():\n        if column_name not in repaired.columns:\n            continue\n        values = []\n        unreadable = []\n        for value, phases in zip(repaired[column_name], repaired[phases_column]):\n            if _is_blank(value):\n                values.append(np.nan)\n                continue\n            amps, recognised = _read_current(value, phases)\n            if not recognised:\n                unreadable.append(value)\n                values.append(np.nan)\n                continue\n            values.append(np.nan if amps is None else float(amps))\n        if unreadable:\n            _refuse_values(column_name, unreadable)\n        repaired[column_name] = pd.Series(values, index=repaired.index, dtype=\"float64\")\n    return repaired\n\n\ndef _read_amount(value, reading):\n    \"\"\"Read one amount with its reading; None when no notation fits.\"\"\"\n    text = str(value)\n    for notation_name, pattern in reading[\"notations\"].items():\n        match = re.match(pattern, text)\n        if match is None:\n            continue\n        number = Decimal(match.group(1).replace(config.THOUSANDS_SEPARATOR, \"\"))\n        return _round_half_up(number * reading[\"units\"][notation_name], reading[\"step\"])\n    return None\n\n\ndef convert_amounts(dataframe, amount_readings):\n    \"\"\"Read powers, power factors and resistances in every notation a portal writes.\"\"\"\n    repaired = dataframe.copy()\n    for column_name, reading in amount_readings.items():\n        if column_name not in repaired.columns:\n            continue\n        values = []\n        unreadable = []\n        for value in repaired[column_name]:\n            if _is_blank(value):\n                values.append(np.nan)\n                continue\n            amount = _read_amount(value, reading)\n            if amount is None:\n                unreadable.append(value)\n                values.append(np.nan)\n                continue\n            values.append(float(amount))\n        if unreadable:\n            _refuse_values(column_name, unreadable)\n        repaired[column_name] = pd.Series(values, index=repaired.index, dtype=\"float64\")\n    return repaired\n\n\ndef treat_values_below_minimum_as_missing(dataframe, minimum_values):\n    \"\"\"Blank readings below the least value that can be true.\"\"\"\n    repaired = dataframe.copy()\n    for column_name, minimum in minimum_values.items():\n        if column_name not in repaired.columns:\n            continue\n        column = repaired[column_name].copy()\n        below = (column.notna() & (column.astype(\"float64\") < float(minimum))).to_numpy(\n            dtype=bool\n        )\n        column[below] = pd.NA if str(column.dtype) == config.WHOLE_NUMBER_DTYPE else np.nan\n        repaired[column_name] = column\n    return repaired\n\n\ndef treat_values_above_maximum_as_missing(dataframe, maximum_values):\n    \"\"\"Blank readings above the greatest value that can be true.\"\"\"\n    repaired = dataframe.copy()\n    for column_name, maximum in maximum_values.items():\n        if column_name not in repaired.columns:\n            continue\n        column = repaired[column_name].copy()\n        above = (column.notna() & (column.astype(\"float64\") > float(maximum))).to_numpy(\n            dtype=bool\n        )\n        column[above] = pd.NA if str(column.dtype) == config.WHOLE_NUMBER_DTYPE else np.nan\n        repaired[column_name] = column\n    return repaired\n\n\ndef treat_values_outside_sizes_as_missing(dataframe, allowed_sizes):\n    \"\"\"Blank readings that are none of the sizes that exist.\"\"\"\n    repaired = dataframe.copy()\n    for column_name, sizes in allowed_sizes.items():\n        if column_name not in repaired.columns:\n            continue\n        column = repaired[column_name].copy()\n        given = column.notna().to_numpy(dtype=bool)\n        numbers = column.astype(\"float64\").to_numpy()\n        outside = given & ~np.isin(numbers, [float(size) for size in sizes])\n        column[outside] = pd.NA if str(column.dtype) == config.WHOLE_NUMBER_DTYPE else np.nan\n        repaired[column_name] = column\n    return repaired\n\n\ndef keep_latest_revision_of_each_application(dataframe):\n    \"\"\"Keep each application once, as its highest revision, in table order.\"\"\"\n    reference_column = config.APPLICATION_REFERENCE_COLUMN\n    revision_column = config.REVISION_NUMBER_COLUMN\n    references = dataframe[reference_column]\n    revisions = dataframe[revision_column]\n    blank = (references.isna() | revisions.isna()).to_numpy(dtype=bool)\n    if blank.any():\n        named = sorted({str(value) for value in references[blank].fillna(\"(no reference)\")})\n        raise ValueError(\n            \"Applications \" + \", \".join(named) + f\" leave {reference_column} or \"\n            f\"{revision_column} blank, so their latest revision cannot be found\"\n        )\n    repeated = dataframe.duplicated([reference_column, revision_column], keep=False)\n    if repeated.any():\n        named = sorted({str(value) for value in references[repeated]})\n        raise ValueError(\n            \"Applications \" + \", \".join(named) + f\" give two rows at the same {revision_column}\"\n        )\n    revision_numbers = revisions.astype(\"int64\")\n    latest = revision_numbers.groupby(references).transform(\"max\")\n    kept = (revision_numbers == latest).to_numpy(dtype=bool)\n    return dataframe[kept].reset_index(drop=True)\n\n\ndef _plain_text(text):\n    without_tags = re.sub(config.MARKUP_PATTERN, \" \", text)\n    unescaped = html.unescape(without_tags)\n    return re.sub(config.WHITESPACE_RUN_PATTERN, \" \", unescaped).strip()\n\n\ndef convert_markup_to_plain_text(texts):\n    \"\"\"Recover the words a writer meant from text with markup and escaped characters.\"\"\"\n    return texts.map(lambda value: value if _is_blank(value) else _plain_text(str(value)))\n\n\ndef _statement_text(value):\n    if _is_blank(value):\n        return value\n    plain = _plain_text(str(value))\n    return plain.lower() if plain.isupper() else plain\n\n\ndef clean_statement_text(texts):\n    \"\"\"Plain words, and a text written wholly in capitals put in small letters.\"\"\"\n    return texts.map(_statement_text)\n"}, {"path": "data_pipeline/application_cleaning.py", "explain": "read_application_answers applies every reading of a form; clean_application_records removes exact repeats, reads every answer, blanks impossible readings and keeps each application once at its highest revision. Shared by the history and the live queue.", "code": "\"\"\"The repairs an application's form needs, shared by the history and the live queue.\"\"\"\n\nfrom config import config\nfrom data_pipeline.common_cleaning import (\n    convert_amounts,\n    convert_application_references,\n    convert_currents,\n    convert_phases,\n    convert_whole_numbers,\n    keep_latest_revision_of_each_application,\n    normalize_category_values,\n    refuse_unreadable_identifiers,\n    remove_duplicate_records,\n    treat_impossible_phase_pairs_as_missing,\n    treat_values_above_maximum_as_missing,\n    treat_values_below_minimum_as_missing,\n    treat_values_outside_sizes_as_missing,\n)\n\n\ndef read_application_answers(frame, value_mappings, whole_number_patterns):\n    \"\"\"Read every answer on a form as the Connection Rules read it; no row is removed.\"\"\"\n    forms = normalize_category_values(frame, value_mappings)\n    forms[config.APPLICATION_REFERENCE_COLUMN] = convert_application_references(\n        forms[config.APPLICATION_REFERENCE_COLUMN]\n    )\n    forms = refuse_unreadable_identifiers(forms, config.FORM_IDENTIFIER_PATTERNS)\n    forms = convert_whole_numbers(forms, whole_number_patterns)\n    forms = convert_phases(forms)\n    forms = treat_impossible_phase_pairs_as_missing(forms)\n    forms = convert_currents(forms, config.FORM_CURRENT_PHASES)\n    forms = convert_amounts(forms, config.FORM_AMOUNT_READINGS)\n    return forms\n\n\ndef clean_application_records(frame, value_mappings, whole_number_patterns):\n    \"\"\"Turn raw application forms into one clean row per application.\"\"\"\n    forms = remove_duplicate_records(frame)\n    forms = read_application_answers(forms, value_mappings, whole_number_patterns)\n    forms = treat_values_below_minimum_as_missing(forms, config.FORM_MINIMUM_VALUES)\n    forms = treat_values_above_maximum_as_missing(forms, config.FORM_MAXIMUM_VALUES)\n    forms = treat_values_outside_sizes_as_missing(forms, config.FORM_ALLOWED_SIZES)\n    return keep_latest_revision_of_each_application(forms)\n"}, {"path": "data_pipeline/document_cleaning.py", "explain": "clean_document_records - for sentences and live statements: drop repeats, refuse missing ids/references and repeated ids, canonical categories and references, whole numbers, and plain statement text.", "code": "\"\"\"Cleaning shared by the past statement sentences and the live statements.\"\"\"\n\nfrom config import config\nfrom data_pipeline.common_cleaning import (\n    clean_statement_text,\n    convert_application_references,\n    convert_whole_numbers,\n    normalize_category_values,\n    refuse_missing_values,\n    refuse_repeated_references,\n    remove_duplicate_records,\n)\n\n\ndef clean_document_records(frame, value_mappings, whole_number_patterns, id_column,\n                           text_column):\n    \"\"\"Clean the rows of statements, whether past sentences or live statements.\"\"\"\n    rows = remove_duplicate_records(frame)\n    rows = refuse_missing_values(rows, [id_column, config.APPLICATION_REFERENCE_COLUMN])\n    rows = refuse_repeated_references(rows, id_column)\n    rows = normalize_category_values(rows, value_mappings)\n    rows[config.APPLICATION_REFERENCE_COLUMN] = convert_application_references(\n        rows[config.APPLICATION_REFERENCE_COLUMN]\n    )\n    rows = convert_whole_numbers(rows, whole_number_patterns)\n    rows[text_column] = clean_statement_text(rows[text_column])\n    return rows\n"}], "commands": "git config pull.rebase false\ngit pull origin main\nmkdir -p data_pipeline\n# paste today's files, then:\ngit add data_pipeline/dataset_loader.py data_pipeline/common_cleaning.py data_pipeline/application_cleaning.py data_pipeline/document_cleaning.py\ngit commit -m \"Day 1 (ML): Raw loader and every shared repair; forms and statements cleaned\"\ngit push origin HEAD", "demo": "python - <<'EOF'\nfrom config import config\nfrom data_pipeline.dataset_loader import load_raw_dataset\nfrom data_pipeline.application_cleaning import clean_application_records\nraw = load_raw_dataset(config.OPEN_APPLICATIONS_FILE)\nclean = clean_application_records(raw, config.FORM_VALUE_MAPPINGS, config.LIVE_WHOLE_NUMBER_PATTERNS)\nprint(len(raw), \"raw rows ->\", len(clean), \"open applications\")\nprint(clean[[\"application_reference\", \"technology\", \"supply_phases\", \"rated_current_amps\"]].head(8))\nEOF", "show": "The live file arrives in three reference notations with kW/kVA ratings and duplicate rows; after cleaning there are 40 applications, every reference is LCT + 7 digits, phases are 1 or 3 and currents are amps per phase (e.g. 4600W single phase becomes 20.0)."}]}, {"n": 2, "title": "Data pipeline, standards and screening", "goal": "Clean all five extracts with the quality report, read every technology's requirements from its own standard, screen applications against them, and load the live queue.", "check": "python run_data_pipeline.py", "order": null, "tasks": [{"owner": "yashwanth", "summary": "Live queue, statements, history, fetch and queue ranking.", "files": [{"path": "tools/application_data_tools.py", "explain": "Reads the live queue (open_applications.csv) and its statements through the same cleaning as the history, loads the connection history, fetches one application as a plain dict (blanks = None), lists its statements in document_id order, ranks the queue (heat pumps on failed heating first) and words a record for prompts and pages.", "code": "\"\"\"Reads the live queue, its statements and the connection history, one application at a time.\"\"\"\n\nimport numpy as np\nimport pandas as pd\n\nfrom config import config\nfrom data_pipeline.application_cleaning import clean_application_records\nfrom data_pipeline.dataset_loader import load_processed_dataset, load_raw_dataset\nfrom data_pipeline.document_cleaning import clean_document_records\n\n\ndef _plain(value):\n    \"\"\"A table cell as a plain Python value, a blank as None.\"\"\"\n    if value is None or value is pd.NA:\n        return None\n    if isinstance(value, float) and np.isnan(value):\n        return None\n    if isinstance(value, np.bool_):\n        return bool(value)\n    if isinstance(value, np.integer):\n        return int(value)\n    if isinstance(value, np.floating):\n        return None if np.isnan(value) else float(value)\n    try:\n        if pd.isna(value):\n            return None\n    except (TypeError, ValueError):\n        pass\n    return value\n\n\ndef load_open_applications():\n    \"\"\"The live queue, read through the same cleaning as the history.\"\"\"\n    return clean_application_records(\n        load_raw_dataset(config.OPEN_APPLICATIONS_FILE),\n        config.FORM_VALUE_MAPPINGS,\n        config.LIVE_WHOLE_NUMBER_PATTERNS,\n    )\n\n\ndef load_application_documents():\n    \"\"\"The statements attached to the open applications.\"\"\"\n    return clean_document_records(\n        load_raw_dataset(config.APPLICATION_DOCUMENTS_FILE),\n        config.DOCUMENT_VALUE_MAPPINGS,\n        config.DOCUMENT_WHOLE_NUMBER_PATTERNS,\n        config.DOCUMENT_ID_COLUMN,\n        config.DOCUMENT_TEXT_COLUMN,\n    )\n\n\ndef load_connection_history():\n    \"\"\"Every application already connected: the cleaned training then held-out history.\"\"\"\n    return pd.concat(\n        [\n            load_processed_dataset(config.CLEAN_APPLICATION_HISTORY_TRAIN_FILE),\n            load_processed_dataset(config.CLEAN_APPLICATION_HISTORY_EVAL_FILE),\n        ],\n        ignore_index=True,\n    )\n\n\ndef fetch_application(applications, application_reference):\n    \"\"\"One application's own answers, column by column, a blank as None.\"\"\"\n    rows = applications[applications[config.APPLICATION_REFERENCE_COLUMN] == application_reference]\n    if len(rows) == 0:\n        raise ValueError(\n            config.UNKNOWN_APPLICATION_MESSAGE.format(application_reference=application_reference)\n        )\n    row = rows.iloc[0]\n    return {str(column_name): _plain(row[column_name]) for column_name in applications.columns}\n\n\ndef fetch_application_documents(documents, application):\n    \"\"\"The statements attached to one application, in document identifier order.\"\"\"\n    reference = application[config.APPLICATION_REFERENCE_COLUMN]\n    attached = documents[documents[config.APPLICATION_REFERENCE_COLUMN] == reference]\n    attached = attached.sort_values(config.DOCUMENT_ID_COLUMN, kind=\"stable\")\n    return [\n        {str(column_name): _plain(value) for column_name, value in record.items()}\n        for record in attached.to_dict(\"records\")\n    ]\n\n\ndef rank_application_queue(applications):\n    \"\"\"Heat pumps replacing failed heating first, then the rest, each by reference.\"\"\"\n    first, rest = [], []\n    for record in applications.to_dict(\"records\"):\n        reference = record[config.APPLICATION_REFERENCE_COLUMN]\n        heat_pump = record.get(config.TECHNOLOGY_COLUMN) == config.HEAT_PUMP\n        failed = record.get(config.URGENCY_COLUMN) == config.URGENCY_HEATING_FAILED\n        (first if heat_pump and failed else rest).append(reference)\n    return sorted(first) + sorted(rest)\n\n\ndef _describe_value(value):\n    plain = _plain(value)\n    if plain is None:\n        return config.NOT_GIVEN_TEXT\n    if isinstance(plain, bool):\n        return str(plain)\n    if isinstance(plain, int):\n        return f\"{plain:,}\"\n    if isinstance(plain, float) and plain.is_integer():\n        return f\"{int(plain):,}\"\n    return str(plain)\n\n\ndef describe_record(record):\n    \"\"\"A record in the words a page and a prompt show: every value as text.\"\"\"\n    return {key: _describe_value(value) for key, value in record.items()}\n"}], "commands": "git pull origin main\nmkdir -p tools\n# paste today's files, then:\ngit add tools/application_data_tools.py\ngit commit -m \"Day 2 (FastAPI): Live queue, statements, history, fetch and queue ranking\"\ngit push origin HEAD", "demo": "python - <<'EOF'\nfrom tools.application_data_tools import (load_open_applications, load_application_documents,\n    rank_application_queue, fetch_application, fetch_application_documents, describe_record)\napplications = load_open_applications()\ndocuments = load_application_documents()\nprint(len(applications), \"open applications,\", len(documents), \"statements\")\nqueue = rank_application_queue(applications)\nprint(\"queue starts:\", queue[:6])\nfirst = fetch_application(applications, queue[0])\nprint(describe_record(first)[\"technology\"], describe_record(first)[\"urgency\"],\n      len(fetch_application_documents(documents, first)), \"statements attached\")\nEOF", "show": "40 open applications and 102 statements, read through the same cleaning as the history. The queue opens with heat pumps whose heating failed, then everything else, each group by reference."}, {"owner": "yash", "summary": "Met / Not met / Not documented, network triggers, assessment; notice details.", "files": [{"path": "tools/screening_tools.py", "explain": "The heart of the Connection Rules. find_network_triggers finds looped service, supply capacity and generation triggers (blanks always count against the application). screen_application judges every requirement of the application's own standard as Met / Not met / Not documented with exact Decimals, names the blank answers, and gives counts, rating_stated, assessment and decisions_open.", "code": "\"\"\"Screens an application's form against its own standard and the network triggers.\"\"\"\n\nfrom decimal import Decimal\n\nimport pandas as pd\n\nfrom config import config\nfrom data_pipeline.common_cleaning import convert_power_to_amps_per_phase\n\n\ndef _is_blank(value):\n    if value is None or value is pd.NA:\n        return True\n    try:\n        return bool(pd.isna(value))\n    except (TypeError, ValueError):\n        return False\n\n\ndef _answer(application, column_name):\n    \"\"\"The form's answer, or None when blank.\"\"\"\n    value = application.get(column_name)\n    return None if _is_blank(value) else value\n\n\ndef _decimal(value):\n    \"\"\"An answer as an exact decimal, read from its shortest written form.\"\"\"\n    if isinstance(value, Decimal):\n        return value\n    if isinstance(value, (int,)) and not isinstance(value, bool):\n        return Decimal(value)\n    return Decimal(repr(float(value))) if not isinstance(value, str) else Decimal(value)\n\n\ndef find_network_triggers(application):\n    \"\"\"Name every network trigger of the Low-Carbon Connections Policy the application meets.\"\"\"\n    technology = _answer(application, config.TECHNOLOGY_COLUMN)\n    if technology not in config.CONNECTION_STANDARD_DOCUMENTS:\n        raise ValueError(\n            config.UNKNOWN_TECHNOLOGY_MESSAGE.format(\n                application_reference=application.get(config.APPLICATION_REFERENCE_COLUMN),\n                technology=technology,\n            )\n        )\n    triggers = []\n\n    looped = _answer(application, config.LOOPED_SERVICE_COLUMN)\n    if looped is None or looped == config.BOOLEAN_YES:\n        triggers.append(config.LOOPED_SERVICE_TRIGGER)\n\n    if _supply_capacity_reached(application):\n        triggers.append(config.SUPPLY_CAPACITY_TRIGGER)\n\n    if technology in config.GENERATING_TECHNOLOGIES and _generation_above_notify_limit(\n        application\n    ):\n        triggers.append(config.GENERATION_TRIGGER)\n    return triggers\n\n\ndef _demand_that_counts(application):\n    \"\"\"The demand the supply capacity trigger is judged on, or None when blank.\"\"\"\n    limiter = _answer(application, config.LOAD_LIMITER_FITTED_COLUMN)\n    demand = _answer(application, config.MAXIMUM_DEMAND_COLUMN)\n    setting = _answer(application, config.LOAD_LIMITER_SETTING_COLUMN)\n    if limiter == config.BOOLEAN_YES:\n        return None if setting is None else _decimal(setting)\n    if limiter == config.BOOLEAN_NO:\n        return None if demand is None else _decimal(demand)\n    if demand is None or setting is None:\n        return None if demand is None else _decimal(demand)\n    return max(_decimal(demand), _decimal(setting))\n\n\ndef _supply_capacity_reached(application):\n    cut_out = _answer(application, config.CUT_OUT_RATING_COLUMN)\n    demand = _demand_that_counts(application)\n    if cut_out is None or demand is None:\n        return True\n    return demand >= _decimal(cut_out) or demand > config.SUPPLY_MAXIMUM_AMPS\n\n\ndef _generation_above_notify_limit(application):\n    inverter = _answer(application, config.INVERTER_CAPACITY_COLUMN)\n    existing = _answer(application, config.EXISTING_GENERATION_COLUMN)\n    phases = _answer(application, config.EQUIPMENT_PHASES_COLUMN)\n    if inverter is None or existing is None or phases is None:\n        return True\n    capacity_amps = convert_power_to_amps_per_phase(\n        _decimal(inverter) + _decimal(existing), int(phases)\n    )\n    if capacity_amps <= config.NOTIFY_GENERATION_AMPS:\n        return False\n    fitted = _answer(application, config.EXPORT_LIMITATION_FITTED_COLUMN)\n    certified = _answer(application, config.EXPORT_SCHEME_CERTIFIED_COLUMN)\n    export_limit = _answer(application, config.EXPORT_LIMIT_COLUMN)\n    if (\n        fitted == config.BOOLEAN_YES\n        and certified == config.BOOLEAN_YES\n        and export_limit is not None\n        and capacity_amps <= config.FAST_TRACK_GENERATION_AMPS\n    ):\n        export_amps = convert_power_to_amps_per_phase(_decimal(export_limit), int(phases))\n        if export_amps <= config.NOTIFY_GENERATION_AMPS:\n            return False\n    return True\n\n\ndef _judge_yes_or_no(application, column_name):\n    answer = _answer(application, column_name)\n    if answer is None:\n        return config.REQUIREMENT_NOT_DOCUMENTED, [column_name]\n    if answer == config.BOOLEAN_YES:\n        return config.REQUIREMENT_MET, []\n    return config.REQUIREMENT_NOT_MET, []\n\n\ndef _judge_maximum(application, column_name, maximum):\n    answer = _answer(application, column_name)\n    if answer is None:\n        return config.REQUIREMENT_NOT_DOCUMENTED, [column_name]\n    if _decimal(answer) <= maximum:\n        return config.REQUIREMENT_MET, []\n    return config.REQUIREMENT_NOT_MET, []\n\n\ndef _judge_power_factor(application, minimum):\n    answer = _answer(application, config.POWER_FACTOR_COLUMN)\n    if answer is None:\n        return config.REQUIREMENT_NOT_DOCUMENTED, [config.POWER_FACTOR_COLUMN]\n    if _decimal(answer) >= minimum:\n        return config.REQUIREMENT_MET, []\n    return config.REQUIREMENT_NOT_MET, []\n\n\ndef _judge_earthing(application, maximum_ohms):\n    arrangement = _answer(application, config.EARTHING_ARRANGEMENT_COLUMN)\n    if arrangement is None:\n        return config.REQUIREMENT_NOT_DOCUMENTED, [config.EARTHING_ARRANGEMENT_COLUMN]\n    if arrangement == config.EARTHING_TN_S:\n        return config.REQUIREMENT_MET, []\n    if arrangement == config.EARTHING_TN_C_S:\n        return _judge_yes_or_no(application, config.OPEN_PEN_PROTECTION_COLUMN)\n    return _judge_maximum(application, config.EARTH_ELECTRODE_COLUMN, maximum_ohms)\n\n\ndef _judge_export_limitation(application, maximum_amps):\n    fitted = _answer(application, config.EXPORT_LIMITATION_FITTED_COLUMN)\n    if fitted is None:\n        return config.REQUIREMENT_NOT_DOCUMENTED, [config.EXPORT_LIMITATION_FITTED_COLUMN]\n    if fitted == config.BOOLEAN_NO:\n        return config.REQUIREMENT_MET, []\n    certified = _answer(application, config.EXPORT_SCHEME_CERTIFIED_COLUMN)\n    export_limit = _answer(application, config.EXPORT_LIMIT_COLUMN)\n    phases = _answer(application, config.EQUIPMENT_PHASES_COLUMN)\n    if certified == config.BOOLEAN_NO:\n        return config.REQUIREMENT_NOT_MET, []\n    if export_limit is not None and phases is not None:\n        export_amps = convert_power_to_amps_per_phase(_decimal(export_limit), int(phases))\n        if export_amps > maximum_amps:\n            return config.REQUIREMENT_NOT_MET, []\n    blanks = []\n    if certified is None:\n        blanks.append(config.EXPORT_SCHEME_CERTIFIED_COLUMN)\n    if export_limit is None:\n        blanks.append(config.EXPORT_LIMIT_COLUMN)\n    elif phases is None:\n        blanks.append(config.EQUIPMENT_PHASES_COLUMN)\n    if blanks:\n        return config.REQUIREMENT_NOT_DOCUMENTED, blanks\n    return config.REQUIREMENT_MET, []\n\n\ndef _judge_requirement(application, requirement, document_name):\n    kind = requirement[\"requirement_kind\"]\n    rules = requirement.get(\"rules\") or {}\n    if kind in config.YES_OR_NO_REQUIREMENT_ANSWERS:\n        return _judge_yes_or_no(application, config.YES_OR_NO_REQUIREMENT_ANSWERS[kind])\n    if kind in config.CURRENT_REQUIREMENT_ANSWERS:\n        return _judge_maximum(\n            application,\n            config.CURRENT_REQUIREMENT_ANSWERS[kind],\n            Decimal(rules[config.MAXIMUM_AMPS_RULE]),\n        )\n    if kind == config.POWER_FACTOR_REQUIREMENT:\n        return _judge_power_factor(\n            application, Decimal(rules[config.MINIMUM_POWER_FACTOR_RULE])\n        )\n    if kind == config.EARTHING_PROTECTION_REQUIREMENT:\n        return _judge_earthing(application, Decimal(rules[config.MAXIMUM_OHMS_RULE]))\n    if kind == config.EXPORT_LIMITATION_REQUIREMENT:\n        return _judge_export_limitation(application, Decimal(rules[config.MAXIMUM_AMPS_RULE]))\n    raise ValueError(\n        f\"{document_name} states a requirement of the kind {kind}, which the screening \"\n        \"does not know\"\n    )\n\n\ndef screen_application(application, standard):\n    \"\"\"Screen a form against every requirement of its standard and the network triggers.\"\"\"\n    application_reference = application.get(config.APPLICATION_REFERENCE_COLUMN)\n    technology = _answer(application, config.TECHNOLOGY_COLUMN)\n    if standard.get(\"technology\") != technology:\n        raise ValueError(\n            config.STANDARD_OF_ANOTHER_TECHNOLOGY_MESSAGE.format(\n                application_reference=application_reference,\n                technology=technology,\n                document_name=standard.get(\"document_name\"),\n            )\n        )\n    document_name = standard.get(\"document_name\")\n    requirements = []\n    for requirement in standard[\"requirements\"]:\n        result, blank_answers = _judge_requirement(application, requirement, document_name)\n        requirements.append(\n            {\n                \"requirement_kind\": requirement[\"requirement_kind\"],\n                \"requirement_name\": requirement[\"requirement_name\"],\n                \"requirement_sentence\": requirement[\"requirement_sentence\"],\n                \"rules\": dict(requirement.get(\"rules\") or {}),\n                \"result\": result,\n                \"blank_answers\": blank_answers,\n            }\n        )\n    counts = {\n        column_name: sum(1 for requirement in requirements if requirement[\"result\"] == result)\n        for column_name, result in config.REQUIREMENT_COUNT_RESULTS.items()\n    }\n    network_triggers = find_network_triggers(application)\n    rating_stated = _answer(application, config.RATING_COLUMNS[technology]) is not None\n    if counts[config.REQUIREMENTS_MET_COUNT_COLUMN] != len(requirements) or not rating_stated:\n        assessment = config.DECISION_RETURN\n    elif network_triggers:\n        assessment = config.DECISION_REFER\n    else:\n        assessment = config.DECISION_APPROVE\n    screening = {\n        \"application_reference\": application_reference,\n        \"technology\": technology,\n        \"standard_document\": document_name,\n        \"requirements\": requirements,\n    }\n    screening.update(counts)\n    screening.update(\n        {\n            \"network_triggers\": network_triggers,\n            \"rating_stated\": rating_stated,\n            \"assessment\": assessment,\n            \"decisions_open\": list(config.DECISIONS_OPEN[assessment]),\n        }\n    )\n    return screening\n"}, {"path": "tools/notice_tools.py", "explain": "Builds, by code, every detail the notices carry: approval details (reference, standard, technology, phases, earthing, rating, export limit / limiter setting), household notice details, rework details (every requirement to put right with its form answers) and the assessment brief for Network Planning. A screening of another application is refused.", "code": "\"\"\"The details the notices and the assessment brief carry, taken from the record by code.\"\"\"\n\nimport pandas as pd\n\nfrom config import config\n\n\ndef _answer(application, column_name):\n    value = application.get(column_name)\n    if value is None or value is pd.NA:\n        return None\n    try:\n        if pd.isna(value):\n            return None\n    except (TypeError, ValueError):\n        pass\n    return value\n\n\ndef _refuse_other_screening(application, screening):\n    application_reference = application.get(config.APPLICATION_REFERENCE_COLUMN)\n    if screening.get(\"application_reference\") != application_reference:\n        raise ValueError(\n            config.SCREENING_OF_ANOTHER_APPLICATION_MESSAGE.format(\n                screening_reference=screening.get(\"application_reference\"),\n                application_reference=application_reference,\n            )\n        )\n\n\ndef _conditions(application, technology):\n    conditions = {}\n    for column_name in config.APPROVAL_CONDITION_COLUMNS.get(technology, []):\n        value = _answer(application, column_name)\n        if value is not None:\n            conditions[column_name] = value\n    return conditions\n\n\ndef build_approval_details(application, screening):\n    \"\"\"The details a connection approval shows, as each standard's section 7 sets out.\"\"\"\n    _refuse_other_screening(application, screening)\n    technology = screening[\"technology\"]\n    details = {\n        config.APPLICATION_REFERENCE_COLUMN: application.get(config.APPLICATION_REFERENCE_COLUMN),\n        \"standard_document\": screening[\"standard_document\"],\n    }\n    for column_name in config.APPROVAL_DETAIL_COLUMNS:\n        details[column_name] = _answer(application, column_name)\n    rating_column = config.RATING_COLUMNS[technology]\n    details[rating_column] = _answer(application, rating_column)\n    details.update(_conditions(application, technology))\n    return details\n\n\ndef build_household_notice_details(application, screening):\n    \"\"\"The only facts a household notice may rest on.\"\"\"\n    _refuse_other_screening(application, screening)\n    technology = screening[\"technology\"]\n    rating_column = config.RATING_COLUMNS[technology]\n    details = {\n        config.TECHNOLOGY_COLUMN: technology,\n        rating_column: _answer(application, rating_column),\n    }\n    details.update(_conditions(application, technology))\n    return details\n\n\ndef build_rework_details(application, screening, documentation_to_provide, disagreements):\n    \"\"\"Everything a rework request must name.\"\"\"\n    _refuse_other_screening(application, screening)\n    to_put_right = []\n    for requirement in screening[\"requirements\"]:\n        if requirement[\"result\"] == config.REQUIREMENT_MET:\n            continue\n        to_put_right.append(\n            {\n                \"requirement_name\": requirement[\"requirement_name\"],\n                \"requirement_sentence\": requirement[\"requirement_sentence\"],\n                \"result\": requirement[\"result\"],\n                \"form_answers\": {\n                    column_name: _answer(application, column_name)\n                    for column_name in config.REQUIREMENT_ANSWER_COLUMNS[\n                        requirement[\"requirement_kind\"]\n                    ]\n                },\n                \"blank_answers\": list(requirement[\"blank_answers\"]),\n            }\n        )\n    blank_rating = None\n    if not screening[\"rating_stated\"]:\n        blank_rating = config.RATING_COLUMNS[screening[\"technology\"]]\n    return {\n        config.APPLICATION_REFERENCE_COLUMN: application.get(config.APPLICATION_REFERENCE_COLUMN),\n        \"technology\": screening[\"technology\"],\n        \"standard_document\": screening[\"standard_document\"],\n        \"requirements_to_put_right\": to_put_right,\n        \"blank_rating_answer\": blank_rating,\n        \"documentation_to_provide\": documentation_to_provide,\n        \"flagged_statements\": list(disagreements),\n    }\n\n\ndef build_assessment_brief(application, screening, likelihood, duration, disagreements):\n    \"\"\"The brief Network Planning receives with a referred application.\"\"\"\n    _refuse_other_screening(application, screening)\n    brief = {\n        config.APPLICATION_REFERENCE_COLUMN: application.get(config.APPLICATION_REFERENCE_COLUMN),\n        \"technology\": screening[\"technology\"],\n        \"standard_document\": screening[\"standard_document\"],\n    }\n    for column_name in config.ASSESSMENT_BRIEF_DETAIL_COLUMNS:\n        brief[column_name] = _answer(application, column_name)\n    brief.update(\n        {\n            \"requirements\": [\n                {\n                    \"requirement_name\": requirement[\"requirement_name\"],\n                    \"result\": requirement[\"result\"],\n                    \"blank_answers\": list(requirement[\"blank_answers\"]),\n                }\n                for requirement in screening[\"requirements\"]\n            ],\n            \"network_triggers\": list(screening[\"network_triggers\"]),\n            \"flagged_statements\": list(disagreements),\n            \"network_work_likelihood\": likelihood[\"network_work_likelihood\"],\n            \"likelihood_band\": likelihood[\"likelihood_band\"],\n            \"expected_working_days\": duration[\"expected_working_days\"],\n            \"planned_working_days\": duration[\"planned_working_days\"],\n            \"delay_expected\": duration[\"delay_expected\"],\n        }\n    )\n    return brief\n"}], "commands": "git pull origin main\nmkdir -p tools\n# paste today's files, then:\ngit add tools/screening_tools.py tools/notice_tools.py\ngit commit -m \"Day 2 (LangGraph): Met / Not met / Not documented, network triggers, assessment; notice details\"\ngit push origin HEAD", "demo": "python - <<'EOF'\nfrom decimal import Decimal\nfrom config import config\nfrom tools.screening_tools import screen_application\nstandard = {\"technology\": \"HP\", \"document_name\": \"Worked-Example-Standard.pdf\", \"requirements\": [\n    {\"requirement_kind\": \"rated_current\", \"requirement_name\": \"Rated current\",\n     \"requirement_sentence\": \"The rated current is at most 20 amps per phase.\", \"rules\": {\"maximum_amps\": Decimal(\"20\")}},\n    {\"requirement_kind\": \"power_factor\", \"requirement_name\": \"Power factor\",\n     \"requirement_sentence\": \"The power factor is at least 0.90 at full load.\", \"rules\": {\"minimum_power_factor\": Decimal(\"0.90\")}},\n    {\"requirement_kind\": \"earthing_protection\", \"requirement_name\": \"Earthing protection\",\n     \"requirement_sentence\": \"On a PME earth ... at most 200 ohms.\", \"rules\": {\"maximum_ohms\": Decimal(\"200\")}}]}\napplication = {\"application_reference\": \"LCT0041999\", \"technology\": \"HP\", \"supply_phases\": 1,\n    \"equipment_phases\": 1, \"rated_current_amps\": 20.0, \"power_factor\": 0.895,\n    \"earthing_arrangement\": \"TT\", \"earth_electrode_ohms\": None, \"looped_service\": \"No\",\n    \"cut_out_rating_amps\": None, \"max_demand_after_connection_amps\": 45.0, \"load_limiter_fitted\": \"No\"}\nscreening = screen_application(application, standard)\nfor requirement in screening[\"requirements\"]:\n    print(requirement[\"requirement_name\"], \"->\", requirement[\"result\"], requirement[\"blank_answers\"])\nprint(\"triggers:\", screening[\"network_triggers\"], \"| assessment:\", screening[\"assessment\"])\nEOF", "show": "The Connection Rules' worked example: 20.0 A is exactly at the limit -> Met; 0.895 < 0.90 -> Not met; TT earth with no resistance -> Not documented asking only for the resistance; the unknown cut-out counts as reached so the supply capacity trigger applies, but the assessment is RETURN TO INSTALLER because requirements come first."}, {"owner": "janavi", "summary": "Requirements read from each standard's own PDF; the Chroma store.", "files": [{"path": "knowledge/standard_reading.py", "explain": "read_connection_standard reads a technology's requirements from its OWN standard only: section 2 must state its code once, section 4 must match the requirements layout, the requirements must be numbered 1..n, and each one must fit exactly one sentence form. Figures (amps, power factor, ohms) come back as exact Decimals - nothing is hard-coded.", "code": "\"\"\"Reads a technology's requirements out of that technology's own connection standard.\n\nNo requirement and no figure is written into the code: everything comes from\nsection 4 of the standard's own document, read at run time.\n\"\"\"\n\nimport re\nfrom decimal import Decimal\n\nfrom config import config\nfrom knowledge.chunk_splitting import split_documents_into_sections\n\nFIGURE_PARTS = [\n    config.MAXIMUM_AMPS_RULE,\n    config.MINIMUM_POWER_FACTOR_RULE,\n    config.MAXIMUM_OHMS_RULE,\n]\n\n\ndef _own_document(technology, document_entries):\n    document_name = config.CONNECTION_STANDARD_DOCUMENTS[technology]\n    matching = [entry for entry in document_entries if entry[\"document_name\"] == document_name]\n    if len(matching) != 1:\n        raise ValueError(\n            f\"{document_name} appears {len(matching)} times among the documents read, \"\n            \"where the standard is read from exactly one\"\n        )\n    return document_name, matching[0]\n\n\ndef _section(sections, number, document_name):\n    found = [section for section in sections if section[\"section_number\"] == number]\n    if len(found) != 1:\n        raise ValueError(f\"{document_name} has no section {number} to read the standard from\")\n    return found[0][\"section_text\"]\n\n\ndef _read_requirement(piece, document_name):\n    fitting = []\n    for kind, pattern in config.REQUIREMENT_SENTENCE_PATTERNS.items():\n        match = re.fullmatch(pattern, piece)\n        if match is not None:\n            fitting.append((kind, match))\n    if len(fitting) != 1:\n        raise ValueError(\n            f\"{document_name} states a requirement no single form of the Connection Rules \"\n            f\"reads: {piece}\"\n        )\n    kind, match = fitting[0]\n    parts = match.groupdict()\n    rules = {\n        part: Decimal(parts[part]) for part in FIGURE_PARTS if parts.get(part) is not None\n    }\n    return {\n        \"requirement_kind\": kind,\n        \"requirement_name\": parts[config.REQUIREMENT_NAME_PART],\n        \"requirement_sentence\": parts[config.REQUIREMENT_SENTENCE_PART],\n        \"rules\": rules,\n    }\n\n\ndef read_connection_standard(technology, document_entries):\n    \"\"\"Every requirement of one technology, with its own figures, from its own standard.\"\"\"\n    if technology not in config.CONNECTION_STANDARD_DOCUMENTS:\n        raise ValueError(config.NO_STANDARD_CONFIGURED_MESSAGE.format(technology=technology))\n    document_name, entry = _own_document(technology, document_entries)\n    sections = split_documents_into_sections([entry])\n\n    technology_text = _section(sections, config.TECHNOLOGY_SECTION_NUMBER, document_name)\n    codes = re.findall(config.TECHNOLOGY_CODE_PATTERN, technology_text)\n    if codes != [technology]:\n        raise ValueError(\n            f\"{document_name} states the technology codes {codes} in section \"\n            f\"{config.TECHNOLOGY_SECTION_NUMBER}, where it states {technology} once and no other\"\n        )\n\n    requirements_text = _section(sections, config.REQUIREMENTS_SECTION_NUMBER, document_name)\n    whole = re.fullmatch(config.REQUIREMENTS_SECTION_PATTERN, requirements_text)\n    if whole is None:\n        raise ValueError(\n            f\"Section {config.REQUIREMENTS_SECTION_NUMBER} of {document_name} is not laid out \"\n            \"as the requirements of a connection standard\"\n        )\n    pieces = re.split(config.REQUIREMENT_NUMBER_PATTERN, whole.group(1))\n    if pieces[0].strip():\n        raise ValueError(f\"{document_name} has text before its first requirement\")\n    numbers = [int(number) for number in pieces[1::2]]\n    if not numbers or numbers != list(range(1, len(numbers) + 1)):\n        raise ValueError(\n            f\"{document_name} numbers its requirements {numbers}, where they run from 1 in order\"\n        )\n    requirements = []\n    seen_kinds = set()\n    for piece in pieces[2::2]:\n        requirement = _read_requirement(piece.strip(), document_name)\n        if requirement[\"requirement_kind\"] in seen_kinds:\n            raise ValueError(\n                f\"{document_name} states the requirement kind \"\n                f\"{requirement['requirement_kind']} twice\"\n            )\n        seen_kinds.add(requirement[\"requirement_kind\"])\n        requirements.append(requirement)\n    return {\n        \"technology\": technology,\n        \"document_name\": document_name,\n        \"requirements\": requirements,\n    }\n"}, {"path": "knowledge/vector_index.py", "explain": "The only module that talks to ChromaDB. build_vector_index rebuilds the persistent store with all-MiniLM-L6-v2 embeddings and cosine distance (search breadth far above the passage count so search is exact). read_document_section stitches a section back together from its passages; search_documents returns the 4 nearest passages, never from the casebook.", "code": "\"\"\"Embeds, stores, reads back and searches the passages. The only module that talks to the store.\"\"\"\n\nimport os\n\nimport chromadb\nfrom chromadb.utils.embedding_functions import SentenceTransformerEmbeddingFunction\n\nfrom config import config\n\nADD_BATCH_SIZE = 256\nSEARCH_BREADTH = 2000\n\n\ndef _embedding_function():\n    \"\"\"The embedding the store is built and searched with.\"\"\"\n    return SentenceTransformerEmbeddingFunction(\n        model_name=config.EMBEDDING_MODEL_NAME, device=config.EMBEDDING_DEVICE\n    )\n\n\ndef _collection_metadata():\n    # A search breadth far above the passage count makes every search weigh every passage.\n    return {\n        \"hnsw:space\": config.VECTOR_DISTANCE_METRIC,\n        \"hnsw:search_ef\": SEARCH_BREADTH,\n        \"hnsw:construction_ef\": SEARCH_BREADTH,\n    }\n\n\ndef build_vector_index(chunk_records, store_path):\n    \"\"\"Build (or replace) the persistent, searchable store of passages.\"\"\"\n    if os.path.isfile(store_path):\n        raise ValueError(f\"{store_path} is a file, where the store is kept in a folder\")\n    if os.path.isdir(store_path):\n        held = os.listdir(store_path)\n        if held and config.VECTOR_STORE_FILE_NAME not in held:\n            raise ValueError(\n                f\"{store_path} holds files but no {config.VECTOR_STORE_FILE_NAME}, so it is not \"\n                \"a store this project built\"\n            )\n    embedding_function = _embedding_function()\n    embedding_function([\"The embedding model is ready.\"])\n    os.makedirs(store_path, exist_ok=True)\n    client = chromadb.PersistentClient(path=store_path)\n    existing = [\n        getattr(collection, \"name\", collection) for collection in client.list_collections()\n    ]\n    if config.VECTOR_COLLECTION_NAME in existing:\n        client.delete_collection(config.VECTOR_COLLECTION_NAME)\n    collection = client.create_collection(\n        name=config.VECTOR_COLLECTION_NAME,\n        embedding_function=embedding_function,\n        metadata=_collection_metadata(),\n    )\n    for start in range(0, len(chunk_records), ADD_BATCH_SIZE):\n        batch = chunk_records[start:start + ADD_BATCH_SIZE]\n        collection.add(\n            ids=[record[\"chunk_id\"] for record in batch],\n            documents=[record[\"chunk_text\"] for record in batch],\n            metadatas=[\n                {\n                    \"document_name\": record[\"document_name\"],\n                    \"section_number\": int(record[\"section_number\"]),\n                    \"passage_number\": int(record[\"passage_number\"]),\n                    \"carried_characters\": int(record[\"carried_characters\"]),\n                }\n                for record in batch\n            ],\n        )\n    return collection.count()\n\n\ndef open_vector_index(store_path):\n    \"\"\"Open the store for reading and searching, without changing it.\"\"\"\n    if not os.path.isfile(os.path.join(store_path, config.VECTOR_STORE_FILE_NAME)):\n        raise ValueError(\n            f\"{store_path} holds no {config.VECTOR_STORE_FILE_NAME}; run run_knowledge_indexing.py\"\n        )\n    client = chromadb.PersistentClient(path=store_path)\n    existing = [\n        getattr(collection, \"name\", collection) for collection in client.list_collections()\n    ]\n    if config.VECTOR_COLLECTION_NAME not in existing:\n        raise ValueError(\n            f\"The store at {store_path} holds no collection {config.VECTOR_COLLECTION_NAME}\"\n        )\n    return client.get_collection(\n        name=config.VECTOR_COLLECTION_NAME, embedding_function=_embedding_function()\n    )\n\n\ndef read_document_section(collection, document_name, section_number):\n    \"\"\"Read one section of one document back, whole, exactly as it was divided.\"\"\"\n    stored = collection.get(\n        where={\n            \"$and\": [\n                {\"document_name\": {\"$eq\": document_name}},\n                {\"section_number\": {\"$eq\": int(section_number)}},\n            ]\n        },\n        include=[\"documents\", \"metadatas\"],\n    )\n    if not stored[\"ids\"]:\n        raise ValueError(\n            config.NO_SECTION_PASSAGES_MESSAGE.format(\n                section_number=section_number, document_name=document_name\n            )\n        )\n    passages = sorted(\n        zip(stored[\"documents\"], stored[\"metadatas\"]),\n        key=lambda pair: int(pair[1][\"passage_number\"]),\n    )\n    section_text = passages[0][0]\n    for text, metadata in passages[1:]:\n        section_text += \" \" + text[int(metadata[\"carried_characters\"]):]\n    return section_text\n\n\ndef search_documents(collection, query_texts):\n    \"\"\"The nearest passages to each question, nearest first, never from the casebook.\"\"\"\n    results = collection.query(\n        query_texts=list(query_texts),\n        n_results=config.CHAT_RETRIEVAL_RESULT_COUNT,\n        where={\"document_name\": {\"$nin\": list(config.CHAT_EXCLUDED_DOCUMENTS)}},\n        include=[\"documents\", \"metadatas\", \"distances\"],\n    )\n    answered = []\n    for position in range(len(query_texts)):\n        passages = []\n        for chunk_id, text, metadata, distance in zip(\n            results[\"ids\"][position],\n            results[\"documents\"][position],\n            results[\"metadatas\"][position],\n            results[\"distances\"][position],\n        ):\n            passages.append(\n                {\n                    \"chunk_id\": chunk_id,\n                    \"chunk_text\": text,\n                    \"document_name\": metadata[\"document_name\"],\n                    \"section_number\": int(metadata[\"section_number\"]),\n                    \"distance\": float(distance),\n                }\n            )\n        passages.sort(key=lambda passage: passage[\"distance\"])\n        answered.append(passages)\n    return answered\n"}], "commands": "git pull origin main\nmkdir -p knowledge\n# paste today's files, then:\ngit add knowledge/standard_reading.py knowledge/vector_index.py\ngit commit -m \"Day 2 (RAG): Requirements read from each standard's own PDF; the Chroma store\"\ngit push origin HEAD", "demo": "python - <<'EOF'\nfrom config import config\nfrom knowledge.pdf_extraction import extract_text_from_directory\nfrom knowledge.standard_reading import read_connection_standard\ndocuments = extract_text_from_directory(config.DOCS_DIRECTORY)\nfor technology in config.CONNECTION_STANDARD_DOCUMENTS:\n    standard = read_connection_standard(technology, documents)\n    print(technology, standard[\"document_name\"])\n    for requirement in standard[\"requirements\"]:\n        rules = {name: str(value) for name, value in requirement[\"rules\"].items()}\n        print(\"   \", requirement[\"requirement_name\"], rules)\nEOF", "show": "Each technology lists its own requirements with its own figures as exact decimals - the EV charge point and heat pump rated-current limits differ even though the sentences look alike. Nothing is hard-coded."}, {"owner": "aparna", "summary": "Queue page with stat cards and filter; the four-tab detail page.", "files": [{"path": "dashboard/application_queue.py", "explain": "The application queue page: stat cards for open applications, heating failed and each assessment, a technology filter (the service does the filtering) and the ranked table. Selecting a row remembers it so the detail page opens on it.", "code": "\"\"\"The open queue, in the order the connections team works it.\"\"\"\n\nimport pandas as pd\nimport streamlit as st\n\nfrom config import config\nfrom dashboard.api_client import apply_page_style, call_service, page_heading, stat_card\n\nSELECTED_KEY = \"selected_application\"\n\n\ndef render_application_queue_page():\n    \"\"\"Counts along the top, a technology filter and the ranked table.\"\"\"\n    apply_page_style()\n    page_heading(config.PAGE_QUEUE, \"Every open application, heat pumps on failed heating first.\")\n    everything = call_service(\"GET\", \"/queue\", query={\"technology\": config.QUEUE_TECHNOLOGY_ALL})\n    heating_failed = sum(\n        1\n        for row in everything\n        if row[\"technology\"] == config.HEAT_PUMP and row[\"urgency\"] == config.URGENCY_HEATING_FAILED\n    )\n    cards = st.columns(2 + len(config.DECISIONS))\n    with cards[0]:\n        stat_card(\"◎\", \"Open applications\", len(everything), \"In working order\", \"green\")\n    with cards[1]:\n        stat_card(\"♨\", \"Heating failed\", heating_failed, \"Moved to the front of the queue\", \"red\")\n    for position, decision in enumerate(config.DECISIONS, start=2):\n        with cards[position]:\n            stat_card(\n                \"◆\",\n                decision.title(),\n                sum(1 for row in everything if row[\"assessment\"] == decision),\n                \"Assessed by the screening\",\n                config.DECISION_BADGE_COLOURS[decision],\n            )\n    st.write(\"\")\n    technology = st.selectbox(\n        \"Technology\",\n        config.QUEUE_TECHNOLOGY_OPTIONS,\n        format_func=lambda option: config.QUEUE_TECHNOLOGY_LABELS[option],\n    )\n    rows = call_service(\"GET\", \"/queue\", query={\"technology\": technology})\n    if not rows:\n        st.info(\"No open application of this technology.\")\n        return\n    table = pd.DataFrame(\n        [\n            {\n                \"Position\": row[\"queue_position\"],\n                \"Reference\": row[\"application_reference\"],\n                \"Technology\": row[\"technology_label\"],\n                \"Premises\": row[\"premises_type\"],\n                \"Portal\": row[\"source_portal\"],\n                \"Urgency\": row[\"urgency\"],\n                \"Assessment\": row[\"assessment\"],\n                \"Met\": row[\"requirements_met_count\"],\n                \"Not met\": row[\"requirements_not_met_count\"],\n                \"Not documented\": row[\"requirements_not_documented_count\"],\n                \"Rating stated\": \"Yes\" if row[\"rating_stated\"] else \"No\",\n                \"Triggers\": row[\"network_trigger_count\"],\n                \"Likelihood\": f\"{row['network_work_likelihood']:.{config.LIKELIHOOD_DECIMALS}f}\",\n                \"Expected days\": row[\"expected_working_days\"],\n                \"Delay\": {True: \"Delay\", False: \"On plan\", None: \"No plan\"}[row[\"delay_expected\"]],\n                \"Flags\": row[\"disagreement_count\"],\n                \"Statements\": row[\"document_count\"],\n            }\n            for row in rows\n        ]\n    )\n    picked = st.dataframe(\n        table,\n        hide_index=True,\n        use_container_width=True,\n        on_select=\"rerun\",\n        selection_mode=\"single-row\",\n    )\n    selected_rows = picked.selection.rows if picked is not None else []\n    if selected_rows:\n        st.session_state[SELECTED_KEY] = table.iloc[selected_rows[0]][\"Reference\"]\n        st.success(\n            f\"{st.session_state[SELECTED_KEY]} selected - open {config.PAGE_DETAIL} to see it.\"\n        )\n"}, {"path": "dashboard/application_detail.py", "explain": "One application: headline badges, four stat cards and four tabs - Screening (each requirement with its result and blank answers), Statement evidence (every sentence, flags highlighted), Form (each answer and what uses it) and Review (the stored recommendation, or the form that opens a review with 5 model calls).", "code": "\"\"\"Everything established about one application, and the form that opens its review.\"\"\"\n\nimport streamlit as st\n\nfrom config import config\nfrom dashboard.api_client import (\n    apply_page_style,\n    badge_html,\n    call_service,\n    page_heading,\n    show_badges,\n    stat_card,\n)\nfrom dashboard.application_queue import SELECTED_KEY\n\n\ndef _label(column_name):\n    return config.FORM_ANSWER_LABELS.get(column_name, column_name.replace(\"_\", \" \"))\n\n\ndef _value(value):\n    return config.NOT_GIVEN_TEXT if value is None else value\n\n\ndef _screening_tab(screening):\n    for requirement in screening[\"requirements\"]:\n        colour = config.REQUIREMENT_RESULT_BADGE_COLOURS[requirement[\"result\"]]\n        blanks = \"\"\n        if requirement[\"blank_answers\"]:\n            blanks = \"<br><small>Left blank: \" + \", \".join(\n                _label(column) for column in requirement[\"blank_answers\"]\n            ) + \"</small>\"\n        st.markdown(\n            f'<div class=\"pw-row\">{badge_html(requirement[\"result\"], colour)}'\n            f\"<b>{requirement['requirement_name']}</b><br>\"\n            f\"<small>{requirement['requirement_sentence']}</small>{blanks}</div>\",\n            unsafe_allow_html=True,\n        )\n    if not screening[\"rating_stated\"]:\n        rating_column = config.RATING_COLUMNS[screening[\"technology\"]]\n        st.warning(f\"The {config.RATING_TERMS[rating_column]} is blank.\")\n    st.markdown(\"**Decisions open**\")\n    show_badges(\n        [(decision, config.DECISION_BADGE_COLOURS[decision]) for decision in screening[\"decisions_open\"]]\n    )\n    st.markdown(\"**Network triggers**\")\n    if screening[\"network_triggers\"]:\n        show_badges([(trigger, \"violet\") for trigger in screening[\"network_triggers\"]])\n    else:\n        st.caption(\"No network trigger applies.\")\n\n\ndef _evidence_tab(detail):\n    if not detail[\"application_documents\"]:\n        st.info(\"No statement is attached.\")\n        return\n    flags = {flag[\"sentence\"]: flag for flag in detail[\"disagreements\"]}\n    current = None\n    for finding in detail[\"evidence_findings\"]:\n        if finding[\"document_id\"] != current:\n            current = finding[\"document_id\"]\n            st.markdown(f\"#### {current} · {finding['document_type']}\")\n        borne = \", \".join(finding[\"requirements_borne_on\"]) or \"none\"\n        flag = flags.get(finding[\"sentence\"])\n        extra = \"\"\n        css = \"pw-row\"\n        if flag is not None:\n            css += \" pw-flag\"\n            stated = \", \".join(f\"{amps:.{config.AMPS_DECIMALS}f}\" for amps in flag[\"stated_amps\"])\n            form = \", \".join(\n                f\"{amps:.{config.AMPS_DECIMALS}f}\" for amps in flag[\"form_rating_amps\"]\n            ) or \"none\"\n            extra = (\n                f\"<br>{badge_html(flag['flag'], config.DELAY_COLOUR)}\"\n                f\"<small>States {stated} A per phase; the form's ratings: {form}</small>\"\n            )\n        st.markdown(\n            f'<div class=\"{css}\">{badge_html(finding[\"sentence_type\"], config.SENTENCE_TYPE_BADGE_COLOUR)}'\n            f\"{finding['sentence']}<br><small>Bears on: {borne}</small>{extra}</div>\",\n            unsafe_allow_html=True,\n        )\n\n\ndef _form_tab(detail):\n    application = detail[\"application\"]\n    screening = detail[\"screening\"]\n    technology = screening[\"technology\"]\n    shown = []\n    rows = []\n    for requirement in screening[\"requirements\"]:\n        for column in config.REQUIREMENT_ANSWER_COLUMNS[requirement[\"requirement_kind\"]]:\n            if column not in shown:\n                shown.append(column)\n                rows.append((_label(column), _value(application.get(column)),\n                             requirement[\"requirement_name\"]))\n    rating_column = config.RATING_COLUMNS[technology]\n    if rating_column not in shown:\n        shown.append(rating_column)\n        rows.append((_label(rating_column), _value(application.get(rating_column)), \"The rating\"))\n    trigger_columns = list(config.SUPPLY_TRIGGER_ANSWER_COLUMNS)\n    if technology in config.GENERATING_TECHNOLOGIES:\n        trigger_columns += config.GENERATION_TRIGGER_ANSWER_COLUMNS\n    for column in trigger_columns:\n        if column not in shown:\n            shown.append(column)\n            rows.append((_label(column), _value(application.get(column)), \"Network triggers\"))\n    st.dataframe(\n        [{\"Answer\": label, \"On the form\": str(value), \"Used for\": use} for label, value, use in rows],\n        hide_index=True,\n        use_container_width=True,\n    )\n\n\ndef _review_tab(reference, reviews):\n    if reviews:\n        review = reviews[-1]\n        show_badges(\n            [\n                (config.REVIEW_STATUS_LABELS[review[\"status\"]],\n                 config.STATUS_BADGE_COLOURS[review[\"status\"]]),\n                (review[\"recommended_decision\"],\n                 config.DECISION_BADGE_COLOURS[review[\"recommended_decision\"]]),\n            ]\n        )\n        st.markdown(review[\"recommendation_text\"])\n        return\n    with st.form(\"open_review_form\"):\n        request_text = st.text_area(\n            \"What should the review look at?\",\n            max_chars=config.COORDINATOR_REQUEST_MAXIMUM_CHARACTERS,\n            placeholder=\"Are the requirements met on the form, and does any statement disagree?\",\n        )\n        submitted = st.form_submit_button(\"Open the review\", type=\"primary\")\n    if submitted:\n        if len(request_text.strip()) < config.COORDINATOR_REQUEST_MINIMUM_CHARACTERS:\n            st.warning(\n                f\"Write at least {config.COORDINATOR_REQUEST_MINIMUM_CHARACTERS} characters.\"\n            )\n            return\n        review = call_service(\n            \"POST\",\n            \"/reviews\",\n            payload={\"application_reference\": reference, \"coordinator_request\": request_text},\n            waiting_message=(\n                f\"{config.LLM_CALLS_BEFORE_DECISION} model calls are being made for {reference}\"\n            ),\n        )\n        st.success(\n            f\"The review of {reference} is waiting for a Connections Engineer. It recommends \"\n            f\"{review['recommended_decision']}.\"\n        )\n        st.markdown(review[\"recommendation_text\"])\n\n\ndef render_application_detail_page():\n    \"\"\"One application: headline, counts and the four tabs.\"\"\"\n    apply_page_style()\n    queue = call_service(\"GET\", \"/queue\", query={\"technology\": config.QUEUE_TECHNOLOGY_ALL})\n    references = [row[\"application_reference\"] for row in queue]\n    if not references:\n        st.info(\"The queue is empty.\")\n        return\n    remembered = st.session_state.get(SELECTED_KEY)\n    index = references.index(remembered) if remembered in references else 0\n    reference = st.selectbox(\"Application\", references, index=index)\n    st.session_state[SELECTED_KEY] = reference\n    detail = call_service(\"GET\", f\"/queue/{reference}\")\n    reviews = [\n        review\n        for review in call_service(\n            \"GET\", \"/reviews\", query={\"status_value\": config.REVIEW_STATUS_OPTIONS}\n        )\n        if review[\"application_reference\"] == reference\n    ]\n    application = detail[\"application\"]\n    screening = detail[\"screening\"]\n    technology = screening[\"technology\"]\n    page_heading(\n        f\"{reference} · {config.TECHNOLOGY_LABELS[technology]}\",\n        f\"{_value(application.get(config.REGION_TYPE_COLUMN))} · substation \"\n        f\"{_value(application.get(config.SUBSTATION_REFERENCE_COLUMN))} · \"\n        f\"{_value(application.get(config.SOURCE_PORTAL_COLUMN))} · revision \"\n        f\"{_value(application.get(config.REVISION_NUMBER_COLUMN))} · {screening['standard_document']}\",\n    )\n    badges = []\n    if technology == config.HEAT_PUMP and application.get(config.URGENCY_COLUMN) == config.URGENCY_HEATING_FAILED:\n        badges.append((config.URGENCY_HEATING_FAILED, config.HEATING_FAILED_BADGE_COLOUR))\n    badges.append((screening[\"assessment\"], config.DECISION_BADGE_COLOURS[screening[\"assessment\"]]))\n    badges.append((f\"Queue position {detail['queue_position']}\", config.NEUTRAL_BADGE_COLOUR))\n    if reviews:\n        status = reviews[-1][\"status\"]\n        badges.append((config.REVIEW_STATUS_LABELS[status], config.STATUS_BADGE_COLOURS[status]))\n    show_badges(badges)\n    total = len(screening[\"requirements\"])\n    columns = st.columns(4)\n    with columns[0]:\n        stat_card(\"✓\", \"Requirements met\", f\"{screening[config.REQUIREMENTS_MET_COUNT_COLUMN]} of {total}\",\n                  f\"{screening[config.REQUIREMENTS_NOT_MET_COUNT_COLUMN]} not met, \"\n                  f\"{screening[config.REQUIREMENTS_NOT_DOCUMENTED_COUNT_COLUMN]} not documented\", \"green\")\n    with columns[1]:\n        stat_card(\"⚡\", \"Network triggers\", len(screening[\"network_triggers\"]),\n                  \", \".join(screening[\"network_triggers\"]) or \"None applies\", \"violet\")\n    with columns[2]:\n        likelihood = detail[\"likelihood\"]\n        stat_card(\"%\", \"Network work likelihood\",\n                  f\"{likelihood['network_work_likelihood']:.{config.LIKELIHOOD_DECIMALS}f}\",\n                  f\"Band {likelihood['likelihood_band']}\",\n                  config.LIKELIHOOD_BAND_BADGE_COLOURS[likelihood[\"likelihood_band\"]])\n    with columns[3]:\n        duration = detail[\"duration\"]\n        planned = duration[\"planned_working_days\"]\n        stat_card(\"⏱\", \"Expected working days\", duration[\"expected_working_days\"],\n                  \"No plan given\" if planned is None else f\"Against {planned} planned\",\n                  config.DELAY_COLOUR if duration[\"delay_expected\"] else config.NEUTRAL_BADGE_COLOUR)\n    st.write(\"\")\n    screening_tab, evidence_tab, form_tab, review_tab = st.tabs(\n        [\"Screening\", \"Statement evidence\", \"Form\", \"Review\"]\n    )\n    with screening_tab:\n        _screening_tab(screening)\n    with evidence_tab:\n        _evidence_tab(detail)\n    with form_tab:\n        _form_tab(detail)\n    with review_tab:\n        _review_tab(reference, reviews)\n"}], "commands": "git pull origin main\nmkdir -p dashboard\n# paste today's files, then:\ngit add dashboard/application_queue.py dashboard/application_detail.py\ngit commit -m \"Day 2 (Streamlit): Queue page with stat cards and filter; the four-tab detail page\"\ngit push origin HEAD", "demo": "python - <<'EOF'\nimport dashboard.application_queue, dashboard.application_detail\nprint(\"queue and detail pages import cleanly; they draw live data from Day 5\")\nEOF", "show": "Walk through the code: stat cards (open, heating failed, each assessment), the technology filter sent to the service, the selectable table, and the detail page's Screening, Statement evidence, Form and Review tabs. Everything shown comes from the service."}, {"owner": "karthik", "summary": "History, logs and sentences cleaned; quality report; entry point 2.", "files": [{"path": "data_pipeline/history_cleaning.py", "explain": "clean_history_dataset - the network work model's table: cleaned forms at their highest revision, minus any application whose highest revision has no outcome.", "code": "\"\"\"Produces the table the network work model learns from.\"\"\"\n\nfrom config import config\nfrom data_pipeline.application_cleaning import clean_application_records\nfrom data_pipeline.common_cleaning import remove_rows_missing_target\n\n\ndef clean_history_dataset(frame):\n    \"\"\"One row per application, at its highest revision, that records an outcome.\"\"\"\n    applications = clean_application_records(\n        frame, config.HISTORY_VALUE_MAPPINGS, config.FORM_WHOLE_NUMBER_PATTERNS\n    )\n    return remove_rows_missing_target(applications, config.HISTORY_TARGET_COLUMN)\n"}, {"path": "data_pipeline/connection_log_cleaning.py", "explain": "read_log_answers reads a log like a form; clean_connection_log_dataset refuses logs without a reference or two logs of one application, blanks impossible values and drops logs without actual working days (including negative ones).", "code": "\"\"\"Produces the table the duration model learns from.\"\"\"\n\nfrom config import config\nfrom data_pipeline.common_cleaning import (\n    convert_amounts,\n    convert_application_references,\n    convert_currents,\n    convert_phases,\n    convert_whole_numbers,\n    normalize_category_values,\n    refuse_missing_values,\n    refuse_repeated_references,\n    refuse_unreadable_identifiers,\n    remove_duplicate_records,\n    remove_rows_missing_target,\n    treat_impossible_phase_pairs_as_missing,\n    treat_values_below_minimum_as_missing,\n    treat_values_outside_sizes_as_missing,\n)\n\n\ndef read_log_answers(frame):\n    \"\"\"Read every answer of a log as the Connection Rules read it; no row is removed.\"\"\"\n    logs = normalize_category_values(frame, config.LOG_VALUE_MAPPINGS)\n    logs[config.APPLICATION_REFERENCE_COLUMN] = convert_application_references(\n        logs[config.APPLICATION_REFERENCE_COLUMN]\n    )\n    logs = refuse_unreadable_identifiers(logs, config.LOG_IDENTIFIER_PATTERNS)\n    logs = convert_whole_numbers(logs, config.LOG_WHOLE_NUMBER_PATTERNS)\n    logs = convert_phases(logs)\n    logs = treat_impossible_phase_pairs_as_missing(logs)\n    logs = convert_currents(logs, config.LOG_CURRENT_PHASES)\n    logs = convert_amounts(logs, config.LOG_AMOUNT_READINGS)\n    return logs\n\n\ndef clean_connection_log_dataset(frame):\n    \"\"\"One row per application with the working days its connection really took.\"\"\"\n    logs = remove_duplicate_records(frame)\n    logs = refuse_missing_values(logs, [config.APPLICATION_REFERENCE_COLUMN])\n    logs = read_log_answers(logs)\n    logs = refuse_repeated_references(logs, config.APPLICATION_REFERENCE_COLUMN)\n    logs = treat_values_below_minimum_as_missing(logs, config.LOG_MINIMUM_VALUES)\n    logs = treat_values_outside_sizes_as_missing(logs, config.LOG_ALLOWED_SIZES)\n    return remove_rows_missing_target(logs, config.LOG_TARGET_COLUMN)\n"}, {"path": "data_pipeline/sentence_cleaning.py", "explain": "clean_sentence_dataset - plain sentence text, the length re-measured after cleaning, and unlabelled or under-3-word sentences removed.", "code": "\"\"\"Produces the table the sentence model learns from.\"\"\"\n\nimport pandas as pd\n\nfrom config import config\nfrom data_pipeline.document_cleaning import clean_document_records\n\n\ndef _word_count(text):\n    if text is None or (isinstance(text, float) and pd.isna(text)):\n        return 0\n    return len(str(text).split())\n\n\ndef clean_sentence_dataset(frame):\n    \"\"\"Clean labelled statement sentences, re-measure them and drop the unusable ones.\"\"\"\n    sentences = clean_document_records(\n        frame,\n        config.SENTENCE_VALUE_MAPPINGS,\n        config.SENTENCE_WHOLE_NUMBER_PATTERNS,\n        config.SENTENCE_ID_COLUMN,\n        config.SENTENCE_TEXT_COLUMN,\n    )\n    texts = sentences[config.SENTENCE_TEXT_COLUMN]\n    lengths = [pd.NA if pd.isna(text) else len(str(text)) for text in texts]\n    sentences[config.SENTENCE_LENGTH_COLUMN] = pd.array(lengths, dtype=config.WHOLE_NUMBER_DTYPE)\n    labelled = sentences[config.SENTENCE_TARGET_COLUMN].notna()\n    long_enough = texts.map(_word_count) >= config.MINIMUM_SENTENCE_WORDS\n    return sentences[labelled & long_enough].reset_index(drop=True)\n"}, {"path": "data_pipeline/quality_profiler.py", "explain": "profile_dataset counts received/kept/removed rows, duplicates, missing targets and missing cells; the history, log and sentence profilers count every defect type; write_quality_report writes output/data_quality_report.json where the removal reasons add up exactly to rows_removed.", "code": "\"\"\"Measures how dirty each raw extract was, and writes the evidence out.\n\nEvery figure is counted on the extract's first copies of each row, as they\narrived, unless said otherwise.\n\"\"\"\n\nimport json\nimport os\n\nimport numpy as np\nimport pandas as pd\n\nfrom config import config\nfrom data_pipeline.application_cleaning import read_application_answers\nfrom data_pipeline.common_cleaning import (\n    convert_markup_to_plain_text,\n    convert_phases,\n    remove_duplicate_records,\n)\nfrom data_pipeline.connection_log_cleaning import read_log_answers\n\n\ndef _missing_cells(frame):\n    counts = frame.isna().sum()\n    return {str(column): int(count) for column, count in counts.items() if count > 0}\n\n\ndef _first_copies(raw_frame):\n    return remove_duplicate_records(raw_frame)\n\n\ndef profile_dataset(raw_frame, clean_frame, target_column):\n    \"\"\"Account for one dataset: what arrived, what survived and what was missing.\"\"\"\n    duplicated = raw_frame.duplicated(keep=\"first\")\n    first_copies = raw_frame[~duplicated]\n    return {\n        \"rows_received\": int(len(raw_frame)),\n        \"rows_kept\": int(len(clean_frame)),\n        \"rows_removed\": int(len(raw_frame) - len(clean_frame)),\n        \"duplicate_rows\": int(duplicated.sum()),\n        \"rows_missing_target\": int(first_copies[target_column].isna().sum()),\n        \"columns\": int(clean_frame.shape[1]),\n        \"missing_cells_as_received\": _missing_cells(first_copies),\n        \"missing_cells_after_cleaning\": _missing_cells(clean_frame),\n    }\n\n\ndef _not_matching(values, pattern):\n    given = values[values.notna()].astype(str)\n    return int((~given.str.match(pattern)).sum())\n\n\ndef _references_not_canonical(first_copies):\n    return _not_matching(\n        first_copies[config.APPLICATION_REFERENCE_COLUMN],\n        config.CANONICAL_APPLICATION_REFERENCE_PATTERN,\n    )\n\n\ndef _numbers_not_plain(first_copies, number_patterns):\n    return {\n        column_name: _not_matching(first_copies[column_name], config.PLAIN_NUMBER_PATTERN)\n        for column_name in number_patterns\n        if column_name in first_copies.columns\n    }\n\n\ndef _phases_not_numbers(first_copies):\n    return {\n        column_name: _not_matching(first_copies[column_name], config.CANONICAL_PHASES_PATTERN)\n        for column_name in config.PHASE_COLUMNS\n    }\n\n\ndef _impossible_phase_pairs(first_copies):\n    phases = convert_phases(first_copies)\n    supply = phases[config.SUPPLY_PHASES_COLUMN].astype(\"float64\")\n    equipment = phases[config.EQUIPMENT_PHASES_COLUMN].astype(\"float64\")\n    return int(((equipment > supply) & supply.notna() & equipment.notna()).sum())\n\n\ndef _by_notation(values, notations):\n    given = values[values.notna()].astype(str)\n    counts = {}\n    for notation_name, pattern in notations.items():\n        counts[notation_name] = int(given.str.match(pattern).sum())\n    return counts\n\n\ndef _currents_by_notation(first_copies, current_phases):\n    return {\n        column_name: _by_notation(first_copies[column_name], config.CURRENT_NOTATIONS)\n        for column_name in current_phases\n        if column_name in first_copies.columns\n    }\n\n\ndef _currents_unconvertible(first_copies, read, current_phases):\n    return {\n        column_name: int((first_copies[column_name].notna() & read[column_name].isna()).sum())\n        for column_name in current_phases\n        if column_name in first_copies.columns\n    }\n\n\ndef _amounts_by_notation(first_copies, amount_readings):\n    return {\n        column_name: _by_notation(first_copies[column_name], reading[\"notations\"])\n        for column_name, reading in amount_readings.items()\n        if column_name in first_copies.columns\n    }\n\n\ndef _beyond(read, limits, compare):\n    counts = {}\n    for column_name, limit in limits.items():\n        if column_name not in read.columns:\n            continue\n        numbers = read[column_name].astype(\"float64\")\n        counts[column_name] = int((numbers.notna() & compare(numbers, float(limit))).sum())\n    return counts\n\n\ndef _outside_sizes(read, allowed_sizes):\n    counts = {}\n    for column_name, sizes in allowed_sizes.items():\n        if column_name not in read.columns:\n            continue\n        numbers = read[column_name].astype(\"float64\")\n        outside = numbers.notna() & ~numbers.isin([float(size) for size in sizes])\n        counts[column_name] = int(outside.sum())\n    return counts\n\n\ndef _categories_not_canonical(first_copies, value_mappings):\n    counts = {}\n    for column_name, value_mapping in value_mappings.items():\n        if column_name not in first_copies.columns:\n            continue\n        given = first_copies[column_name][first_copies[column_name].notna()].astype(str)\n        counts[column_name] = int((~given.isin(set(value_mapping.values()))).sum())\n    return counts\n\n\ndef _target_shares(clean_frame, target_column):\n    shares = clean_frame[target_column].value_counts(normalize=True)\n    return {\n        str(value): round(float(share), config.TARGET_SHARE_DECIMALS)\n        for value, share in shares.sort_index().items()\n    }\n\n\ndef profile_history_details(raw_frame, clean_frame):\n    \"\"\"Account for the defects peculiar to the application history extracts.\"\"\"\n    first_copies = _first_copies(raw_frame)\n    read = read_application_answers(\n        first_copies, config.HISTORY_VALUE_MAPPINGS, config.FORM_WHOLE_NUMBER_PATTERNS\n    )\n    revisions = read[config.REVISION_NUMBER_COLUMN].astype(\"float64\")\n    latest = revisions.groupby(read[config.APPLICATION_REFERENCE_COLUMN]).transform(\"max\")\n    earlier = (revisions < latest).to_numpy(dtype=bool)\n    answered = read[config.HISTORY_TARGET_COLUMN].notna().to_numpy(dtype=bool)\n    return {\n        \"answered_earlier_revisions_removed\": int((earlier & answered).sum()),\n        \"application_references_not_written_canonically\": _references_not_canonical(\n            first_copies\n        ),\n        \"numbers_not_written_as_plain_numbers\": _numbers_not_plain(\n            first_copies, config.FORM_WHOLE_NUMBER_PATTERNS\n        ),\n        \"phases_not_written_as_numbers\": _phases_not_numbers(first_copies),\n        \"impossible_phase_pairs_as_received\": _impossible_phase_pairs(first_copies),\n        \"currents_by_notation_as_written\": _currents_by_notation(\n            first_copies, config.FORM_CURRENT_PHASES\n        ),\n        \"currents_unconvertible_without_phases\": _currents_unconvertible(\n            first_copies, read, config.FORM_CURRENT_PHASES\n        ),\n        \"amounts_by_notation_as_written\": _amounts_by_notation(\n            first_copies, config.FORM_AMOUNT_READINGS\n        ),\n        \"values_below_minimum_as_received\": _beyond(\n            read, config.FORM_MINIMUM_VALUES, lambda numbers, limit: numbers < limit\n        ),\n        \"values_above_maximum_as_received\": _beyond(\n            read, config.FORM_MAXIMUM_VALUES, lambda numbers, limit: numbers > limit\n        ),\n        \"values_outside_sizes_as_received\": _outside_sizes(read, config.FORM_ALLOWED_SIZES),\n        \"category_values_not_written_canonically\": _categories_not_canonical(\n            first_copies, config.HISTORY_VALUE_MAPPINGS\n        ),\n        \"target_shares\": _target_shares(clean_frame, config.HISTORY_TARGET_COLUMN),\n    }\n\n\ndef profile_log_details(raw_frame, clean_frame):\n    \"\"\"Account for the defects peculiar to the connection log extracts.\"\"\"\n    first_copies = _first_copies(raw_frame)\n    read = read_log_answers(first_copies)\n    target = read[config.LOG_TARGET_COLUMN].astype(\"float64\")\n    target_minimum = float(config.LOG_MINIMUM_VALUES[config.LOG_TARGET_COLUMN])\n    return {\n        \"rows_with_impossible_target\": int((target.notna() & (target < target_minimum)).sum()),\n        \"values_below_minimum_as_received\": _beyond(\n            read, config.LOG_MINIMUM_VALUES, lambda numbers, limit: numbers < limit\n        ),\n        \"application_references_not_written_canonically\": _references_not_canonical(\n            first_copies\n        ),\n        \"numbers_not_written_as_plain_numbers\": _numbers_not_plain(\n            first_copies, config.LOG_WHOLE_NUMBER_PATTERNS\n        ),\n        \"phases_not_written_as_numbers\": _phases_not_numbers(first_copies),\n        \"impossible_phase_pairs_as_received\": _impossible_phase_pairs(first_copies),\n        \"currents_by_notation_as_written\": _currents_by_notation(\n            first_copies, config.LOG_CURRENT_PHASES\n        ),\n        \"currents_unconvertible_without_phases\": _currents_unconvertible(\n            first_copies, read, config.LOG_CURRENT_PHASES\n        ),\n        \"amounts_by_notation_as_written\": _amounts_by_notation(\n            first_copies, config.LOG_AMOUNT_READINGS\n        ),\n        \"values_outside_sizes_as_received\": _outside_sizes(read, config.LOG_ALLOWED_SIZES),\n        \"category_values_not_written_canonically\": _categories_not_canonical(\n            first_copies, config.LOG_VALUE_MAPPINGS\n        ),\n        \"median_actual_working_days\": float(clean_frame[config.LOG_TARGET_COLUMN].median()),\n    }\n\n\ndef profile_sentence_details(raw_frame, clean_frame):\n    \"\"\"Account for the defects peculiar to free text.\"\"\"\n    first_copies = _first_copies(raw_frame)\n    texts = first_copies[config.SENTENCE_TEXT_COLUMN]\n    given = texts[texts.notna()].astype(str)\n    plain = convert_markup_to_plain_text(texts)\n    plain_given = plain[plain.notna()].astype(str)\n    raw_lengths = pd.to_numeric(first_copies[config.SENTENCE_LENGTH_COLUMN], errors=\"coerce\")\n    plain_lengths = plain.map(lambda text: np.nan if pd.isna(text) else len(str(text)))\n    disagreeing = int((raw_lengths != plain_lengths).sum())\n    word_counts = plain.map(lambda text: 0 if pd.isna(text) else len(str(text).split()))\n    labelled = first_copies[config.SENTENCE_TARGET_COLUMN].notna()\n    cleaned_words = clean_frame[config.SENTENCE_TEXT_COLUMN].map(\n        lambda text: len(str(text).split())\n    )\n    return {\n        \"sentences_with_markup\": int(given.str.contains(config.MARKUP_PATTERN, regex=True).sum()),\n        \"sentences_with_encoding_artifacts\": int(\n            given.str.contains(config.ENCODING_ARTIFACT_PATTERN, regex=True).sum()\n        ),\n        \"sentences_in_capitals\": int(plain_given.map(str.isupper).sum()),\n        \"sentence_lengths_disagreeing_with_plain_text_as_received\": disagreeing,\n        \"rows_with_too_few_words\": int(\n            (labelled & (word_counts < config.MINIMUM_SENTENCE_WORDS)).sum()\n        ),\n        \"shortest_sentence_words\": int(cleaned_words.min()) if len(cleaned_words) else 0,\n        \"application_references_not_written_canonically\": _references_not_canonical(\n            first_copies\n        ),\n        \"category_values_not_written_canonically\": _categories_not_canonical(\n            first_copies, config.SENTENCE_VALUE_MAPPINGS\n        ),\n        \"target_shares\": _target_shares(clean_frame, config.SENTENCE_TARGET_COLUMN),\n    }\n\n\ndef _plain_json(value):\n    if isinstance(value, np.integer):\n        return int(value)\n    if isinstance(value, np.floating):\n        return float(value)\n    if isinstance(value, np.bool_):\n        return bool(value)\n    raise TypeError(f\"{type(value).__name__} cannot be written to the quality report\")\n\n\ndef write_quality_report(profiles):\n    \"\"\"Write every dataset's profile to the quality report as sorted, indented JSON.\"\"\"\n    folder = os.path.dirname(config.DATA_QUALITY_REPORT_FILE)\n    if folder:\n        os.makedirs(folder, exist_ok=True)\n    with open(config.DATA_QUALITY_REPORT_FILE, \"w\", encoding=\"utf-8\") as report_file:\n        json.dump(profiles, report_file, indent=config.JSON_INDENT, sort_keys=True,\n                  default=_plain_json)\n\n"}, {"path": "run_data_pipeline.py", "explain": "Entry point 2. Cleans all five extracts first (so a refusal leaves no half-written set), then saves them to processed/ and writes the quality report, printing one aligned line per dataset.", "code": "\"\"\"Entry point 2: cleans the five raw extracts and writes the data quality report.\n\nRun from the Project folder:  python run_data_pipeline.py\n\"\"\"\n\nimport os\n\nfrom config import config\nfrom data_pipeline.connection_log_cleaning import clean_connection_log_dataset\nfrom data_pipeline.dataset_loader import load_raw_dataset, save_processed_dataset\nfrom data_pipeline.history_cleaning import clean_history_dataset\nfrom data_pipeline.quality_profiler import (\n    profile_dataset,\n    profile_history_details,\n    profile_log_details,\n    profile_sentence_details,\n    write_quality_report,\n)\nfrom data_pipeline.sentence_cleaning import clean_sentence_dataset\n\nDATASET_JOBS = [\n    (config.RAW_APPLICATION_HISTORY_TRAIN_FILE, config.CLEAN_APPLICATION_HISTORY_TRAIN_FILE,\n     clean_history_dataset, config.HISTORY_TARGET_COLUMN, profile_history_details),\n    (config.RAW_APPLICATION_HISTORY_EVAL_FILE, config.CLEAN_APPLICATION_HISTORY_EVAL_FILE,\n     clean_history_dataset, config.HISTORY_TARGET_COLUMN, profile_history_details),\n    (config.RAW_CONNECTION_LOGS_TRAIN_FILE, config.CLEAN_CONNECTION_LOGS_TRAIN_FILE,\n     clean_connection_log_dataset, config.LOG_TARGET_COLUMN, profile_log_details),\n    (config.RAW_CONNECTION_LOGS_EVAL_FILE, config.CLEAN_CONNECTION_LOGS_EVAL_FILE,\n     clean_connection_log_dataset, config.LOG_TARGET_COLUMN, profile_log_details),\n    (config.RAW_STATEMENT_SENTENCES_FILE, config.CLEAN_STATEMENT_SENTENCES_FILE,\n     clean_sentence_dataset, config.SENTENCE_TARGET_COLUMN, profile_sentence_details),\n]\n\n\ndef main():\n    \"\"\"Clean all five extracts first, then save them all and write the report.\"\"\"\n    cleaned = []\n    profiles = {}\n    for raw_path, clean_path, cleaner, target_column, detail_profiler in DATASET_JOBS:\n        raw_frame = load_raw_dataset(raw_path)\n        clean_frame = cleaner(raw_frame)\n        dataset_name = os.path.splitext(os.path.basename(raw_path))[0]\n        profile = profile_dataset(raw_frame, clean_frame, target_column)\n        profile.update(detail_profiler(raw_frame, clean_frame))\n        profiles[dataset_name] = profile\n        cleaned.append((dataset_name, clean_path, clean_frame, profile))\n    for dataset_name, clean_path, clean_frame, profile in cleaned:\n        save_processed_dataset(clean_frame, clean_path)\n        print(\n            f\"{dataset_name:<{config.DATASET_NAME_WIDTH}}\"\n            f\"{profile['rows_received']:>{config.ROW_COUNT_WIDTH}} received -> \"\n            f\"{profile['rows_kept']:>{config.ROW_COUNT_WIDTH}} kept  \"\n            f\"({profile['rows_removed']} removed)\"\n        )\n    write_quality_report(profiles)\n    print(f\"quality report written to {config.DATA_QUALITY_REPORT_FILE}\")\n\n\nif __name__ == \"__main__\":\n    main()\n"}], "commands": "git pull origin main\nmkdir -p data_pipeline\n# paste today's files, then:\ngit add data_pipeline/history_cleaning.py data_pipeline/connection_log_cleaning.py data_pipeline/sentence_cleaning.py data_pipeline/quality_profiler.py run_data_pipeline.py\ngit commit -m \"Day 2 (ML): History, logs and sentences cleaned; quality report; entry point 2\"\ngit push origin HEAD", "demo": "python run_data_pipeline.py", "show": "Five aligned lines, e.g. application_history_train 31750 received -> 29597 kept (2153 removed), and output/data_quality_report.json where duplicates + missing targets + earlier revisions + impossible targets + short sentences add up exactly to the rows removed."}]}, {"n": 3, "title": "Knowledge base, features and evidence", "goal": "Build the searchable knowledge base, add requirement counts and trigger flags to the history, train the network work model, read statement evidence and declare every API shape.", "check": "python run_knowledge_indexing.py", "order": null, "tasks": [{"owner": "yashwanth", "summary": "Every request and reply shape; invalid input refused with 422.", "files": [{"path": "api/schemas.py", "explain": "Pydantic shapes for every request and reply. Requests are validated before any work: a coordinator request under 5 characters, a decision reason under 10 or a decision that is not one of the three gives 422 automatically.", "code": "\"\"\"The shape of every request the service accepts and every reply it returns.\"\"\"\n\nfrom typing import Annotated, Literal\n\nfrom pydantic import BaseModel, StringConstraints\n\nfrom config import config\n\nTechnologyFilter = Literal[tuple(config.QUEUE_TECHNOLOGY_OPTIONS)]\nReviewStatusValue = Literal[tuple(config.REVIEW_STATUS_OPTIONS)]\nDecisionValue = Literal[tuple(config.DECISIONS)]\n\nCoordinatorRequestText = Annotated[\n    str,\n    StringConstraints(\n        strip_whitespace=True,\n        min_length=config.COORDINATOR_REQUEST_MINIMUM_CHARACTERS,\n        max_length=config.COORDINATOR_REQUEST_MAXIMUM_CHARACTERS,\n    ),\n]\nDecisionReasonText = Annotated[\n    str,\n    StringConstraints(\n        strip_whitespace=True,\n        min_length=config.DECISION_REASON_MINIMUM_CHARACTERS,\n        max_length=config.DECISION_REASON_MAXIMUM_CHARACTERS,\n    ),\n]\nQuestionText = Annotated[\n    str,\n    StringConstraints(\n        strip_whitespace=True,\n        min_length=config.CHAT_QUESTION_MINIMUM_CHARACTERS,\n        max_length=config.CHAT_QUESTION_MAXIMUM_CHARACTERS,\n    ),\n]\n\n\nclass SignInRequest(BaseModel):\n    username: str\n    password: str\n\n\nclass SignedInUserResponse(BaseModel):\n    username: str\n    display_name: str\n    role: str\n    session_token: str\n    pages: list[str]\n    areas: list[str]\n\n\nclass SignedOutResponse(BaseModel):\n    username: str\n    signed_out: bool\n\n\nclass QueueRow(BaseModel):\n    queue_position: int\n    application_reference: str\n    technology: str\n    technology_label: str\n    source_portal: str | None\n    premises_type: str | None\n    urgency: str | None\n    document_count: int\n    requirements_met_count: int\n    requirements_not_met_count: int\n    requirements_not_documented_count: int\n    network_trigger_count: int\n    rating_stated: bool\n    assessment: str\n    decisions_open: list[str]\n    network_work_likelihood: float\n    likelihood_band: str\n    expected_working_days: int\n    delay_expected: bool | None\n    disagreement_count: int\n\n\nclass ApplicationDetailResponse(BaseModel):\n    queue_position: int\n    application: dict\n    application_documents: list[dict]\n    screening: dict\n    evidence_findings: list[dict]\n    disagreements: list[dict]\n    likelihood: dict\n    duration: dict\n    duration_text: str\n\n\nclass ReviewRequest(BaseModel):\n    application_reference: str\n    coordinator_request: CoordinatorRequestText\n\n\nclass DecisionRequest(BaseModel):\n    decision: DecisionValue\n    decision_reason: DecisionReasonText\n\n\nclass ReviewRecordResponse(BaseModel):\n    review_id: str\n    run_id: str\n    thread_id: str | None\n    application_reference: str\n    technology: str\n    urgency: str | None\n    standard_document: str\n    coordinator_id: str | None\n    coordinator_request: str\n    status: str\n    llm_call_count: int | None\n    requirements: list[dict]\n    requirements_met_count: int\n    requirements_not_met_count: int\n    requirements_not_documented_count: int\n    network_triggers: list[str]\n    rating_stated: bool\n    assessment: str\n    decisions_open: list[str]\n    evidence: list[dict]\n    disagreements: list[dict]\n    network_work_likelihood: float\n    likelihood_band: str\n    expected_working_days: int\n    planned_working_days: int | None\n    delay_expected: bool | None\n    duration_text: str\n    review_plan_text: str\n    requirements_analysis_text: str\n    evidence_review_text: str\n    prediction_analysis_text: str\n    recommendation_text: str\n    recommended_decision: str\n    decision: str | None\n    decided_by: str | None\n    decided_by_role: str | None\n    decision_reason: str | None\n    installer_notice_text: str | None\n    notice_details: dict | None\n    household_notice_text: str | None\n    assessment_brief: dict | None\n\n\nclass LlmCallRecord(BaseModel):\n    agent_name: str\n    model_name: str\n    prompt_tokens: int\n    response_tokens: int\n    total_tokens: int\n    latency_milliseconds: int\n\n\nclass CallBudgetResponse(BaseModel):\n    review_id: str\n    run_id: str\n    calls: list[LlmCallRecord]\n    call_count: int\n    expected_call_count: int\n    total_tokens: int\n    total_latency_milliseconds: int\n\n\nclass ChatRequest(BaseModel):\n    question: QuestionText\n\n\nclass ChatResponse(BaseModel):\n    question_type: str\n    application_reference: str | None\n    substation_reference: str | None\n    technology: str | None\n    answer: str\n    source_documents: list[str]\n    closest_distance: float | None\n    was_refused: bool\n\n\nclass ChatTurnResponse(BaseModel):\n    turn_id: int\n    username: str\n    user_role: str\n    question_text: str\n    question_type: str\n    application_reference: str | None\n    substation_reference: str | None\n    technology: str | None\n    answer_text: str\n    source_documents: list[str]\n    closest_distance: float | None\n    was_refused: bool\n"}], "commands": "git pull origin main\nmkdir -p api\n# paste today's files, then:\ngit add api/schemas.py\ngit commit -m \"Day 3 (FastAPI): Every request and reply shape; invalid input refused with 422\"\ngit push origin HEAD", "demo": "python - <<'EOF'\nfrom pydantic import ValidationError\nfrom api.schemas import ReviewRequest, DecisionRequest\nprint(ReviewRequest(application_reference=\"LCT0052118\", coordinator_request=\"  Are the requirements met?  \"))\nfor bad in [lambda: ReviewRequest(application_reference=\"LCT0052118\", coordinator_request=\"ok\"),\n            lambda: DecisionRequest(decision=\"CONNECT\", decision_reason=\"Every requirement is met.\")]:\n    try:\n        bad()\n    except ValidationError as error:\n        print(\"refused:\", error.errors()[0][\"msg\"])\nEOF", "show": "Text is trimmed, a 2-character request and an unknown decision are refused by the schema - FastAPI turns these into 422 before any work or model call happens."}, {"owner": "yash", "summary": "Sentence evidence, requirement links and rating disagreements.", "files": [{"path": "tools/evidence_tools.py", "explain": "read_document_evidence splits each statement into sentences and lets the sentence model type them; link_evidence_to_requirements records which requirements of the application's own standard each sentence bears on; find_disagreements reads amps, W, kW and kVA in equipment-rating sentences (skipping fuse/cut-out/supply/... figures and kWh) and flags DISAGREES WITH FORM or DESCRIBES BLANK ANSWER.", "code": "\"\"\"Reads every sentence of an application's statements, links it and flags disagreements.\"\"\"\n\nimport re\nfrom decimal import ROUND_HALF_UP, Decimal\n\nimport pandas as pd\n\nfrom config import config\nfrom data_pipeline.common_cleaning import convert_power_to_amps_per_phase\n\n\ndef _is_blank(value):\n    if value is None or value is pd.NA:\n        return True\n    try:\n        return bool(pd.isna(value))\n    except (TypeError, ValueError):\n        return False\n\n\ndef read_document_evidence(sentence_model, documents):\n    \"\"\"One finding per sentence, statement by statement, in the order written.\"\"\"\n    pieces = []\n    for document in documents:\n        document_id = document[config.DOCUMENT_ID_COLUMN]\n        text = document.get(config.DOCUMENT_TEXT_COLUMN)\n        if _is_blank(text) or not str(text).strip():\n            raise ValueError(config.NO_STATEMENT_TEXT_MESSAGE.format(document_id=document_id))\n        for sentence in re.split(config.STATEMENT_SENTENCE_PATTERN, str(text)):\n            if sentence:\n                pieces.append((document, sentence))\n    if not pieces:\n        return []\n    predicted = sentence_model.predict([sentence for _, sentence in pieces])\n    findings = []\n    for (document, sentence), sentence_type in zip(pieces, predicted):\n        findings.append(\n            {\n                \"document_id\": document[config.DOCUMENT_ID_COLUMN],\n                \"document_type\": document.get(config.DOCUMENT_TYPE_COLUMN),\n                \"sentence\": sentence,\n                \"sentence_type\": str(sentence_type),\n            }\n        )\n    return findings\n\n\ndef link_evidence_to_requirements(findings, screening):\n    \"\"\"Record which requirements of the application's own standard each sentence bears on.\"\"\"\n    linked = []\n    for finding in findings:\n        sentence_type = finding[\"sentence_type\"]\n        if sentence_type not in config.SENTENCE_TYPE_REQUIREMENT_KINDS:\n            raise ValueError(\n                config.NO_REQUIREMENT_KINDS_MESSAGE.format(sentence_type=sentence_type)\n            )\n        kinds = config.SENTENCE_TYPE_REQUIREMENT_KINDS[sentence_type]\n        borne_on = [\n            requirement[\"requirement_name\"]\n            for requirement in screening[\"requirements\"]\n            if requirement[\"requirement_kind\"] in kinds\n        ]\n        linked.append(dict(finding, requirements_borne_on=borne_on))\n    return linked\n\n\ndef _form_rating_amps(application):\n    phases = application.get(config.EQUIPMENT_PHASES_COLUMN)\n    ratings = []\n    for column_name in config.FORM_CURRENT_RATING_COLUMNS:\n        value = application.get(column_name)\n        if not _is_blank(value):\n            ratings.append(\n                Decimal(repr(float(value))).quantize(config.AMPS_STEP, rounding=ROUND_HALF_UP)\n            )\n    for column_name in config.FORM_POWER_RATING_COLUMNS:\n        value = application.get(column_name)\n        if not _is_blank(value) and not _is_blank(phases):\n            ratings.append(\n                convert_power_to_amps_per_phase(Decimal(repr(float(value))), int(phases))\n            )\n    return ratings\n\n\ndef _stated_amps(sentence, phases):\n    stated = []\n    for match in re.finditer(config.STATED_FIGURE_PATTERN, sentence):\n        following = re.findall(config.FOLLOWING_WORD_PATTERN, sentence[match.end():].lower())\n        if any(\n            word in config.UNREAD_FIGURE_WORDS\n            for word in following[:config.FOLLOWING_WORDS_CHECKED]\n        ):\n            continue\n        number = Decimal(\n            match.group(config.STATED_NUMBER_PART).replace(config.THOUSANDS_SEPARATOR, \"\")\n        )\n        unit = match.group(config.STATED_UNIT_PART).lower()\n        if unit in config.STATED_CURRENT_UNITS:\n            stated.append(number.quantize(config.AMPS_STEP, rounding=ROUND_HALF_UP))\n            continue\n        if _is_blank(phases):\n            continue\n        stated.append(\n            convert_power_to_amps_per_phase(number * config.STATED_POWER_UNITS[unit], int(phases))\n        )\n    return stated\n\n\ndef find_disagreements(findings, application):\n    \"\"\"Flag every equipment rating sentence whose figures are none of the form's ratings.\"\"\"\n    phases = application.get(config.EQUIPMENT_PHASES_COLUMN)\n    form_ratings = _form_rating_amps(application)\n    flags = []\n    for finding in findings:\n        if finding.get(\"sentence_type\") != config.EQUIPMENT_RATING:\n            continue\n        stated = _stated_amps(finding[\"sentence\"], phases)\n        if not stated:\n            continue\n        if not form_ratings:\n            flag = config.DESCRIBES_BLANK_ANSWER\n        elif not any(amps in form_ratings for amps in stated):\n            flag = config.DISAGREES_WITH_FORM\n        else:\n            continue\n        flags.append(\n            {\n                \"document_id\": finding[\"document_id\"],\n                \"sentence\": finding[\"sentence\"],\n                \"stated_amps\": [float(amps) for amps in stated],\n                \"form_rating_amps\": [float(amps) for amps in form_ratings],\n                \"flag\": flag,\n            }\n        )\n    return flags\n"}], "commands": "git pull origin main\nmkdir -p tools\n# paste today's files, then:\ngit add tools/evidence_tools.py\ngit commit -m \"Day 3 (LangGraph): Sentence evidence, requirement links and rating disagreements\"\ngit push origin HEAD", "demo": "python - <<'EOF'\nfrom config import config\nfrom tools.evidence_tools import find_disagreements\napplication = {\"equipment_phases\": 1, \"rated_current_amps\": 32.0, \"charging_current_amps\": None, \"inverter_capacity_kw\": None}\nfindings = [{\"document_id\": \"DOC-1\", \"document_type\": \"Design statement\", \"sentence_type\": config.EQUIPMENT_RATING,\n             \"sentence\": \"The charge point draws up to 40 A on a dedicated 45 A circuit.\"},\n            {\"document_id\": \"DOC-1\", \"document_type\": \"Design statement\", \"sentence_type\": config.EQUIPMENT_RATING,\n             \"sentence\": \"The unit is rated at 7.36 kW.\"}]\nfor flag in find_disagreements(findings, application):\n    print(flag[\"flag\"], flag[\"stated_amps\"], \"vs form\", flag[\"form_rating_amps\"], \"|\", flag[\"sentence\"])\nEOF", "show": "'40 A on a dedicated 45 A circuit': the 40 is read, the 45 is not (followed by 'circuit') and 40 is not the form's 32 -> DISAGREES WITH FORM. 7.36 kW on one phase is exactly 32.0 A, so that sentence agrees and is not flagged."}, {"owner": "janavi", "summary": "Exact section reads; entry point 4 builds and reads back the store.", "files": [{"path": "tools/retrieval_tools.py", "explain": "Four exact section reads: reviewer checks (guide section 3), documentation to provide (standard section 6), connection approval (section 7) and household notice (section 8). Each checks the heading matches the configured title and returns the text without it.", "code": "\"\"\"The four section reads the workflow and the chat need, each from one document alone.\"\"\"\n\nfrom config import config\nfrom knowledge.vector_index import read_document_section\n\n\ndef _read_titled_section(collection, document_name, section_number, section_title):\n    section_text = read_document_section(collection, document_name, section_number)\n    heading = f\"{section_number}. {section_title} \"\n    if not section_text.startswith(heading):\n        raise ValueError(\n            config.SECTION_TITLE_MISMATCH_MESSAGE.format(\n                section_number=section_number,\n                document_name=document_name,\n                section_title=section_title,\n            )\n        )\n    return section_text[len(heading):]\n\n\ndef _standard_document(technology):\n    if technology not in config.CONNECTION_STANDARD_DOCUMENTS:\n        raise ValueError(config.NO_STANDARD_CONFIGURED_MESSAGE.format(technology=technology))\n    return config.CONNECTION_STANDARD_DOCUMENTS[technology]\n\n\ndef read_reviewer_checks(collection, sentence_type):\n    \"\"\"What a sentence type's statement guide says the reviewer checks.\"\"\"\n    if sentence_type not in config.SENTENCE_TYPE_GUIDE_DOCUMENTS:\n        raise ValueError(config.NO_GUIDE_CONFIGURED_MESSAGE.format(sentence_type=sentence_type))\n    return _read_titled_section(\n        collection,\n        config.SENTENCE_TYPE_GUIDE_DOCUMENTS[sentence_type],\n        config.REVIEWER_CHECKS_SECTION_NUMBER,\n        config.REVIEWER_CHECKS_SECTION_TITLE,\n    )\n\n\ndef read_documentation_to_provide(collection, technology):\n    \"\"\"What a technology's own standard asks the installer to provide.\"\"\"\n    return _read_titled_section(\n        collection,\n        _standard_document(technology),\n        config.DOCUMENTATION_SECTION_NUMBER,\n        config.DOCUMENTATION_SECTION_TITLE,\n    )\n\n\ndef read_connection_approval_guidance(collection, technology):\n    \"\"\"What a technology's own standard says the connection approval holds.\"\"\"\n    return _read_titled_section(\n        collection,\n        _standard_document(technology),\n        config.CONNECTION_APPROVAL_SECTION_NUMBER,\n        config.CONNECTION_APPROVAL_SECTION_TITLE,\n    )\n\n\ndef read_household_notice_guidance(collection, technology):\n    \"\"\"What a technology's own standard says the household notice tells.\"\"\"\n    return _read_titled_section(\n        collection,\n        _standard_document(technology),\n        config.HOUSEHOLD_NOTICE_SECTION_NUMBER,\n        config.HOUSEHOLD_NOTICE_SECTION_TITLE,\n    )\n"}, {"path": "run_knowledge_indexing.py", "explain": "Entry point 4. Reads the 16 PDFs, splits them into sections and passages, rebuilds the store in database/chroma_store and reads each standard's 'Documentation to provide' back from the store to prove each technology reads its own document.", "code": "\"\"\"Entry point 4: builds the knowledge base from the sixteen documents and reads it back.\n\nRun from the Project folder:  python run_knowledge_indexing.py\n\"\"\"\n\nfrom config import config\nfrom knowledge.chunk_splitting import build_chunk_records, split_documents_into_sections\nfrom knowledge.pdf_extraction import extract_text_from_directory\nfrom knowledge.vector_index import build_vector_index, open_vector_index\nfrom tools.retrieval_tools import read_documentation_to_provide\n\n\ndef main():\n    \"\"\"Rebuild the store, then read each standard's documentation section back from it.\"\"\"\n    documents = extract_text_from_directory(config.DOCS_DIRECTORY)\n    sections = split_documents_into_sections(documents)\n    chunks = build_chunk_records(sections)\n    stored = build_vector_index(chunks, config.VECTOR_STORE_DIRECTORY)\n    print(\n        f\"{len(documents)} documents, {len(sections)} sections, {stored} passages indexed in \"\n        f\"{config.VECTOR_STORE_DIRECTORY}\"\n    )\n    collection = open_vector_index(config.VECTOR_STORE_DIRECTORY)\n    print(\"what each connection standard asks the installer to provide, read back from the index\")\n    for technology, document_name in config.CONNECTION_STANDARD_DOCUMENTS.items():\n        section_text = read_documentation_to_provide(collection, technology)\n        print(f\"  {technology}  {document_name}\")\n        print(f\"      {section_text}\")\n\n\nif __name__ == \"__main__\":\n    main()\n"}], "commands": "git pull origin main\nmkdir -p tools\n# paste today's files, then:\ngit add tools/retrieval_tools.py run_knowledge_indexing.py\ngit commit -m \"Day 3 (RAG): Exact section reads; entry point 4 builds and reads back the store\"\ngit push origin HEAD", "demo": "python run_knowledge_indexing.py", "show": "'16 documents, 136 sections, N passages indexed in database/chroma_store' and then each technology's own section 6 'Documentation to provide' read back from the store - five different texts from five documents."}, {"owner": "aparna", "summary": "Decision page for engineers; audit trail with call budget and chat turns.", "files": [{"path": "dashboard/decision_queue.py", "explain": "Reviews waiting at the gate. Shows the recommendation, figures, requirements, triggers, flags and agents' write-ups. The engineer who opened a review is told someone else must decide; others get a form offering only the decisions open and a reason box.", "code": "\"\"\"The reviews waiting at the gate, and the form a Connections Engineer decides with.\"\"\"\n\nimport streamlit as st\n\nfrom config import config\nfrom dashboard.api_client import (\n    apply_page_style,\n    badge_html,\n    call_service,\n    page_heading,\n    show_badges,\n    signed_in_user,\n    stat_card,\n)\n\nPENDING_KEY = \"pending_decision\"\n\n\ndef _label(column_name):\n    return config.FORM_ANSWER_LABELS.get(column_name, column_name.replace(\"_\", \" \"))\n\n\ndef _show_review(review):\n    show_badges(\n        [\n            (f\"Recommends {review['recommended_decision']}\",\n             config.DECISION_BADGE_COLOURS[review[\"recommended_decision\"]]),\n            (review[\"standard_document\"], config.NEUTRAL_BADGE_COLOUR),\n        ]\n    )\n    columns = st.columns(2)\n    with columns[0]:\n        stat_card(\"%\", \"Network work likelihood\",\n                  f\"{review['network_work_likelihood']:.{config.LIKELIHOOD_DECIMALS}f}\",\n                  f\"Band {review['likelihood_band']}\",\n                  config.LIKELIHOOD_BAND_BADGE_COLOURS[review[\"likelihood_band\"]])\n    with columns[1]:\n        stat_card(\"⏱\", \"Expected working days\", review[\"expected_working_days\"],\n                  review[\"duration_text\"],\n                  config.DELAY_COLOUR if review[\"delay_expected\"] else config.NEUTRAL_BADGE_COLOUR)\n    st.markdown(\"#### Recommendation\")\n    st.markdown(review[\"recommendation_text\"])\n    st.markdown(\"#### Requirements\")\n    for requirement in review[\"requirements\"]:\n        blanks = \"\"\n        if requirement[\"blank_answers\"]:\n            blanks = \" · left blank: \" + \", \".join(_label(c) for c in requirement[\"blank_answers\"])\n        st.markdown(\n            f'<div class=\"pw-row\">{badge_html(requirement[\"result\"], config.REQUIREMENT_RESULT_BADGE_COLOURS[requirement[\"result\"]])}'\n            f\"<b>{requirement['requirement_name']}</b><small>{blanks}</small></div>\",\n            unsafe_allow_html=True,\n        )\n    if not review[\"rating_stated\"]:\n        st.warning(\"The rating is blank on the form.\")\n    st.markdown(\"#### Network triggers\")\n    if review[\"network_triggers\"]:\n        show_badges([(trigger, \"violet\") for trigger in review[\"network_triggers\"]])\n    else:\n        st.caption(\"None applies.\")\n    st.markdown(\"#### Flagged sentences\")\n    if not review[\"disagreements\"]:\n        st.caption(\"No statement sentence is flagged.\")\n    for flag in review[\"disagreements\"]:\n        st.markdown(\n            f'<div class=\"pw-row pw-flag\">{badge_html(flag[\"flag\"], config.DELAY_COLOUR)}'\n            f\"{flag['sentence']}<br><small>States \"\n            + \", \".join(f\"{a:.{config.AMPS_DECIMALS}f}\" for a in flag[\"stated_amps\"])\n            + \" A; form: \"\n            + (\", \".join(f\"{a:.{config.AMPS_DECIMALS}f}\" for a in flag[\"form_rating_amps\"]) or \"none\")\n            + \"</small></div>\",\n            unsafe_allow_html=True,\n        )\n    with st.expander(\"What was asked, and each agent's write-up\"):\n        st.markdown(f\"**Asked:** {review['coordinator_request']}\")\n        for title, key in [\n            (\"Plan\", \"review_plan_text\"),\n            (\"Requirements\", \"requirements_analysis_text\"),\n            (\"Evidence\", \"evidence_review_text\"),\n            (\"Predictions\", \"prediction_analysis_text\"),\n        ]:\n            st.markdown(f\"**{title}**\")\n            st.text(review[key])\n\n\ndef render_decision_queue_page():\n    \"\"\"List the reviews awaiting a decision and record one.\"\"\"\n    apply_page_style()\n    page_heading(config.PAGE_DECISION, \"Reviews waiting at the gate for a Connections Engineer.\")\n    waiting = call_service(\n        \"GET\", \"/reviews\", query={\"status_value\": [config.REVIEW_STATUS_AWAITING]}\n    )\n    if not waiting:\n        st.info(\"Nothing is waiting for a decision.\")\n        return\n    labels = {\n        f\"{review['application_reference']} · {config.TECHNOLOGY_LABELS[review['technology']]}\": review\n        for review in waiting\n    }\n    review = labels[st.selectbox(\"Review\", list(labels))]\n    _show_review(review)\n    st.divider()\n    user = signed_in_user()\n    if review[\"coordinator_id\"] == user[\"username\"]:\n        st.info(\n            \"You opened this review, so another Connections Engineer must decide it.\"\n        )\n        return\n    pending = st.session_state.get(PENDING_KEY, {})\n    remembered = pending if pending.get(\"review_id\") == review[\"review_id\"] else {}\n    options = review[\"decisions_open\"]\n    with st.form(\"decision_form\"):\n        decision = st.radio(\n            \"Decision\",\n            options,\n            index=options.index(remembered[\"decision\"]) if remembered.get(\"decision\") in options else 0,\n        )\n        reason = st.text_area(\n            \"Reason\",\n            value=remembered.get(\"decision_reason\", \"\"),\n            max_chars=config.DECISION_REASON_MAXIMUM_CHARACTERS,\n        )\n        submitted = st.form_submit_button(\"Record the decision\", type=\"primary\")\n    if submitted:\n        if len(reason.strip()) < config.DECISION_REASON_MINIMUM_CHARACTERS:\n            st.warning(f\"Give a reason of at least {config.DECISION_REASON_MINIMUM_CHARACTERS} characters.\")\n            return\n        st.session_state[PENDING_KEY] = {\n            \"review_id\": review[\"review_id\"], \"decision\": decision, \"decision_reason\": reason\n        }\n        decided = call_service(\n            \"POST\",\n            f\"/reviews/{review['review_id']}/decision\",\n            payload={\"decision\": decision, \"decision_reason\": reason},\n            waiting_message=f\"Recording {decision} for {review['application_reference']}\",\n        )\n        st.session_state.pop(PENDING_KEY, None)\n        st.success(\n            f\"{review['application_reference']} is {config.REVIEW_STATUS_PHRASES[decided['status']]}: \"\n            f\"{config.DECISION_OUTCOME_TEXTS[decision]}.\"\n        )\n"}, {"path": "dashboard/audit_trail.py", "explain": "Reviews filtered by status (decided ones by default) with who opened and decided them, each agent's write-up, the notices or assessment brief, the call budget (calls, tokens, seconds) and a second tab with the latest 200 chat turns from everyone.", "code": "\"\"\"What has been reviewed and decided, the record behind each review, and every chat turn.\"\"\"\n\nimport streamlit as st\n\nfrom config import config\nfrom dashboard.api_client import apply_page_style, call_service, page_heading, show_badges\n\n\ndef _label(column_name):\n    return config.FORM_ANSWER_LABELS.get(column_name, column_name.replace(\"_\", \" \"))\n\n\ndef _reviews_tab():\n    statuses = st.multiselect(\n        \"Statuses\",\n        config.REVIEW_STATUS_OPTIONS,\n        default=config.DECIDED_REVIEW_STATUSES,\n        format_func=lambda status: config.REVIEW_STATUS_LABELS[status],\n    )\n    if not statuses:\n        st.info(\"Choose at least one status.\")\n        return\n    reviews = call_service(\"GET\", \"/reviews\", query={\"status_value\": statuses})\n    if not reviews:\n        st.info(\"No review has these statuses.\")\n        return\n    st.dataframe(\n        [\n            {\n                \"Application\": review[\"application_reference\"],\n                \"Technology\": config.TECHNOLOGY_LABELS[review[\"technology\"]],\n                \"Status\": config.REVIEW_STATUS_LABELS[review[\"status\"]],\n                \"Opened by\": review[\"coordinator_id\"],\n                \"Decided by\": review[\"decided_by\"] or \"-\",\n                \"Model calls\": review[\"llm_call_count\"],\n            }\n            for review in reviews\n        ],\n        hide_index=True,\n        use_container_width=True,\n    )\n    chosen = {review[\"review_id\"]: review for review in reviews}\n    review = chosen[\n        st.selectbox(\n            \"Review\",\n            list(chosen),\n            format_func=lambda review_id: f\"{review_id} · {chosen[review_id]['application_reference']}\",\n        )\n    ]\n    show_badges(\n        [\n            (config.REVIEW_STATUS_LABELS[review[\"status\"]], config.STATUS_BADGE_COLOURS[review[\"status\"]]),\n            (review[\"assessment\"], config.DECISION_BADGE_COLOURS[review[\"assessment\"]]),\n            (review[\"standard_document\"], config.NEUTRAL_BADGE_COLOUR),\n        ]\n    )\n    st.markdown(f\"**Recommendation:** {review['recommended_decision']}  \\n{review['duration_text']}\")\n    if review[\"decision\"]:\n        st.markdown(\n            f\"**Decision:** {review['decision']} by {review['decided_by']} \"\n            f\"({review['decided_by_role']}) - {review['decision_reason']}\"\n        )\n    with st.expander(\"Each agent's write-up\"):\n        for key in [\"review_plan_text\", \"requirements_analysis_text\", \"evidence_review_text\",\n                    \"prediction_analysis_text\", \"recommendation_text\"]:\n            st.markdown(f\"**{key.replace('_text', '').replace('_', ' ').title()}**\")\n            st.text(review[key])\n    if review[\"installer_notice_text\"]:\n        kind = config.NOTICE_KINDS[review[\"decision\"]]\n        with st.expander(kind.capitalize(), expanded=True):\n            st.text(review[\"installer_notice_text\"])\n    if review[\"household_notice_text\"]:\n        with st.expander(\"Household notice\", expanded=True):\n            st.text(review[\"household_notice_text\"])\n    if review[\"assessment_brief\"]:\n        brief = review[\"assessment_brief\"]\n        with st.expander(\"Assessment brief\", expanded=True):\n            st.dataframe(\n                [{\"Answer\": _label(column), \"On the form\": str(brief.get(column))}\n                 for column in config.ASSESSMENT_BRIEF_DETAIL_COLUMNS],\n                hide_index=True, use_container_width=True,\n            )\n            st.json({key: brief[key] for key in [\"requirements\", \"network_triggers\",\n                                                 \"flagged_statements\", \"network_work_likelihood\",\n                                                 \"likelihood_band\", \"expected_working_days\",\n                                                 \"planned_working_days\", \"delay_expected\"]})\n    budget = call_service(\"GET\", f\"/reviews/{review['review_id']}/calls\")\n    seconds = budget[\"total_latency_milliseconds\"] / config.MILLISECONDS_PER_SECOND\n    st.markdown(\n        f\"**Call budget:** {budget['call_count']} of {budget['expected_call_count']} calls · \"\n        f\"{budget['total_tokens']:,} tokens · {seconds:.{config.LATENCY_SECONDS_DECIMALS}f} s\"\n    )\n    st.dataframe(budget[\"calls\"], hide_index=True, use_container_width=True)\n\n\ndef _chat_tab():\n    turns = call_service(\"GET\", \"/audit/chat-turns\", query={\"turn_limit\": config.CHAT_AUDIT_MAX_ROWS})\n    if not turns:\n        st.info(\"Nobody has asked the chat anything yet.\")\n        return\n    st.dataframe(\n        [\n            {\n                \"Asked by\": turn[\"username\"],\n                \"Role\": turn[\"user_role\"],\n                \"Type\": turn[\"question_type\"],\n                \"Application\": turn[\"application_reference\"] or \"-\",\n                \"Substation\": turn[\"substation_reference\"] or \"-\",\n                \"Refused\": \"Yes\" if turn[\"was_refused\"] else \"No\",\n                \"Question\": turn[\"question_text\"],\n                \"Answer\": turn[\"answer_text\"],\n                \"Sources\": \", \".join(turn[\"source_documents\"]),\n            }\n            for turn in turns\n        ],\n        hide_index=True,\n        use_container_width=True,\n    )\n\n\ndef render_audit_trail_page():\n    \"\"\"Reviews by status with their record and cost, and the recent chat turns.\"\"\"\n    apply_page_style()\n    page_heading(config.PAGE_AUDIT, \"Every review, decision, model call and chat turn on record.\")\n    reviews_tab, chat_tab = st.tabs([\"Reviews\", \"Chat turns\"])\n    with reviews_tab:\n        _reviews_tab()\n    with chat_tab:\n        _chat_tab()\n"}], "commands": "git pull origin main\nmkdir -p dashboard\n# paste today's files, then:\ngit add dashboard/decision_queue.py dashboard/audit_trail.py\ngit commit -m \"Day 3 (Streamlit): Decision page for engineers; audit trail with call budget and chat turns\"\ngit push origin HEAD", "demo": "python - <<'EOF'\nimport dashboard.decision_queue, dashboard.audit_trail\nprint(\"decision queue and audit trail import cleanly\")\nEOF", "show": "Walk through: only AWAITING_DECISION reviews are listed; the opener is told another engineer must decide; the form offers exactly the decisions open with a 10-1000 character reason; the audit trail shows notices, brief, call budget and every chat turn."}, {"owner": "karthik", "summary": "Counts, flags, model inputs, the pipeline; network work model; prediction tools.", "files": [{"path": "data_pipeline/feature_builder.py", "explain": "add_requirement_counts screens every past application under its own standard; add_network_trigger_flags adds the three 0/1 trigger flags; build_feature_frame lays out the model inputs in schema order (gaps as NaN); build_model_pipeline = median / most-frequent imputing + scaling + one-hot, then the estimator.", "code": "\"\"\"Requirement counts, network trigger flags, model inputs and the model pipeline.\"\"\"\n\nimport numpy as np\nimport pandas as pd\nfrom sklearn.compose import ColumnTransformer\nfrom sklearn.impute import SimpleImputer\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import OneHotEncoder, StandardScaler\n\nfrom config import config\nfrom tools.screening_tools import find_network_triggers, screen_application\n\n\ndef add_requirement_counts(dataframe, standards):\n    \"\"\"Add the Met, Not met and Not documented counts each row's own standard gives it.\"\"\"\n    counted = dataframe.copy()\n    columns = {column_name: [] for column_name in config.REQUIREMENT_COUNT_RESULTS}\n    for application in dataframe.to_dict(\"records\"):\n        technology = application[config.TECHNOLOGY_COLUMN]\n        standard = standards.get(technology)\n        if standard is None:\n            raise ValueError(\n                str(application[config.APPLICATION_REFERENCE_COLUMN]) + \": \"\n                + config.NO_STANDARD_CONFIGURED_MESSAGE.format(technology=technology)\n            )\n        screening = screen_application(application, standard)\n        for column_name in config.REQUIREMENT_COUNT_RESULTS:\n            columns[column_name].append(int(screening[column_name]))\n    for column_name, values in columns.items():\n        counted[column_name] = pd.Series(values, index=counted.index, dtype=\"int64\")\n    return counted\n\n\ndef add_network_trigger_flags(dataframe):\n    \"\"\"Add a 1/0 flag for every network trigger each row meets.\"\"\"\n    flagged = dataframe.copy()\n    flags = {column_name: [] for column_name in config.NETWORK_TRIGGER_FLAG_COLUMNS.values()}\n    for row in dataframe.to_dict(\"records\"):\n        triggers = find_network_triggers(row)\n        for trigger_name, column_name in config.NETWORK_TRIGGER_FLAG_COLUMNS.items():\n            flags[column_name].append(int(trigger_name in triggers))\n    for column_name, values in flags.items():\n        flagged[column_name] = pd.Series(values, index=flagged.index, dtype=\"int64\")\n    return flagged\n\n\ndef build_feature_frame(dataframe, numeric_columns, categorical_columns):\n    \"\"\"Lay a table out exactly as a model is fitted and scored on it.\"\"\"\n    features = pd.DataFrame(index=dataframe.index)\n    for column_name in numeric_columns:\n        features[column_name] = pd.to_numeric(\n            dataframe[column_name].astype(object).where(dataframe[column_name].notna(), np.nan),\n            errors=\"raise\",\n        ).astype(\"float64\")\n    for column_name in categorical_columns:\n        column = dataframe[column_name]\n        features[column_name] = column.astype(object).where(column.notna(), np.nan)\n    return features\n\n\ndef build_model_pipeline(estimator, numeric_columns, categorical_columns):\n    \"\"\"Join the input preparation and the estimator into one pipeline.\"\"\"\n    numbers = Pipeline(\n        [\n            (\"fill\", SimpleImputer(strategy=config.NUMBER_FILL_STRATEGY)),\n            (\"scale\", StandardScaler()),\n        ]\n    )\n    words = Pipeline(\n        [\n            (\"fill\", SimpleImputer(strategy=config.CATEGORY_FILL_STRATEGY)),\n            (\"encode\", OneHotEncoder(handle_unknown=\"ignore\")),\n        ]\n    )\n    preparation = ColumnTransformer(\n        [\n            (\"numbers\", numbers, list(numeric_columns)),\n            (\"words\", words, list(categorical_columns)),\n        ],\n        remainder=\"drop\",\n    )\n    return Pipeline(\n        [\n            (config.PREPROCESSING_STEP_NAME, preparation),\n            (config.MODEL_STEP_NAME, estimator),\n        ]\n    )\n"}, {"path": "modeling/model_registry.py", "explain": "save_model / load_model with joblib (compress=3), save_feature_schema / load_feature_schema as JSON lists, and save_metrics writing output/model_metrics.json.", "code": "\"\"\"Saves and loads the models and their feature schemas, and saves their scores.\"\"\"\n\nimport json\nimport os\n\nimport joblib\n\nfrom config import config\n\n\ndef _make_folder(file_path):\n    folder = os.path.dirname(file_path)\n    if folder:\n        os.makedirs(folder, exist_ok=True)\n\n\ndef save_model(model, file_path):\n    \"\"\"Put the whole fitted pipeline on disk, compressed, replacing any earlier file.\"\"\"\n    _make_folder(file_path)\n    joblib.dump(model, file_path, compress=config.MODEL_FILE_COMPRESSION)\n\n\ndef save_feature_schema(feature_names, file_path):\n    \"\"\"Record the columns a saved model expects, in order.\"\"\"\n    _make_folder(file_path)\n    with open(file_path, \"w\", encoding=\"utf-8\") as schema_file:\n        json.dump([str(name) for name in feature_names], schema_file, indent=config.JSON_INDENT)\n\n\ndef load_model(file_path):\n    \"\"\"Bring a saved model back, ready to score.\"\"\"\n    return joblib.load(file_path)\n\n\ndef load_feature_schema(file_path):\n    \"\"\"Read back the columns a model expects, in the order saved.\"\"\"\n    with open(file_path, encoding=\"utf-8\") as schema_file:\n        return list(json.load(schema_file))\n\n\ndef save_metrics(metrics):\n    \"\"\"Leave every model's scores on disk as sorted, indented JSON.\"\"\"\n    _make_folder(config.MODEL_METRICS_FILE)\n    with open(config.MODEL_METRICS_FILE, \"w\", encoding=\"utf-8\") as metrics_file:\n        json.dump(metrics, metrics_file, indent=config.JSON_INDENT, sort_keys=True)\n"}, {"path": "modeling/model_evaluation.py", "explain": "Scores a fitted model without refitting it: ROC AUC, Brier, mean probability and gap for the classifier; R2, MAE, average-guess MAE and prediction range for the regressor; macro/weighted F1, accuracy and per-class F1 for the text classifier.", "code": "\"\"\"Scores a fitted model on training and held-out data, never fitting it again.\"\"\"\n\nimport numpy as np\nfrom sklearn.metrics import (\n    accuracy_score,\n    brier_score_loss,\n    f1_score,\n    mean_absolute_error,\n    r2_score,\n    roc_auc_score,\n)\n\nfrom config import config\n\n\ndef _rounded(value):\n    return round(float(value), config.METRIC_DECIMALS)\n\n\ndef _positive_scores(model, features):\n    positive = list(model.classes_).index(1)\n    return model.predict_proba(features)[:, positive]\n\n\ndef evaluate_classifier(model, train_features, train_target, held_out_features,\n                        held_out_target):\n    \"\"\"How well the network work model ranks unseen applications, and whether it is calibrated.\"\"\"\n    train_scores = _positive_scores(model, train_features)\n    held_out_scores = _positive_scores(model, held_out_features)\n    train_auc = roc_auc_score(train_target, train_scores)\n    held_out_auc = roc_auc_score(held_out_target, held_out_scores)\n    return {\n        \"train_roc_auc\": _rounded(train_auc),\n        \"held_out_roc_auc\": _rounded(held_out_auc),\n        \"brier_score\": _rounded(brier_score_loss(held_out_target, held_out_scores)),\n        \"mean_predicted_probability\": _rounded(np.mean(held_out_scores)),\n        \"positive_share\": _rounded(np.mean(np.asarray(held_out_target, dtype=float))),\n        \"generalisation_gap\": _rounded(train_auc - held_out_auc),\n    }\n\n\ndef evaluate_regressor(model, train_features, train_target, held_out_features,\n                       held_out_target):\n    \"\"\"How close the duration model's working days are on unseen connections.\"\"\"\n    train_forecast = model.predict(train_features)\n    held_out_forecast = model.predict(held_out_features)\n    train_r2 = r2_score(train_target, train_forecast)\n    held_out_r2 = r2_score(held_out_target, held_out_forecast)\n    training_average = float(np.mean(np.asarray(train_target, dtype=float)))\n    return {\n        \"train_r2\": _rounded(train_r2),\n        \"held_out_r2\": _rounded(held_out_r2),\n        \"mean_absolute_error\": _rounded(mean_absolute_error(held_out_target, held_out_forecast)),\n        \"average_estimate_mean_absolute_error\": _rounded(\n            mean_absolute_error(held_out_target, [training_average] * len(held_out_target))\n        ),\n        \"lowest_prediction\": _rounded(np.min(held_out_forecast)),\n        \"highest_prediction\": _rounded(np.max(held_out_forecast)),\n        \"generalisation_gap\": _rounded(train_r2 - held_out_r2),\n    }\n\n\ndef evaluate_text_classifier(model, train_text, train_target, held_out_text, held_out_target):\n    \"\"\"How well the sentence model names every type of sentence, not only the common ones.\"\"\"\n    train_predicted = model.predict(list(train_text))\n    held_out_predicted = model.predict(list(held_out_text))\n    train_f1 = f1_score(train_target, train_predicted, average=\"macro\")\n    held_out_f1 = f1_score(held_out_target, held_out_predicted, average=\"macro\")\n    classes = list(model.classes_)\n    per_class = f1_score(\n        held_out_target, held_out_predicted, labels=classes, average=None, zero_division=0\n    )\n    return {\n        \"train_macro_f1\": _rounded(train_f1),\n        \"held_out_macro_f1\": _rounded(held_out_f1),\n        \"accuracy\": _rounded(accuracy_score(held_out_target, held_out_predicted)),\n        \"weighted_f1\": _rounded(\n            f1_score(held_out_target, held_out_predicted, average=\"weighted\")\n        ),\n        \"generalisation_gap\": _rounded(train_f1 - held_out_f1),\n        \"per_class_f1\": {\n            str(label): _rounded(score) for label, score in zip(classes, per_class)\n        },\n    }\n"}, {"path": "modeling/network_work_model.py", "explain": "train_network_work_model - logistic regression (3000 iterations) inside the shared pipeline. Linear, so one more 'Not met' or a looped service moves every score in the same direction, and its average score matches the real share of network work.", "code": "\"\"\"The network work model: how likely an application is to need work on the network.\"\"\"\n\nfrom sklearn.linear_model import LogisticRegression\n\nfrom config import config\nfrom data_pipeline.feature_builder import build_model_pipeline\nfrom modeling.model_evaluation import evaluate_classifier\n\n\ndef train_network_work_model(train_features, train_target, held_out_features,\n                             held_out_target):\n    \"\"\"Fit a calibrated logistic regression on the training applications only.\"\"\"\n    estimator = LogisticRegression(\n        max_iter=config.NETWORK_WORK_MODEL_MAXIMUM_ITERATIONS,\n        random_state=config.RANDOM_SEED,\n    )\n    model = build_model_pipeline(\n        estimator,\n        config.NETWORK_WORK_NUMERIC_FEATURES,\n        config.NETWORK_WORK_CATEGORICAL_FEATURES,\n    )\n    model.fit(train_features, train_target.astype(int))\n    scores = evaluate_classifier(\n        model, train_features, train_target, held_out_features, held_out_target\n    )\n    return model, scores\n"}, {"path": "tools/prediction_tools.py", "explain": "estimate_network_work_likelihood rounds the probability half up to 0.01 and bands it HIGH/MEDIUM/LOW; estimate_expected_working_days rounds the forecast to whole days and flags a delay only when it is more than 5 days over the plan; describe_expected_working_days words it with the config templates.", "code": "\"\"\"The network work likelihood and the expected working days of one application.\"\"\"\n\nfrom decimal import ROUND_HALF_UP, Decimal\n\nimport pandas as pd\n\nfrom config import config\nfrom data_pipeline.feature_builder import build_feature_frame\n\n\ndef _refuse_other_screening(application, screening):\n    application_reference = application.get(config.APPLICATION_REFERENCE_COLUMN)\n    if screening.get(\"application_reference\") != application_reference:\n        raise ValueError(\n            config.SCREENING_OF_ANOTHER_APPLICATION_MESSAGE.format(\n                screening_reference=screening.get(\"application_reference\"),\n                application_reference=application_reference,\n            )\n        )\n\n\ndef _model_inputs(application, screening, numeric_columns, categorical_columns,\n                  feature_names, with_counts):\n    row = dict(application)\n    if with_counts:\n        for column_name in config.REQUIREMENT_COUNT_RESULTS:\n            row[column_name] = screening[column_name]\n    for trigger_name, column_name in config.NETWORK_TRIGGER_FLAG_COLUMNS.items():\n        row[column_name] = int(trigger_name in screening[\"network_triggers\"])\n    for column_name in list(numeric_columns) + list(categorical_columns):\n        row.setdefault(column_name, None)\n    features = build_feature_frame(pd.DataFrame([row]), numeric_columns, categorical_columns)\n    if list(features.columns) != list(feature_names):\n        raise ValueError(\n            f\"The inputs {list(features.columns)} are not the saved schema \"\n            f\"{list(feature_names)} the model was fitted on\"\n        )\n    return features\n\n\ndef estimate_network_work_likelihood(network_work_model, feature_names, application,\n                                     screening):\n    \"\"\"The probability of network work, rounded half up to the step, and its band.\"\"\"\n    _refuse_other_screening(application, screening)\n    features = _model_inputs(\n        application,\n        screening,\n        config.NETWORK_WORK_NUMERIC_FEATURES,\n        config.NETWORK_WORK_CATEGORICAL_FEATURES,\n        feature_names,\n        with_counts=True,\n    )\n    positive = list(network_work_model.classes_).index(1)\n    probability = float(network_work_model.predict_proba(features)[0, positive])\n    figure = Decimal(repr(probability)).quantize(config.LIKELIHOOD_STEP, rounding=ROUND_HALF_UP)\n    if figure >= config.HIGH_LIKELIHOOD_MINIMUM:\n        band = config.HIGH_LIKELIHOOD_BAND\n    elif figure >= config.MEDIUM_LIKELIHOOD_MINIMUM:\n        band = config.MEDIUM_LIKELIHOOD_BAND\n    else:\n        band = config.LOW_LIKELIHOOD_BAND\n    return {\"network_work_likelihood\": float(figure), \"likelihood_band\": band}\n\n\ndef estimate_expected_working_days(duration_model, feature_names, application, screening):\n    \"\"\"The working days the connection is expected to take, and whether a delay is expected.\"\"\"\n    _refuse_other_screening(application, screening)\n    features = _model_inputs(\n        application,\n        screening,\n        config.DURATION_NUMERIC_FEATURES,\n        config.DURATION_CATEGORICAL_FEATURES,\n        feature_names,\n        with_counts=False,\n    )\n    forecast = float(duration_model.predict(features)[0])\n    expected = int(\n        Decimal(repr(forecast)).quantize(config.WORKING_DAY_STEP, rounding=ROUND_HALF_UP)\n    )\n    planned_value = application.get(config.PLANNED_WORKING_DAYS_COLUMN)\n    if planned_value is None or pd.isna(planned_value):\n        planned = None\n        delay = None\n    else:\n        planned = int(planned_value)\n        delay = bool(expected - planned > config.DELAY_MARGIN_WORKING_DAYS)\n    return {\n        \"expected_working_days\": expected,\n        \"planned_working_days\": planned,\n        \"delay_expected\": delay,\n    }\n\n\ndef describe_expected_working_days(duration):\n    \"\"\"The expected working days in the configuration's words.\"\"\"\n    if duration[\"delay_expected\"] is None:\n        return config.EXPECTED_DAYS_WITHOUT_PLAN_TEMPLATE.format(\n            expected_working_days=duration[\"expected_working_days\"]\n        )\n    template = config.DELAY_TEMPLATE if duration[\"delay_expected\"] else config.NO_DELAY_TEMPLATE\n    return template.format(\n        expected_working_days=duration[\"expected_working_days\"],\n        planned_working_days=duration[\"planned_working_days\"],\n    )\n"}], "commands": "git pull origin main\nmkdir -p data_pipeline modeling tools\n# paste today's files, then:\ngit add data_pipeline/feature_builder.py modeling/model_registry.py modeling/model_evaluation.py modeling/network_work_model.py tools/prediction_tools.py\ngit commit -m \"Day 3 (ML): Counts, flags, model inputs, the pipeline; network work model; prediction tools\"\ngit push origin HEAD", "demo": "python - <<'EOF'\nfrom config import config\nfrom data_pipeline.dataset_loader import load_processed_dataset\nfrom data_pipeline.feature_builder import add_requirement_counts, add_network_trigger_flags, build_feature_frame\nfrom knowledge.pdf_extraction import extract_text_from_directory\nfrom knowledge.standard_reading import read_connection_standard\nfrom modeling.network_work_model import train_network_work_model\ndocuments = extract_text_from_directory(config.DOCS_DIRECTORY)\nstandards = {t: read_connection_standard(t, documents) for t in config.CONNECTION_STANDARD_DOCUMENTS}\ndef prepare(path):\n    frame = add_network_trigger_flags(add_requirement_counts(load_processed_dataset(path), standards))\n    features = build_feature_frame(frame, config.NETWORK_WORK_NUMERIC_FEATURES, config.NETWORK_WORK_CATEGORICAL_FEATURES)\n    return features, frame[config.HISTORY_TARGET_COLUMN].map(config.NETWORK_WORK_TARGET_ENCODING)\ntrain_x, train_y = prepare(config.CLEAN_APPLICATION_HISTORY_TRAIN_FILE)\nheld_x, held_y = prepare(config.CLEAN_APPLICATION_HISTORY_EVAL_FILE)\nmodel, scores = train_network_work_model(train_x, train_y, held_x, held_y)\nprint(scores)\nEOF", "show": "Every past application screened under its own standard, the three trigger flags added, and the network work model scored on the later applications it never saw: held-out ROC AUC at least 0.82 with the mean probability close to the real positive share."}]}, {"n": 4, "title": "Models, agents and the record answers", "goal": "Train and save all three models, wire the seven Gemini agents, answer questions from the records, and add the access guard and chat page.", "check": "python run_model_training.py", "order": null, "tasks": [{"owner": "yashwanth", "summary": "The guard: 401 without a valid token, 403 outside the role's areas.", "files": [{"path": "access/permissions.py", "explain": "authorize_request - the guard on every endpoint except sign-in/out. No token or an unknown token = 401 'Sign in first'. The route's area comes from config.AREA_BY_ROUTE and a role without that area gets 403 before the endpoint runs.", "code": "\"\"\"The guard every request except signing in and out passes through.\"\"\"\n\nfrom typing import Annotated\n\nfrom fastapi import Header, HTTPException, Request\n\nfrom config import config\nfrom persistence.database import session_factory\nfrom persistence.models import UserAccount\nfrom persistence.repository import fetch_user_account\n\n\ndef authorize_request(\n    request: Request,\n    session_token: Annotated[str | None, Header(alias=config.SESSION_TOKEN_HEADER)] = None,\n):\n    \"\"\"Who is asking, and whether their role reaches the area of this route.\"\"\"\n    if not session_token:\n        raise HTTPException(status_code=401, detail=config.SIGN_IN_REQUIRED_MESSAGE)\n    with session_factory() as session:\n        account = fetch_user_account(session, UserAccount.session_token == session_token)\n    if account is None:\n        raise HTTPException(status_code=401, detail=config.SIGN_IN_REQUIRED_MESSAGE)\n    route = request.scope.get(\"route\")\n    path_template = getattr(route, \"path\", request.url.path)\n    area = config.AREA_BY_ROUTE.get((request.method, path_template))\n    if area not in config.ROLE_AREA_ACCESS.get(account[\"role\"], []):\n        raise HTTPException(\n            status_code=403,\n            detail=config.AREA_REFUSED_MESSAGE.format(role=account[\"role\"], area=area),\n        )\n    return account\n"}], "commands": "git pull origin main\nmkdir -p access\n# paste today's files, then:\ngit add access/permissions.py\ngit commit -m \"Day 4 (FastAPI): The guard: 401 without a valid token, 403 outside the role's areas\"\ngit push origin HEAD", "demo": "python - <<'EOF'\nimport secrets\nfrom typing import Annotated\nfrom fastapi import Depends, FastAPI\nfrom fastapi.testclient import TestClient\nfrom access.permissions import authorize_request\nfrom persistence.database import session_factory\nfrom persistence.repository import update_session_token\napp = FastAPI()\n@app.get(\"/queue\")\ndef queue(user: Annotated[dict, Depends(authorize_request)]):\n    return {\"hello\": user[\"username\"]}\n@app.get(\"/reviews\")\ndef reviews(user: Annotated[dict, Depends(authorize_request)]):\n    return {\"hello\": user[\"username\"]}\nclient = TestClient(app)\nprint(client.get(\"/queue\").status_code, client.get(\"/queue\").json())\ntoken = secrets.token_urlsafe(24)\nwith session_factory() as session:\n    update_session_token(session, \"zara\", token); session.commit()\nprint(client.get(\"/reviews\", headers={\"X-Session-Token\": token}).json())\nEOF", "show": "No token -> 401 'Sign in first'. A Customer Service Advisor's token on an audit route -> 403 naming the role and the area. The guard runs before the endpoint, whether or not the thing asked for exists."}, {"owner": "yash", "summary": "Gemini client, the reply parser and the seven agents.", "files": [{"path": "agentic/agents.py", "explain": "The Gemini client and the seven agents. call_language_model makes exactly one call and records tokens and latency. parse_labelled_response reads 'LABEL: text' replies even when the model adds **bold** or ## headings. Planner, requirements, evidence, risk and writer agents prepare the review; the installer-notice and household-notice agents write after the decision and every notice is checked (reference, rating figure, sign-off, no brackets, no forbidden terms, nothing withheld).", "code": "\"\"\"The language model client, the reply parser and the seven agents.\n\nEvery agent is exactly one language model call. Each is handed facts the tools\nalready established and asked for prose in labelled fields; none calculates\nanything of its own.\n\"\"\"\n\nimport os\nimport re\nimport time\nfrom decimal import Decimal, InvalidOperation\n\nfrom dotenv import load_dotenv\nfrom google import genai\nfrom google.genai import types\n\nfrom config import config\nfrom tools.application_data_tools import describe_record\nfrom tools.prediction_tools import describe_expected_working_days\n\nload_dotenv(config.ENV_FILE)\n\ngeneration_settings = types.GenerateContentConfig(\n    max_output_tokens=config.GEMINI_MAX_OUTPUT_TOKENS,\n    temperature=config.GEMINI_TEMPERATURE,\n    automatic_function_calling=types.AutomaticFunctionCallingConfig(disable=True),\n)\n\nNONE_TEXT = \"none\"\n\n\n# --------------------------------------------------------------------------- client\n\n\ndef call_language_model(prompt_text, agent_name):\n    \"\"\"Make one language model call and measure what it cost.\"\"\"\n    api_key = os.environ.get(config.GEMINI_API_KEY_VARIABLE)\n    model_name = os.environ.get(config.GEMINI_MODEL_VARIABLE)\n    if not api_key or not model_name:\n        raise ValueError(\n            f\"{agent_name} cannot call the language model: set \"\n            f\"{config.GEMINI_API_KEY_VARIABLE} and {config.GEMINI_MODEL_VARIABLE} in \"\n            f\"{config.ENV_FILE}\"\n        )\n    client = genai.Client(api_key=api_key)\n    try:\n        started = time.perf_counter()\n        response = client.models.generate_content(\n            model=model_name, contents=prompt_text, config=generation_settings\n        )\n        latency = int(round((time.perf_counter() - started) * config.MILLISECONDS_PER_SECOND))\n    finally:\n        closer = getattr(client, \"close\", None)\n        if callable(closer):\n            closer()\n    candidates = response.candidates or []\n    finish_reason = candidates[0].finish_reason if candidates else None\n    if finish_reason != types.FinishReason.STOP:\n        raise ValueError(\n            f\"{agent_name}'s reply from {model_name} did not finish normally ({finish_reason})\"\n        )\n    response_text = (response.text or \"\").strip()\n    if not response_text:\n        raise ValueError(f\"{agent_name}'s reply from {model_name} is empty\")\n    usage = response.usage_metadata\n    counts = [\n        getattr(usage, \"prompt_token_count\", None),\n        getattr(usage, \"candidates_token_count\", None),\n        getattr(usage, \"total_token_count\", None),\n    ]\n    if usage is None or any(count is None for count in counts):\n        raise ValueError(\n            f\"{agent_name}'s reply from {model_name} does not say how many tokens it used\"\n        )\n    return {\n        \"response_text\": response_text,\n        \"call_record\": {\n            \"agent_name\": agent_name,\n            \"model_name\": model_name,\n            \"prompt_tokens\": int(counts[0]),\n            \"response_tokens\": int(counts[1]),\n            \"total_tokens\": int(counts[2]),\n            \"latency_milliseconds\": latency,\n        },\n    }\n\n\n# --------------------------------------------------------------------------- replies\n\n\ndef _label_of(text_before_colon):\n    bare = re.sub(config.RESPONSE_DECORATION_EDGE_PATTERN, \"\", text_before_colon.strip())\n    bare = bare.replace(\"-\", \" \")\n    return re.sub(r\"\\s+\", \" \", bare).strip().upper()\n\n\ndef parse_labelled_response(response_text, field_labels, agent_name):\n    \"\"\"Read a labelled reply back into exactly the fields asked for.\"\"\"\n    wanted = [label.upper() for label in field_labels]\n    fields = {label: [] for label in wanted}\n    current = None\n    for raw_line in response_text.splitlines():\n        line = raw_line.replace(\"**\", \"\").strip()\n        if \":\" in line:\n            before, after = line.split(\":\", 1)\n            label = _label_of(before)\n            if label in fields:\n                current = label\n                value = after.strip(config.RESPONSE_DECORATION_CHARACTERS)\n                if value:\n                    fields[current].append(value)\n                continue\n        if current is None:\n            continue\n        if not re.sub(config.RESPONSE_DECORATION_EDGE_PATTERN, \"\", line):\n            continue\n        fields[current].append(line)\n    empty = [label for label in wanted if not \"\\n\".join(fields[label]).strip()]\n    if empty:\n        raise ValueError(\n            f\"{agent_name}'s reply leaves out or leaves empty: \" + \", \".join(empty)\n        )\n    return {\n        original: \"\\n\".join(fields[original.upper()]).strip() for original in field_labels\n    }\n\n\ndef join_labelled_response(labelled_fields):\n    \"\"\"An agent's fields written back as one text for the record.\"\"\"\n    return \"\\n\\n\".join(f\"{label}: {text}\" for label, text in labelled_fields.items())\n\n\ndef _reply_layout(field_labels):\n    lines = \"\\n\".join(f\"{label}: <your text>\" for label in field_labels)\n    return (\n        \"Reply with exactly these labelled fields, in this order, each label at the start of its \"\n        \"own line followed by a colon. Write at least two full sentences in every field unless a \"\n        \"field asks for a single value, write 'None.' in a field when nothing belongs in it, and \"\n        \"never start any other line with one of these labels:\\n\" + lines\n    )\n\n\ndef _one_line(value, field, agent_name):\n    if \"\\n\" in value.strip():\n        raise ValueError(f\"{agent_name} wrote {field} over more than one line\")\n    return value.strip()\n\n\ndef _bare_upper(value):\n    return re.sub(config.RESPONSE_DECORATION_EDGE_PATTERN, \"\", value.strip()).upper()\n\n\n# --------------------------------------------------------------------------- wording\n\n\ndef _technology_words(technology):\n    return f\"{config.TECHNOLOGY_NAMES.get(technology, technology)} ({technology})\"\n\n\ndef _label(column_name):\n    return config.FORM_ANSWER_LABELS.get(column_name, column_name.replace(\"_\", \" \"))\n\n\ndef _answers_block(application, columns):\n    described = describe_record({column: application.get(column) for column in columns})\n    return \"\\n\".join(f\"- {_label(column)}: {described[column]}\" for column in columns)\n\n\ndef _list_or_none(lines):\n    return \"\\n\".join(lines) if lines else NONE_TEXT\n\n\ndef _amps_text(values):\n    return \", \".join(f\"{float(value):.{config.AMPS_DECIMALS}f}\" for value in values) or NONE_TEXT\n\n\ndef _requirements_lines(screening, application=None, with_answers=False):\n    lines = []\n    for requirement in screening[\"requirements\"]:\n        line = (\n            f\"- {requirement['requirement_name']}: {requirement['result']}. Sentence: \"\n            f\"\\\"{requirement['requirement_sentence']}\\\"\"\n        )\n        if requirement[\"blank_answers\"]:\n            line += \" Blank answers: \" + \", \".join(\n                _label(column) for column in requirement[\"blank_answers\"]\n            ) + \".\"\n        if with_answers and application is not None:\n            columns = config.REQUIREMENT_ANSWER_COLUMNS[requirement[\"requirement_kind\"]]\n            described = describe_record({column: application.get(column) for column in columns})\n            line += \" Answers read: \" + \"; \".join(\n                f\"{_label(column)} = {described[column]}\" for column in columns\n            ) + \".\"\n        lines.append(line)\n    return _list_or_none(lines)\n\n\ndef _counts_text(screening):\n    return (\n        f\"Met {screening[config.REQUIREMENTS_MET_COUNT_COLUMN]}, Not met \"\n        f\"{screening[config.REQUIREMENTS_NOT_MET_COUNT_COLUMN]}, Not documented \"\n        f\"{screening[config.REQUIREMENTS_NOT_DOCUMENTED_COUNT_COLUMN]}; rating stated: \"\n        f\"{config.BOOLEAN_YES if screening['rating_stated'] else config.BOOLEAN_NO}\"\n    )\n\n\ndef _screening_summary(screening):\n    return (\n        f\"Standard screened under: {screening['standard_document']}\\n\"\n        f\"Requirements:\\n{_requirements_lines(screening)}\\n\"\n        f\"Counts: {_counts_text(screening)}\\n\"\n        f\"Network triggers: {', '.join(screening['network_triggers']) or NONE_TEXT}\\n\"\n        f\"Assessment: {screening['assessment']}\\n\"\n        f\"Decisions open: {', '.join(screening['decisions_open'])}\"\n    )\n\n\ndef _opening(role_text):\n    return (\n        f\"You are the {role_text} for {config.ORGANISATION_NAME}, reviewing a home low-carbon \"\n        \"connection application. Every fact below was established by the connection standards, \"\n        \"the models and the tools. Use only these facts. Do not alter any result, do not work \"\n        \"anything out yourself and do not introduce any figure that is not written below.\\n\\n\"\n    )\n\n\n# --------------------------------------------------------------------------- reviewing agents\n\n\ndef plan_review(application_profile, application_documents, screening, coordinator_request):\n    \"\"\"Decide what the review has to establish about this application.\"\"\"\n    profile = describe_record(application_profile)\n    technology = application_profile.get(config.TECHNOLOGY_COLUMN)\n    statements = [\n        f\"- {document.get(config.DOCUMENT_ID_COLUMN)}: {document.get(config.DOCUMENT_TITLE_COLUMN)}\"\n        for document in application_documents\n    ]\n    prompt = (\n        _opening(\"review planner\")\n        + \"APPLICATION\\n\"\n        f\"- Reference: {profile[config.APPLICATION_REFERENCE_COLUMN]}\\n\"\n        f\"- Portal: {profile[config.SOURCE_PORTAL_COLUMN]}\\n\"\n        f\"- Revision: {profile[config.REVISION_NUMBER_COLUMN]}\\n\"\n        f\"- Technology: {_technology_words(technology)}\\n\"\n        f\"- Premises type: {profile[config.PREMISES_TYPE_COLUMN]}\\n\"\n        f\"- Region type: {profile[config.REGION_TYPE_COLUMN]}\\n\"\n        f\"- Substation: {profile[config.SUBSTATION_REFERENCE_COLUMN]}\\n\"\n        f\"- Urgency: {profile[config.URGENCY_COLUMN]}\\n\"\n        f\"- Supply phases: {profile[config.SUPPLY_PHASES_COLUMN]}\\n\"\n        f\"- Equipment phases: {profile[config.EQUIPMENT_PHASES_COLUMN]}\\n\"\n        f\"- Service type: {profile[config.SERVICE_TYPE_COLUMN]}\\n\"\n        f\"- Cut-out rating, in amps: {profile[config.CUT_OUT_RATING_COLUMN]}\\n\\n\"\n        \"STATEMENTS ATTACHED\\n\"\n        + (_list_or_none(statements) if statements else \"No statement is attached.\")\n        + \"\\n\\nSCREENING\\n\" + _screening_summary(screening) + \"\\n\\n\"\n        f\"WHAT THE PERSON WHO OPENED THE REVIEW ASKED\\n{coordinator_request}\\n\\n\"\n        \"TASK\\nPlan the review: say which requirement or trigger deserves attention first, which \"\n        \"checks the review must make against the form and the statements, and why.\\n\\n\"\n        + _reply_layout([\"PRIORITY\", \"CHECKS\", \"RATIONALE\"])\n    )\n    reply = call_language_model(prompt, config.AGENT_NAME_PLANNER)\n    plan = parse_labelled_response(\n        reply[\"response_text\"], [\"PRIORITY\", \"CHECKS\", \"RATIONALE\"], config.AGENT_NAME_PLANNER\n    )\n    return {\"review_plan\": plan, \"call_record\": reply[\"call_record\"]}\n\n\ndef analyse_requirements(screening, application_profile, review_plan):\n    \"\"\"Account for each requirement's result and for the network triggers.\"\"\"\n    labels = [\n        \"REQUIREMENTS MET\",\n        \"REQUIREMENTS NOT MET\",\n        \"NOT DOCUMENTED\",\n        \"NETWORK TRIGGERS\",\n        \"REQUIREMENTS SUMMARY\",\n    ]\n    prompt = (\n        _opening(\"requirements analyst\")\n        + f\"STANDARD: {screening['standard_document']}\\n\\n\"\n        \"REQUIREMENTS, IN THE STANDARD'S ORDER\\n\"\n        + _requirements_lines(screening, application_profile, with_answers=True)\n        + f\"\\n\\nCOUNTS\\n{_counts_text(screening)}\\n{config.CURRENT_RULE_TEXT}\\n\\n\"\n        \"ANSWERS THE NETWORK TRIGGERS READ\\n\"\n        + _answers_block(application_profile, config.TRIGGER_ANSWER_COLUMNS)\n        + f\"\\nTriggers that apply: {', '.join(screening['network_triggers']) or NONE_TEXT}\\n\"\n        f\"{config.NETWORK_BLANK_ANSWER_RULE_TEXT}\\n\\n\"\n        f\"ASSESSMENT: {screening['assessment']}\\n{config.ASSESSMENT_RULE_TEXT}\\n\"\n        f\"Decisions open: {', '.join(screening['decisions_open'])}\\n\\n\"\n        f\"THE PLAN'S CHECKS\\n{review_plan['CHECKS']}\\n\\n\"\n        \"TASK\\nExplain each result exactly as the screening gave it, in words a Connections \"\n        \"Engineer can check against the form. Never supply a blank answer from a statement, and \"\n        \"never present the application as already decided.\\n\\n\"\n        + _reply_layout(labels)\n    )\n    reply = call_language_model(prompt, config.AGENT_NAME_REQUIREMENTS)\n    analysis = parse_labelled_response(\n        reply[\"response_text\"], labels, config.AGENT_NAME_REQUIREMENTS\n    )\n    return {\"requirements_analysis\": analysis, \"call_record\": reply[\"call_record\"]}\n\n\ndef review_evidence(evidence_findings, disagreements, reviewer_checks, application_profile,\n                    screening, review_plan):\n    \"\"\"Set the evidence in the statements beside the form.\"\"\"\n    labels = [\"EVIDENCE FOUND\", \"DISAGREEMENTS\", \"CHECKS TO MAKE\", \"EVIDENCE SUMMARY\"]\n    columns = []\n    for requirement in screening[\"requirements\"]:\n        for column in config.REQUIREMENT_ANSWER_COLUMNS[requirement[\"requirement_kind\"]]:\n            if column not in columns:\n                columns.append(column)\n    for column in config.STATEMENT_GUIDE_ANSWER_COLUMNS:\n        if column not in columns:\n            columns.append(column)\n    sentence_lines = []\n    current_document = None\n    for finding in evidence_findings:\n        if finding[\"document_id\"] != current_document:\n            current_document = finding[\"document_id\"]\n            sentence_lines.append(f\"Statement {current_document} ({finding['document_type']}):\")\n        borne = \", \".join(finding.get(\"requirements_borne_on\", [])) or NONE_TEXT\n        sentence_lines.append(\n            f\"- [{finding['sentence_type']}] {finding['sentence']} (bears on: {borne})\"\n        )\n    flag_lines = [\n        f\"- {flag['document_id']}: \\\"{flag['sentence']}\\\" states {_amps_text(flag['stated_amps'])} \"\n        f\"amps per phase; the form's ratings are {_amps_text(flag['form_rating_amps'])} amps per \"\n        f\"phase; flag {flag['flag']}\"\n        for flag in disagreements\n    ]\n    check_lines = [\n        f\"- {sentence_type}, from {config.SENTENCE_TYPE_GUIDE_DOCUMENTS[sentence_type]}: {checks}\"\n        for sentence_type, checks in reviewer_checks.items()\n    ]\n    prompt = (\n        _opening(\"evidence analyst\")\n        + \"FORM ANSWERS\\n\" + _answers_block(application_profile, columns) + \"\\n\\n\"\n        \"SENTENCES READ, STATEMENT BY STATEMENT\\n\" + _list_or_none(sentence_lines) + \"\\n\\n\"\n        \"FLAGGED SENTENCES\\n\" + _list_or_none(flag_lines) + \"\\n\\n\"\n        \"WHAT THE STATEMENT GUIDES SAY THE REVIEWER CHECKS\\n\" + _list_or_none(check_lines) + \"\\n\\n\"\n        f\"THE PLAN'S CHECKS\\n{review_plan['CHECKS']}\\n\\n\"\n        \"TASK\\nThe statements are evidence only and never a substitute for an answer on the form. \"\n        \"A flagged disagreement is left for the Connections Engineer to settle.\\n\\n\"\n        + _reply_layout(labels)\n    )\n    reply = call_language_model(prompt, config.AGENT_NAME_EVIDENCE)\n    review = parse_labelled_response(reply[\"response_text\"], labels, config.AGENT_NAME_EVIDENCE)\n    return {\"evidence_review\": review, \"call_record\": reply[\"call_record\"]}\n\n\ndef analyse_predictions(likelihood, duration, application_profile, screening, review_plan):\n    \"\"\"Interpret the network work likelihood and the expected working days.\"\"\"\n    labels = [\"LIKELIHOOD\", \"EXPECTED WORKING DAYS\", \"PREDICTION SUMMARY\"]\n    work_inputs = dict(application_profile)\n    for column in config.REQUIREMENT_COUNT_RESULTS:\n        work_inputs[column] = screening[column]\n    for trigger, column in config.NETWORK_TRIGGER_FLAG_COLUMNS.items():\n        work_inputs[column] = int(trigger in screening[\"network_triggers\"])\n    work_columns = config.NETWORK_WORK_NUMERIC_FEATURES + config.NETWORK_WORK_CATEGORICAL_FEATURES\n    days_columns = config.DURATION_NUMERIC_FEATURES + config.DURATION_CATEGORICAL_FEATURES\n    prompt = (\n        _opening(\"risk analyst\")\n        + \"NETWORK WORK LIKELIHOOD\\n\"\n        f\"- Figure: {likelihood['network_work_likelihood']:.{config.LIKELIHOOD_DECIMALS}f}, band \"\n        f\"{likelihood['likelihood_band']}\\n\"\n        f\"- Bands: {config.HIGH_LIKELIHOOD_BAND} from {config.HIGH_LIKELIHOOD_MINIMUM}, \"\n        f\"{config.MEDIUM_LIKELIHOOD_BAND} from {config.MEDIUM_LIKELIHOOD_MINIMUM}, otherwise \"\n        f\"{config.LOW_LIKELIHOOD_BAND}\\n\"\n        \"Inputs of the network work model:\\n\" + _answers_block(work_inputs, work_columns) + \"\\n\\n\"\n        \"EXPECTED WORKING DAYS\\n\"\n        f\"- {describe_expected_working_days(duration)} (a delay is expected only beyond \"\n        f\"{config.DELAY_MARGIN_WORKING_DAYS} working days over the plan)\\n\"\n        \"Inputs of the duration model:\\n\" + _answers_block(work_inputs, days_columns) + \"\\n\"\n        f\"{config.BLANK_INPUT_RULE_TEXT}\\n\\n\"\n        f\"THE PLAN'S CHECKS\\n{review_plan['CHECKS']}\\n\\n\"\n        \"TASK\\nExplain what each figure means and which inputs stand behind it. Neither figure \"\n        \"has any bearing on a requirement, a network trigger, a decision or a notice, and you \"\n        \"must not recalculate either.\\n\\n\"\n        + _reply_layout(labels)\n    )\n    reply = call_language_model(prompt, config.AGENT_NAME_RISK)\n    analysis = parse_labelled_response(reply[\"response_text\"], labels, config.AGENT_NAME_RISK)\n    return {\"prediction_analysis\": analysis, \"call_record\": reply[\"call_record\"]}\n\n\ndef write_review_recommendation(application_profile, coordinator_request, screening,\n                                likelihood, duration, review_plan, requirements_analysis,\n                                evidence_review, prediction_analysis):\n    \"\"\"Write the review a Connections Engineer decides from, recommending an open decision.\"\"\"\n    labels = [\"RECOMMENDATION\", \"RECOMMENDED DECISION\"]\n    profile = describe_record(application_profile)\n    technology = application_profile.get(config.TECHNOLOGY_COLUMN)\n    decisions = \"\\n\".join(\n        f\"- {decision}: {config.DECISION_DESCRIPTIONS[decision]} \"\n        f\"{config.DECISION_OPEN_CONDITIONS[decision]}\"\n        for decision in config.DECISIONS\n    )\n    analyst_fields = \"\\n\".join(\n        f\"{label}: {text}\"\n        for fields in [requirements_analysis, evidence_review, prediction_analysis]\n        for label, text in fields.items()\n    )\n    prompt = (\n        _opening(\"review writer\")\n        + f\"APPLICATION {profile[config.APPLICATION_REFERENCE_COLUMN]}, \"\n        f\"{_technology_words(technology)}, urgency {profile[config.URGENCY_COLUMN]}, standard \"\n        f\"{screening['standard_document']}\\n\"\n        f\"Request: {coordinator_request}\\n\\n\"\n        f\"PLAN\\nPRIORITY: {review_plan['PRIORITY']}\\nCHECKS: {review_plan['CHECKS']}\\n\\n\"\n        f\"ANALYSTS\\n{analyst_fields}\\n\\n\"\n        \"SCREENING\\n\" + _screening_summary(screening) + \"\\n\"\n        f\"{config.ASSESSMENT_RULE_TEXT}\\n\\n\"\n        f\"FIGURES (never a reason for a decision)\\n- Network work likelihood \"\n        f\"{likelihood['network_work_likelihood']:.{config.LIKELIHOOD_DECIMALS}f}, band \"\n        f\"{likelihood['likelihood_band']}\\n- {describe_expected_working_days(duration)}\\n\\n\"\n        f\"THE DECISIONS\\n{decisions}\\nDecisions open: {', '.join(screening['decisions_open'])}\\n\\n\"\n        \"TASK\\nYou only recommend; a Connections Engineer decides. Recommend the assessment, \"\n        f\"{screening['assessment']}, unless the review supports another open decision, and then \"\n        \"give that reason. Never cite either figure as a reason. RECOMMENDATION is several \"\n        \"sentences of prose whose last sentence names the decision you recommend and why. \"\n        \"RECOMMENDED DECISION is exactly one of the decisions open, on one line, and nothing \"\n        \"else.\\n\\n\"\n        + _reply_layout(labels)\n    )\n    reply = call_language_model(prompt, config.AGENT_NAME_WRITER)\n    fields = parse_labelled_response(reply[\"response_text\"], labels, config.AGENT_NAME_WRITER)\n    decision = _bare_upper(\n        _one_line(fields[\"RECOMMENDED DECISION\"], \"RECOMMENDED DECISION\", config.AGENT_NAME_WRITER)\n    )\n    if decision not in screening[\"decisions_open\"]:\n        raise ValueError(\n            f\"{config.AGENT_NAME_WRITER} recommended {decision}, which is not among the \"\n            f\"decisions open: {', '.join(screening['decisions_open'])}\"\n        )\n    fields[\"RECOMMENDED DECISION\"] = decision\n    return {\"review_recommendation\": fields, \"call_record\": reply[\"call_record\"]}\n\n\n# --------------------------------------------------------------------------- notice checks\n\n\ndef _flat(text):\n    return re.sub(r\"\\s+\", \" \", text).strip().lower()\n\n\ndef _figures(text):\n    found = []\n    for figure in re.findall(config.FIGURE_PATTERN, text.replace(config.THOUSANDS_SEPARATOR, \"\")):\n        try:\n            found.append(Decimal(figure))\n        except InvalidOperation:\n            continue\n    return found\n\n\ndef _gives_figure(text, value):\n    wanted = Decimal(repr(float(value))) if not isinstance(value, int) else Decimal(value)\n    return any(figure == wanted for figure in _figures(text))\n\n\ndef _names_technology(flat_text, technology):\n    name = config.TECHNOLOGY_NAMES.get(technology, technology).lower()\n    return name in flat_text or re.search(rf\"\\b{re.escape(technology.lower())}\\b\", flat_text)\n\n\ndef _check_sign_off_and_slots(notice, agent_name):\n    if any(character in notice for character in config.TEMPLATE_SLOT_CHARACTERS):\n        raise ValueError(f\"{agent_name} left a gap to fill in its notice\")\n\n    def spaced(text):\n        return re.sub(config.SIGN_OFF_SPACING_PATTERN, \" \", text.lower()).strip()\n\n    if not spaced(notice).endswith(spaced(config.NOTICE_SIGN_OFF)):\n        raise ValueError(f\"{agent_name}'s notice does not end with {config.NOTICE_SIGN_OFF}\")\n\n\ndef _check_forbidden_terms(flat_text, agent_name):\n    used = [term for term in config.NOTICE_FORBIDDEN_TERMS if term.lower() in flat_text]\n    if used:\n        raise ValueError(f\"{agent_name}'s notice speaks of \" + \", \".join(used))\n\n\ndef _value_words(value):\n    return describe_record({\"value\": value})[\"value\"]\n\n\n# --------------------------------------------------------------------------- notice agents\n\n\ndef draft_installer_notice(decision, application_profile, notice_details, notice_guidance):\n    \"\"\"Write the connection approval or the rework request to the installer.\"\"\"\n    agent_name = config.AGENT_NAME_INSTALLER_NOTICE\n    labels = [\"SUBJECT\", \"NOTICE\"]\n    technology = notice_details.get(config.TECHNOLOGY_COLUMN) or application_profile.get(\n        config.TECHNOLOGY_COLUMN\n    )\n    rating_column = config.RATING_COLUMNS[technology]\n    reference = notice_details.get(config.APPLICATION_REFERENCE_COLUMN)\n    kind = config.NOTICE_KINDS[decision]\n    tech_words = _technology_words(technology)\n    if decision == config.DECISION_APPROVE:\n        if notice_details.get(rating_column) is None:\n            raise ValueError(f\"{agent_name} cannot write an approval whose details give no rating\")\n        described = describe_record(notice_details)\n        detail_lines = []\n        for key in notice_details:\n            label = config.NOTICE_DETAIL_LABELS.get(key, _label(key))\n            value = tech_words if key == config.TECHNOLOGY_COLUMN else described[key]\n            detail_lines.append(f\"- {label}: {value}\")\n        required = (\n            f\"The {config.TECHNOLOGY_NAMES[technology]} for application {reference} is approved \"\n            f\"with a {config.RATING_TERMS[rating_column]} of {described[rating_column]}\"\n            + (\" amps per phase.\" if rating_column == config.RATED_CURRENT_COLUMN else \" kW.\")\n        )\n        details_text = \"\\n\".join(detail_lines)\n        must_name = []\n    else:\n        described = describe_record(\n            {\n                config.APPLICATION_REFERENCE_COLUMN: reference,\n                config.TECHNOLOGY_COLUMN: notice_details[\"technology\"],\n                \"standard_document\": notice_details[\"standard_document\"],\n            }\n        )\n        lines = [\n            f\"- {config.NOTICE_DETAIL_LABELS[config.APPLICATION_REFERENCE_COLUMN]}: \"\n            f\"{described[config.APPLICATION_REFERENCE_COLUMN]}\",\n            f\"- {config.NOTICE_DETAIL_LABELS[config.TECHNOLOGY_COLUMN]}: {tech_words}\",\n            f\"- {config.NOTICE_DETAIL_LABELS['standard_document']}: \"\n            f\"{described['standard_document']}\",\n            \"Requirements to put right:\",\n        ]\n        must_name = []\n        for requirement in notice_details[\"requirements_to_put_right\"]:\n            must_name.append(requirement[\"requirement_name\"])\n            answers = describe_record(requirement[\"form_answers\"])\n            lines.append(\n                f\"- {requirement['requirement_name']} ({requirement['result']}): \"\n                f\"\\\"{requirement['requirement_sentence']}\\\" Form answers: \"\n                + \"; \".join(f\"{_label(column)} = {text}\" for column, text in answers.items())\n                + \". Answers needed: \"\n                + (\", \".join(_label(column) for column in requirement[\"blank_answers\"])\n                   or NONE_TEXT)\n            )\n        if not notice_details[\"requirements_to_put_right\"]:\n            lines.append(f\"- {NONE_TEXT}\")\n        blank_rating = notice_details.get(\"blank_rating_answer\")\n        if blank_rating:\n            must_name.append(config.RATING_TERMS[blank_rating])\n            lines.append(\n                f\"The form leaves the {config.RATING_TERMS[blank_rating]} blank, and every \"\n                \"application states its equipment's rating.\"\n            )\n        lines.append(\n            \"Documentation to provide: \" + str(notice_details.get(\"documentation_to_provide\"))\n        )\n        flags = notice_details.get(\"flagged_statements\") or []\n        lines.append(\"Statement sentences flagged against the form:\")\n        lines.append(\n            _list_or_none(\n                [\n                    f\"- {flag['document_id']}: \\\"{flag['sentence']}\\\" states \"\n                    f\"{_amps_text(flag['stated_amps'])} amps per phase against the form's \"\n                    f\"{_amps_text(flag['form_rating_amps'])}\"\n                    for flag in flags\n                ]\n            )\n        )\n        details_text = \"\\n\".join(lines)\n        required = (\n            \"Name each of these word for word in the notice: \" + \"; \".join(must_name) + \".\"\n            if must_name\n            else \"\"\n        )\n    prompt = (\n        f\"You write the {kind} to an installer for {config.ORGANISATION_NAME}.\\n\\n\"\n        f\"DECISION: {decision}: {config.DECISION_DESCRIPTIONS[decision]}\\n\"\n        f\"The installer applied through {application_profile.get(config.SOURCE_PORTAL_COLUMN)}.\\n\\n\"\n        f\"DETAILS\\n{details_text}\\n\\n\"\n        f\"GUIDANCE\\n{notice_guidance}\\n\\n\"\n        \"RULES\\n\"\n        f\"- The SUBJECT is one line and names the application reference {reference}.\\n\"\n        f\"- Name the technology, the {config.TECHNOLOGY_NAMES[technology]}, in the notice.\\n\"\n        + (f\"- {required}\\n\" if required else \"\")\n        + \"- Use only the details above. Do not mention any model figure, any likelihood, \"\n        \"probability or expected working days, the name of anyone at the organisation, or any \"\n        \"made-up time, date or contact detail.\\n\"\n        \"- Never use square brackets and never leave a gap to fill in.\\n\"\n        f\"- The NOTICE ends with this exact line: {config.NOTICE_SIGN_OFF}\\n\\n\"\n        + _reply_layout(labels)\n    )\n    reply = call_language_model(prompt, agent_name)\n    fields = parse_labelled_response(reply[\"response_text\"], labels, agent_name)\n    subject = _one_line(fields[\"SUBJECT\"], \"SUBJECT\", agent_name)\n    if str(reference).lower() not in subject.lower():\n        raise ValueError(f\"{agent_name}'s subject does not name {reference}\")\n    flat_text = _flat(subject + \" \" + fields[\"NOTICE\"])\n    if decision == config.DECISION_APPROVE:\n        if not _names_technology(flat_text, technology):\n            raise ValueError(f\"{agent_name}'s approval does not name the technology\")\n        if not _gives_figure(flat_text, notice_details[rating_column]):\n            raise ValueError(f\"{agent_name}'s approval does not give the rating as a figure\")\n    else:\n        missing = [name for name in must_name if name.lower() not in flat_text]\n        if missing:\n            raise ValueError(f\"{agent_name}'s rework request does not name \" + \", \".join(missing))\n    _check_forbidden_terms(flat_text, agent_name)\n    _check_sign_off_and_slots(fields[\"NOTICE\"], agent_name)\n    fields[\"SUBJECT\"] = subject\n    return {\"installer_notice\": fields, \"call_record\": reply[\"call_record\"]}\n\n\ndef draft_household_notice(application_profile, household_details, household_guidance):\n    \"\"\"Write the household notice to the people who live at the premises.\"\"\"\n    agent_name = config.AGENT_NAME_HOUSEHOLD_NOTICE\n    labels = [\"HEADLINE\", \"NOTICE\"]\n    technology = household_details[config.TECHNOLOGY_COLUMN]\n    rating_column = config.RATING_COLUMNS[technology]\n    if household_details.get(rating_column) is None:\n        raise ValueError(f\"{agent_name} cannot write a household notice that gives no rating\")\n    described = describe_record(household_details)\n    equipment = config.EQUIPMENT_NAMES[technology]\n    conditions = [\n        column\n        for column in config.APPROVAL_CONDITION_COLUMNS.get(technology, [])\n        if household_details.get(column) is not None\n    ]\n    condition_lines = [\n        config.HOUSEHOLD_CONDITION_TEMPLATES[column].format(\n            equipment_name=equipment, value=described[column]\n        )\n        for column in conditions\n    ]\n    prompt = (\n        f\"You write a short, friendly household notice for {config.ORGANISATION_NAME} to the \"\n        \"people who live at a home whose low-carbon connection has been approved.\\n\\n\"\n        f\"TECHNOLOGY: {config.TECHNOLOGY_NAMES[technology]}\\n\"\n        f\"{config.NOTICE_DETAIL_LABELS[rating_column]}: {described[rating_column]}\\n\"\n        \"CONDITIONS THE HOUSEHOLD MUST KEEP TO:\\n\"\n        + (_list_or_none([f\"- {line}\" for line in condition_lines]) if condition_lines\n           else \"There is neither an export limit nor a load limiting setting.\")\n        + f\"\\n\\nGUIDANCE\\n{household_guidance}\\n\\n\"\n        \"RULES\\n\"\n        f\"- Name the technology, the {config.TECHNOLOGY_NAMES[technology]}, in the notice.\\n\"\n        + \"\".join(f\"- Include this sentence word for word: {line}\\n\" for line in condition_lines)\n        + \"- Never mention the substation, the cut-out or its rating, or the maximum demand, \"\n        \"even if the guidance does.\\n\"\n        \"- Do not mention any model figure, any likelihood, probability or expected working \"\n        \"days, the name of anyone at the organisation, or any made-up time, date or contact \"\n        \"detail.\\n\"\n        \"- Never use square brackets and never leave a gap to fill in.\\n\"\n        \"- The HEADLINE is one line.\\n\"\n        f\"- The NOTICE ends with this exact line: {config.NOTICE_SIGN_OFF}\\n\\n\"\n        + _reply_layout(labels)\n    )\n    reply = call_language_model(prompt, agent_name)\n    fields = parse_labelled_response(reply[\"response_text\"], labels, agent_name)\n    headline = _one_line(fields[\"HEADLINE\"], \"HEADLINE\", agent_name)\n    flat_text = _flat(headline + \" \" + fields[\"NOTICE\"])\n    if not _names_technology(flat_text, technology):\n        raise ValueError(f\"{agent_name}'s notice does not name the technology\")\n    for column in conditions:\n        if not _gives_figure(flat_text, household_details[column]):\n            raise ValueError(f\"{agent_name}'s notice does not give {_label(column)} as a figure\")\n    withheld = [\n        name for name, pattern in config.HOUSEHOLD_NOTICE_WITHHELD_PATTERNS.items()\n        if re.search(pattern, flat_text)\n    ]\n    if withheld:\n        raise ValueError(f\"{agent_name}'s notice names \" + \", \".join(withheld))\n    _check_forbidden_terms(flat_text, agent_name)\n    for account in config.SEED_USER_ACCOUNTS:\n        if re.search(rf\"\\b{re.escape(account['username'].lower())}\\b\", flat_text) or (\n            account[\"display_name\"].lower() in flat_text\n        ):\n            raise ValueError(f\"{agent_name}'s notice names a member of staff\")\n    _check_sign_off_and_slots(fields[\"NOTICE\"], agent_name)\n    fields[\"HEADLINE\"] = headline\n    return {\"household_notice\": fields, \"call_record\": reply[\"call_record\"]}\n"}], "commands": "git pull origin main\nmkdir -p agentic\n# paste today's files, then:\ngit add agentic/agents.py\ngit commit -m \"Day 4 (LangGraph): Gemini client, the reply parser and the seven agents\"\ngit push origin HEAD", "demo": "python - <<'EOF'\nfrom agentic.agents import parse_labelled_response, call_language_model\nreply = \"Here is the plan.\\n**PRIORITY:** The rated current.\\n## Checks: 1. Confirm the rating.\\n2. Confirm the register.\\n- RATIONALE: The form decides.\"\nprint(parse_labelled_response(reply, [\"PRIORITY\", \"CHECKS\", \"RATIONALE\"], \"review_planner_agent\"))\nresult = call_language_model(\"Reply with the single word READY.\", \"review_planner_agent\")\nprint(result[\"response_text\"], result[\"call_record\"])\nEOF", "show": "The parser reads labels even with **bold**, ## headings and bullets. The live call (needs GEMINI_API_KEY and GEMINI_MODEL in .env) returns the reply plus prompt, response and total tokens and the latency."}, {"owner": "janavi", "summary": "Per-person chat memory; record answers by role; group-size line.", "files": [{"path": "chat/conversation_memory.py", "explain": "recall_conversation gives the assistant the asker's own last 3 exchanges, oldest first. Answers that came from the records are replaced by a placeholder so nothing from the records ever reaches a prompt. search_text = previous question + new question.", "code": "\"\"\"The last few exchanges of one person's own conversation, for the next prompt and search.\"\"\"\n\nfrom config import config\nfrom persistence.models import ChatTurn\nfrom persistence.repository import fetch_chat_turns\n\n\ndef recall_conversation(session, username, question_text):\n    \"\"\"History to read and words to search with, from this person's own recent turns.\"\"\"\n    turns = fetch_chat_turns(session, ChatTurn.username == username, config.CHAT_HISTORY_TURN_LIMIT)\n    oldest_first = list(reversed(turns))\n    if not oldest_first:\n        history_text = config.CHAT_FIRST_QUESTION_TEXT\n    else:\n        exchanges = []\n        for turn in oldest_first:\n            answer = turn[\"answer_text\"]\n            if turn[\"question_type\"] in config.CHAT_RECORD_TYPES:\n                answer = config.CHAT_RECORD_ANSWER_IN_HISTORY\n            exchanges.append(f\"Question: {turn['question_text']}\\nAnswer: {answer}\")\n        history_text = \"\\n\\n\".join(exchanges)\n    previous_question = turns[0][\"question_text\"] if turns else \"\"\n    search_text = f\"{previous_question} {question_text}\".strip() if previous_question else question_text\n    return {\n        \"history_text\": history_text,\n        \"search_text\": search_text,\n        \"previous_question\": previous_question,\n    }\n"}, {"path": "chat/record_answer.py", "explain": "Answers about applications and substations from the records, never from a model. An advisor hears only technology and status (plus export limit / limiter setting once approved) and never a prediction; engineers and coordinators hear the full review record. Substation figures are given only when at least 5 premises make them up.", "code": "\"\"\"Answers from the records, never from a model, within what the asker's role allows.\"\"\"\n\nfrom config import config\nfrom persistence.models import ApplicationReview\nfrom persistence.repository import fetch_review_records\nfrom tools.application_data_tools import describe_record\n\n\ndef _advisor_status(review, technology, application_reference):\n    status_text = (\n        config.CHAT_AWAITING_REVIEW_TEXT\n        if review is None\n        else config.REVIEW_STATUS_PHRASES[review[\"status\"]]\n    )\n    line = config.CHAT_ADVISOR_STATUS_TEMPLATE.format(\n        application_reference=application_reference,\n        technology_application=config.TECHNOLOGY_APPLICATION_PHRASES[technology],\n        status=status_text,\n    )\n    if review is None or review[\"status\"] != config.REVIEW_STATUS_APPROVED:\n        return line\n    details = review.get(\"notice_details\") or {}\n    described = describe_record(details)\n    conditions = [\n        template.format(\n            equipment_name=config.EQUIPMENT_NAMES[technology], value=described[column_name]\n        )\n        for column_name, template in config.HOUSEHOLD_CONDITION_TEMPLATES.items()\n        if details.get(column_name) is not None\n    ]\n    return line + \" \" + (\" \".join(conditions) if conditions else config.CHAT_NO_CONDITIONS_TEXT)\n\n\ndef _team_lines(review):\n    requirements = \"; \".join(\n        f\"{requirement['requirement_name']} {requirement['result']}\"\n        for requirement in review[\"requirements\"]\n    )\n    type_counts = {}\n    for finding in review[\"evidence\"]:\n        type_counts[finding[\"sentence_type\"]] = type_counts.get(finding[\"sentence_type\"], 0) + 1\n    sentence_types = (\n        \", \".join(f\"{name} {count}\" for name, count in sorted(type_counts.items()))\n        or config.CHAT_NO_STATEMENTS_TEXT\n    )\n    lines = [\n        config.CHAT_REVIEW_TEMPLATE.format(\n            review_id=review[\"review_id\"],\n            application_reference=review[\"application_reference\"],\n            technology_label=config.TECHNOLOGY_LABELS[review[\"technology\"]],\n            standard_document=review[\"standard_document\"],\n            coordinator_id=review[\"coordinator_id\"],\n            status=config.REVIEW_STATUS_LABELS[review[\"status\"]],\n        ),\n        config.CHAT_SCREENING_TEMPLATE.format(\n            assessment=review[\"assessment\"],\n            requirements=requirements,\n            rating_stated=config.BOOLEAN_YES if review[\"rating_stated\"] else config.BOOLEAN_NO,\n            triggers=\"; \".join(review[\"network_triggers\"]) or config.CHAT_NO_TRIGGERS_TEXT,\n            decisions_open=\", \".join(review[\"decisions_open\"]),\n        ),\n        config.CHAT_FIGURES_TEMPLATE.format(\n            network_work_likelihood=format(\n                review[\"network_work_likelihood\"], \".\" + str(config.LIKELIHOOD_DECIMALS) + \"f\"\n            ),\n            likelihood_band=review[\"likelihood_band\"],\n            expected_working_days=review[\"duration_text\"],\n        ),\n        config.CHAT_EVIDENCE_TEMPLATE.format(\n            sentence_count=len(review[\"evidence\"]),\n            sentence_types=sentence_types,\n            flag_count=len(review[\"disagreements\"]),\n        ),\n    ]\n    if review.get(\"decision\") is None:\n        lines.append(\n            config.CHAT_AWAITING_DECISION_TEMPLATE.format(\n                recommended_decision=review[\"recommended_decision\"]\n            )\n        )\n    else:\n        lines.append(\n            config.CHAT_DECIDED_TEMPLATE.format(\n                decided_by=review[\"decided_by\"],\n                decided_by_role=review[\"decided_by_role\"],\n                decision=review[\"decision\"],\n                decision_reason=review[\"decision_reason\"],\n            )\n        )\n    return lines\n\n\ndef answer_application_record(session, signed_in_user, open_applications, question_type,\n                              application_reference):\n    \"\"\"A question about one application, answered from the review records by role.\"\"\"\n    role = signed_in_user.get(\"role\")\n    advisor = role == config.ROLE_CUSTOMER_SERVICE_ADVISOR\n    if not advisor and role not in config.ROLES_SEEING_EVERY_REVIEW:\n        raise ValueError(f\"The role {role} may not hear about an application from the records\")\n    if advisor and question_type == config.CHAT_TYPE_OUTCOME_PREDICTION:\n        return config.OUTCOME_NOT_PREDICTED_LINE\n    if not application_reference:\n        return config.CHAT_APPLICATION_NOT_NAMED_MESSAGE\n    matching = open_applications[\n        open_applications[config.APPLICATION_REFERENCE_COLUMN] == application_reference\n    ]\n    if len(matching) == 0:\n        return config.CHAT_NO_APPLICATION_TEMPLATE.format(\n            application_reference=application_reference\n        )\n    technology = matching.iloc[0][config.TECHNOLOGY_COLUMN]\n    reviews = fetch_review_records(\n        session, ApplicationReview.application_reference == application_reference\n    )\n    if advisor:\n        return _advisor_status(reviews[-1] if reviews else None, technology, application_reference)\n    if not reviews:\n        return config.CHAT_NO_REVIEW_TEMPLATE.format(application_reference=application_reference)\n    lines = []\n    for review in reviews:\n        lines.extend(_team_lines(review))\n    return \"\\n\".join(lines)\n\n\ndef answer_substation_figure(connection_history, substation_reference, technology):\n    \"\"\"A substation figure, given only where enough premises make it up.\"\"\"\n    if not substation_reference or not technology:\n        return config.CHAT_SUBSTATION_NOT_NAMED_MESSAGE\n    rows = connection_history[\n        (connection_history[config.SUBSTATION_REFERENCE_COLUMN] == substation_reference)\n        & (connection_history[config.TECHNOLOGY_COLUMN] == technology)\n    ]\n    premises_count = int(rows[config.PREMISES_REFERENCE_COLUMN].dropna().nunique())\n    if premises_count < config.GROUP_SIZE_MINIMUM:\n        return config.GROUP_SIZE_LINE\n    return config.CHAT_SUBSTATION_FIGURE_TEMPLATE.format(\n        technology_plural=config.TECHNOLOGY_PLURALS[technology],\n        premises_count=premises_count,\n        substation_reference=substation_reference,\n    )\n"}], "commands": "git pull origin main\nmkdir -p chat\n# paste today's files, then:\ngit add chat/conversation_memory.py chat/record_answer.py\ngit commit -m \"Day 4 (RAG): Per-person chat memory; record answers by role; group-size line\"\ngit push origin HEAD", "demo": "python - <<'EOF'\nfrom config import config\nfrom tools.application_data_tools import load_connection_history\nfrom chat.record_answer import answer_substation_figure\nhistory = load_connection_history()\nbusiest = history.groupby([\"substation_reference\", \"technology\"])[\"premises_reference\"].nunique().sort_values()\nsmall, large = busiest.index[0], busiest.index[-1]\nprint(answer_substation_figure(history, *large))\nprint(answer_substation_figure(history, *small))\nprint(answer_substation_figure(history, None, \"HP\"))\nEOF", "show": "A substation with enough premises gives its figure; one with fewer than five gets the group-size line, whoever asks; a question without a substation is asked to name one. No model is involved."}, {"owner": "aparna", "summary": "The chat page with type badges and sources.", "files": [{"path": "dashboard/connection_chat.py", "explain": "The chat page: your own last 20 turns oldest first, each answer badged with its question type and its sources, and a chat box limited to 1000 characters.", "code": "\"\"\"Ask the connection assistant, and see your own conversation.\"\"\"\n\nimport streamlit as st\n\nfrom config import config\nfrom dashboard.api_client import apply_page_style, call_service, page_heading, show_badges\n\n\ndef render_connection_chat_page():\n    \"\"\"The signed-in person's own conversation, oldest at the top, and the question box.\"\"\"\n    apply_page_style()\n    page_heading(config.PAGE_CHAT, \"Answers come from Merrowdale's documents and records only.\")\n    turns = call_service(\"GET\", \"/chat/turns\", query={\"turn_limit\": config.CHAT_PAGE_TURN_LIMIT})\n    for turn in reversed(turns):\n        with st.chat_message(\"user\"):\n            st.markdown(turn[\"question_text\"])\n        with st.chat_message(\"assistant\"):\n            show_badges([(turn[\"question_type\"],\n                          config.CHAT_TYPE_BADGE_COLOURS.get(turn[\"question_type\"], \"gray\"))])\n            st.markdown(turn[\"answer_text\"])\n            if turn[\"source_documents\"]:\n                st.caption(\"Sources: \" + \", \".join(turn[\"source_documents\"]))\n    question = st.chat_input(\n        \"Ask about a standard, the rules, a statement guide or an application\",\n        max_chars=config.CHAT_QUESTION_MAXIMUM_CHARACTERS,\n    )\n    if question is not None:\n        if len(question.strip()) < config.CHAT_QUESTION_MINIMUM_CHARACTERS:\n            st.warning(f\"Ask with at least {config.CHAT_QUESTION_MINIMUM_CHARACTERS} characters.\")\n            return\n        call_service(\n            \"POST\", \"/chat/ask\", payload={\"question\": question},\n            waiting_message=\"The connection assistant is reading the documents\",\n        )\n        st.rerun()\n"}], "commands": "git pull origin main\nmkdir -p dashboard\n# paste today's files, then:\ngit add dashboard/connection_chat.py\ngit commit -m \"Day 4 (Streamlit): The chat page with type badges and sources\"\ngit push origin HEAD", "demo": "python - <<'EOF'\nimport dashboard.connection_chat\nprint(\"chat page imports cleanly\")\nEOF", "show": "Walk through: your own last 20 turns oldest first, each answer badged by question type with its sources, questions under 3 characters are not sent and the box stops at 1000 characters."}, {"owner": "karthik", "summary": "Duration and sentence models; entry point 3 trains and saves all three.", "files": [{"path": "modeling/duration_model.py", "explain": "train_duration_model - random forest (300 trees, leaf >= 25, 70% features). A forest averages real working days, so it never forecasts fewer days than any connection ever took.", "code": "\"\"\"The duration model: how many working days a connection will really take.\"\"\"\n\nfrom sklearn.ensemble import RandomForestRegressor\n\nfrom config import config\nfrom data_pipeline.feature_builder import build_model_pipeline\nfrom modeling.model_evaluation import evaluate_regressor\n\n\ndef train_duration_model(train_features, train_target, held_out_features, held_out_target):\n    \"\"\"Fit a random forest on the training logs only.\n\n    A forest's forecast is an average of working days it learned from, so it is\n    never below the quickest connection in the training logs.\n    \"\"\"\n    estimator = RandomForestRegressor(\n        n_estimators=config.DURATION_FOREST_TREES,\n        min_samples_leaf=config.DURATION_FOREST_LEAF_MINIMUM,\n        max_features=config.DURATION_FOREST_FEATURE_SHARE,\n        random_state=config.RANDOM_SEED,\n        n_jobs=-1,\n    )\n    model = build_model_pipeline(\n        estimator,\n        config.DURATION_NUMERIC_FEATURES,\n        config.DURATION_CATEGORICAL_FEATURES,\n    )\n    model.fit(train_features, train_target.astype(float))\n    scores = evaluate_regressor(\n        model, train_features, train_target, held_out_features, held_out_target\n    )\n    return model, scores\n"}, {"path": "modeling/sentence_model.py", "explain": "train_sentence_model - TF-IDF word and word-pair features + balanced logistic regression, so rare sentence types are weighted as much as common ones (macro F1).", "code": "\"\"\"The sentence model: names the type of each sentence of an installer's statement.\"\"\"\n\nfrom sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.pipeline import Pipeline\n\nfrom config import config\nfrom modeling.model_evaluation import evaluate_text_classifier\n\n\ndef train_sentence_model(train_text, train_target, held_out_text, held_out_target):\n    \"\"\"Fit TF-IDF word and word-pair features with a balanced logistic regression.\"\"\"\n    model = Pipeline(\n        [\n            (\n                config.PREPROCESSING_STEP_NAME,\n                TfidfVectorizer(ngram_range=(1, 2), sublinear_tf=True, lowercase=True),\n            ),\n            (\n                config.MODEL_STEP_NAME,\n                LogisticRegression(\n                    C=10.0,\n                    class_weight=\"balanced\",\n                    max_iter=config.SENTENCE_MODEL_MAXIMUM_ITERATIONS,\n                    random_state=config.RANDOM_SEED,\n                ),\n            ),\n        ]\n    )\n    model.fit(list(train_text), list(train_target))\n    scores = evaluate_text_classifier(\n        model, train_text, train_target, held_out_text, held_out_target\n    )\n    return model, scores\n"}, {"path": "run_model_training.py", "explain": "Entry point 3. Reads the five standards, builds counts and flags, trains the three models, prints held-out / train / gap, and saves models, schemas and metrics only if every model reaches its minimum (ROC AUC 0.82, R2 0.75, macro F1 0.94).", "code": "\"\"\"Entry point 3: trains, scores and saves the three models.\n\nRun from the Project folder:  python run_model_training.py\nNothing is saved unless every model reaches the minimum the configuration sets.\n\"\"\"\n\nimport sklearn\nfrom sklearn.model_selection import train_test_split\n\nfrom config import config\nfrom data_pipeline.dataset_loader import load_processed_dataset\nfrom data_pipeline.feature_builder import (\n    add_network_trigger_flags,\n    add_requirement_counts,\n    build_feature_frame,\n)\nfrom knowledge.pdf_extraction import extract_text_from_directory\nfrom knowledge.standard_reading import read_connection_standard\nfrom modeling.duration_model import train_duration_model\nfrom modeling.model_registry import save_feature_schema, save_metrics, save_model\nfrom modeling.network_work_model import train_network_work_model\nfrom modeling.sentence_model import train_sentence_model\n\n\ndef _encoded_outcomes(frame):\n    target = frame[config.HISTORY_TARGET_COLUMN]\n    unknown = sorted(set(target.dropna().astype(str)) - set(config.NETWORK_WORK_TARGET_ENCODING))\n    if unknown or target.isna().any():\n        raise ValueError(\n            f\"{config.HISTORY_TARGET_COLUMN} holds outcomes the encoding does not know: \"\n            + \", \".join(unknown or [\"a blank outcome\"])\n        )\n    return target.map(config.NETWORK_WORK_TARGET_ENCODING).astype(int)\n\n\ndef _network_work_inputs(frame, standards):\n    prepared = add_network_trigger_flags(add_requirement_counts(frame, standards))\n    features = build_feature_frame(\n        prepared, config.NETWORK_WORK_NUMERIC_FEATURES, config.NETWORK_WORK_CATEGORICAL_FEATURES\n    )\n    return features, _encoded_outcomes(prepared)\n\n\ndef _duration_inputs(frame):\n    prepared = add_network_trigger_flags(frame)\n    features = build_feature_frame(\n        prepared, config.DURATION_NUMERIC_FEATURES, config.DURATION_CATEGORICAL_FEATURES\n    )\n    return features, prepared[config.LOG_TARGET_COLUMN].astype(float)\n\n\ndef _algorithm(model, every_step=False):\n    if every_step:\n        return \" + \".join(type(step).__name__ for _, step in model.steps)\n    return type(model.named_steps[config.MODEL_STEP_NAME]).__name__\n\n\ndef _print_scores(label, held_label, held, train, gap, extra=\"\"):\n    print(f\"  {label:<15} held-out {held_label} {held:.4f}{extra}  (train {train:.4f}, gap {gap:+.4f})\")\n\n\ndef main():\n    \"\"\"Train the three models, check each against its minimum, then save them all.\"\"\"\n    print(\"training three models\")\n    documents = extract_text_from_directory(config.DOCS_DIRECTORY)\n    standards = {\n        technology: read_connection_standard(technology, documents)\n        for technology in config.CONNECTION_STANDARD_DOCUMENTS\n    }\n\n    history_train = load_processed_dataset(config.CLEAN_APPLICATION_HISTORY_TRAIN_FILE)\n    history_eval = load_processed_dataset(config.CLEAN_APPLICATION_HISTORY_EVAL_FILE)\n    work_train_x, work_train_y = _network_work_inputs(history_train, standards)\n    work_eval_x, work_eval_y = _network_work_inputs(history_eval, standards)\n    work_model, work_scores = train_network_work_model(\n        work_train_x, work_train_y, work_eval_x, work_eval_y\n    )\n\n    logs_train = load_processed_dataset(config.CLEAN_CONNECTION_LOGS_TRAIN_FILE)\n    logs_eval = load_processed_dataset(config.CLEAN_CONNECTION_LOGS_EVAL_FILE)\n    days_train_x, days_train_y = _duration_inputs(logs_train)\n    days_eval_x, days_eval_y = _duration_inputs(logs_eval)\n    days_model, days_scores = train_duration_model(\n        days_train_x, days_train_y, days_eval_x, days_eval_y\n    )\n\n    sentences = load_processed_dataset(config.CLEAN_STATEMENT_SENTENCES_FILE)\n    text_train, text_held, type_train, type_held = train_test_split(\n        sentences[config.SENTENCE_TEXT_COLUMN],\n        sentences[config.SENTENCE_TARGET_COLUMN],\n        test_size=config.SENTENCE_HELD_OUT_SHARE,\n        stratify=sentences[config.SENTENCE_TARGET_COLUMN],\n        random_state=config.RANDOM_SEED,\n    )\n    sentence_model, sentence_scores = train_sentence_model(\n        text_train, type_train, text_held, type_held\n    )\n\n    _print_scores(\"network work\", \"ROC AUC\", work_scores[\"held_out_roc_auc\"],\n                  work_scores[\"train_roc_auc\"], work_scores[\"generalisation_gap\"])\n    _print_scores(\"duration\", \"R2\", days_scores[\"held_out_r2\"], days_scores[\"train_r2\"],\n                  days_scores[\"generalisation_gap\"],\n                  f\"  MAE {days_scores['mean_absolute_error']:.4f} working days\")\n    _print_scores(\"sentence\", \"macro F1\", sentence_scores[\"held_out_macro_f1\"],\n                  sentence_scores[\"train_macro_f1\"], sentence_scores[\"generalisation_gap\"])\n\n    shortfalls = []\n    for label, score, minimum in [\n        (\"network work held-out ROC AUC\", work_scores[\"held_out_roc_auc\"],\n         config.MINIMUM_NETWORK_WORK_ROC_AUC),\n        (\"duration held-out R2\", days_scores[\"held_out_r2\"], config.MINIMUM_DURATION_R2),\n        (\"sentence held-out macro F1\", sentence_scores[\"held_out_macro_f1\"],\n         config.MINIMUM_SENTENCE_MACRO_F1),\n    ]:\n        if score < minimum:\n            shortfalls.append(f\"{label} {score:.4f} is below {minimum}\")\n    if shortfalls:\n        raise SystemExit(\"Nothing was saved: \" + \"; \".join(shortfalls))\n\n    save_model(work_model, config.NETWORK_WORK_MODEL_FILE)\n    save_model(days_model, config.DURATION_MODEL_FILE)\n    save_model(sentence_model, config.SENTENCE_MODEL_FILE)\n    save_feature_schema(list(work_model.feature_names_in_), config.NETWORK_WORK_SCHEMA_FILE)\n    save_feature_schema(list(days_model.feature_names_in_), config.DURATION_SCHEMA_FILE)\n    save_metrics(\n        {\n            \"network_work\": {\n                \"algorithm\": _algorithm(work_model),\n                \"training_rows\": int(len(work_train_x)),\n                \"held_out_rows\": int(len(work_eval_x)),\n                \"scores\": work_scores,\n                \"minimum_required\": config.MINIMUM_NETWORK_WORK_ROC_AUC,\n                \"scikit_learn_version\": sklearn.__version__,\n            },\n            \"duration\": {\n                \"algorithm\": _algorithm(days_model),\n                \"training_rows\": int(len(days_train_x)),\n                \"held_out_rows\": int(len(days_eval_x)),\n                \"scores\": days_scores,\n                \"minimum_required\": config.MINIMUM_DURATION_R2,\n                \"scikit_learn_version\": sklearn.__version__,\n            },\n            \"sentence\": {\n                \"algorithm\": _algorithm(sentence_model, every_step=True),\n                \"training_rows\": int(len(text_train)),\n                \"held_out_rows\": int(len(text_held)),\n                \"scores\": sentence_scores,\n                \"minimum_required\": config.MINIMUM_SENTENCE_MACRO_F1,\n                \"scikit_learn_version\": sklearn.__version__,\n            },\n        }\n    )\n    print(f\"metrics written to {config.MODEL_METRICS_FILE}\")\n    print(\"every model reaches the minimum the configuration sets for it\")\n\n\nif __name__ == \"__main__\":\n    main()\n"}], "commands": "git pull origin main\nmkdir -p modeling\n# paste today's files, then:\ngit add modeling/duration_model.py modeling/sentence_model.py run_model_training.py\ngit commit -m \"Day 4 (ML): Duration and sentence models; entry point 3 trains and saves all three\"\ngit push origin HEAD", "demo": "python run_model_training.py", "show": "Three lines with held-out score, training score and gap, then 'metrics written to output/model_metrics.json' and 'every model reaches the minimum'. The models and schemas are now in output/models/."}]}, {"n": 5, "title": "Workflow, service, dashboard and tests", "goal": "Assemble the LangGraph workflow, the connection assistant, the REST service and the dashboard, then run the whole system and the test suite end to end.", "check": "python -m pytest tests.py -q", "order": "Merge order today: Yash and Janavi push first and Yashwanth merges them; then Yashwanth pulls main and pushes routes.py and run_api_service.py; Aparna pushes run_dashboard.py; everyone pulls main before the final run.", "tasks": [{"owner": "yashwanth", "summary": "The whole REST service and entry point 5.", "files": [{"path": "api/routes.py", "explain": "The FastAPI service. At import it builds the workflow and works out every queued application's detail and queue row once (no LLM). Endpoints: sign in/out, queue, detail, open a review (201, runs 5 agents to the gate), list reviews, decide (checks conflicts and refusals before resuming), call budget, chat ask/turns and the audit trail. Every ValueError/Gemini/HTTP failure becomes one 502 reply and a failed run is marked FAILED.", "code": "\"\"\"The REST service: queue, detail, review workflow, decision, call budget, chat and audit.\"\"\"\n\nimport hmac\nimport secrets\nimport threading\nfrom typing import Annotated\n\nimport httpx\nfrom fastapi import APIRouter, Depends, FastAPI, Header, HTTPException, Query, Request\nfrom fastapi.responses import JSONResponse\nfrom google.genai import errors as genai_errors\nfrom langgraph.types import Command\n\nfrom access.password_security import hash_password\nfrom access.permissions import authorize_request\nfrom agentic import nodes\nfrom agentic.graph import build_workflow\nfrom api.schemas import (\n    ApplicationDetailResponse,\n    CallBudgetResponse,\n    ChatRequest,\n    ChatResponse,\n    ChatTurnResponse,\n    DecisionRequest,\n    QueueRow,\n    ReviewRecordResponse,\n    ReviewRequest,\n    ReviewStatusValue,\n    SignedInUserResponse,\n    SignedOutResponse,\n    SignInRequest,\n    TechnologyFilter,\n)\nfrom chat.conversation_memory import recall_conversation\nfrom chat.connection_assistant import answer_from_documents\nfrom chat.record_answer import answer_application_record, answer_substation_figure\nfrom config import config\nfrom persistence.database import session_factory\nfrom persistence.models import AgentRun, ApplicationReview, ChatTurn, UserAccount\nfrom persistence.repository import (\n    fetch_agent_run,\n    fetch_chat_turns,\n    fetch_llm_calls,\n    fetch_review_records,\n    fetch_user_account,\n    insert_chat_turn,\n    update_agent_run,\n    update_session_token,\n)\nfrom tools.application_data_tools import rank_application_queue\nfrom tools.decision_tools import find_decision_refusal, find_review_conflict\nfrom tools.prediction_tools import describe_expected_working_days\n\nREQUIREMENT_DETAIL_KEYS = [\n    \"requirement_kind\",\n    \"requirement_name\",\n    \"requirement_sentence\",\n    \"result\",\n    \"blank_answers\",\n]\n\nreview_workflow = build_workflow(config.CHECKPOINT_DATABASE_FILE)\n\n\ndef _plain_screening(screening):\n    \"\"\"The screening as plain values: each requirement without its exact-decimal rules.\"\"\"\n    plain = {key: value for key, value in screening.items() if key != \"requirements\"}\n    plain[\"requirements\"] = [\n        {key: requirement[key] for key in REQUIREMENT_DETAIL_KEYS}\n        for requirement in screening[\"requirements\"]\n    ]\n    plain[\"network_triggers\"] = list(screening[\"network_triggers\"])\n    plain[\"decisions_open\"] = list(screening[\"decisions_open\"])\n    return plain\n\n\ndef _build_queue():\n    details = {}\n    rows = []\n    ranked = rank_application_queue(nodes.open_applications)\n    for position, reference in enumerate(ranked, start=1):\n        context = nodes.gather_application_context(reference)\n        screening = _plain_screening(context[\"screening\"])\n        detail = {\n            \"queue_position\": position,\n            \"application\": context[\"application_profile\"],\n            \"application_documents\": context[\"application_documents\"],\n            \"screening\": screening,\n            \"evidence_findings\": context[\"evidence_findings\"],\n            \"disagreements\": context[\"disagreements\"],\n            \"likelihood\": context[\"likelihood\"],\n            \"duration\": context[\"duration\"],\n            \"duration_text\": describe_expected_working_days(context[\"duration\"]),\n        }\n        details[reference] = detail\n        application = context[\"application_profile\"]\n        rows.append(\n            {\n                \"queue_position\": position,\n                \"application_reference\": reference,\n                \"technology\": screening[\"technology\"],\n                \"technology_label\": config.TECHNOLOGY_LABELS[screening[\"technology\"]],\n                \"source_portal\": application.get(config.SOURCE_PORTAL_COLUMN),\n                \"premises_type\": application.get(config.PREMISES_TYPE_COLUMN),\n                \"urgency\": application.get(config.URGENCY_COLUMN),\n                \"document_count\": len(context[\"application_documents\"]),\n                \"requirements_met_count\": screening[config.REQUIREMENTS_MET_COUNT_COLUMN],\n                \"requirements_not_met_count\": screening[config.REQUIREMENTS_NOT_MET_COUNT_COLUMN],\n                \"requirements_not_documented_count\": screening[\n                    config.REQUIREMENTS_NOT_DOCUMENTED_COUNT_COLUMN\n                ],\n                \"network_trigger_count\": len(screening[\"network_triggers\"]),\n                \"rating_stated\": screening[\"rating_stated\"],\n                \"assessment\": screening[\"assessment\"],\n                \"decisions_open\": screening[\"decisions_open\"],\n                \"network_work_likelihood\": context[\"likelihood\"][\"network_work_likelihood\"],\n                \"likelihood_band\": context[\"likelihood\"][\"likelihood_band\"],\n                \"expected_working_days\": context[\"duration\"][\"expected_working_days\"],\n                \"delay_expected\": context[\"duration\"][\"delay_expected\"],\n                \"disagreement_count\": len(context[\"disagreements\"]),\n            }\n        )\n    return details, rows\n\n\napplication_details, application_queue = _build_queue()\napplication_locks = {reference: threading.Lock() for reference in application_details}\n\npublic_router = APIRouter()\nguarded_router = APIRouter(dependencies=[Depends(authorize_request)])\n\nSessionTokenHeader = Annotated[str | None, Header(alias=config.SESSION_TOKEN_HEADER)]\nSignedInUser = Annotated[dict, Depends(authorize_request)]\n\n\ndef _thread_config(thread_id):\n    return {\"configurable\": {\"thread_id\": thread_id}}\n\n\ndef _hex_identifier():\n    return secrets.token_hex(config.IDENTIFIER_HEX_LENGTH // 2 + 1).upper()[\n        :config.IDENTIFIER_HEX_LENGTH\n    ]\n\n\ndef _one_review(session, review_id):\n    records = fetch_review_records(session, ApplicationReview.review_id == review_id)\n    return records[0] if records else None\n\n\ndef _turn_reply(turn):\n    reply = dict(turn)\n    sources = turn.get(\"source_documents\") or \"\"\n    reply[\"source_documents\"] = [name for name in sources.split(\", \") if name]\n    return reply\n\n\n# ------------------------------------------------------------------------ sign in and out\n\n\n@public_router.post(\"/auth/signin\", response_model=SignedInUserResponse)\ndef sign_in_user(sign_in_request: SignInRequest):\n    \"\"\"Exchange a username and password for a session token.\"\"\"\n    with session_factory() as session:\n        account = fetch_user_account(\n            session, UserAccount.username == sign_in_request.username\n        )\n        salt = account[\"password_salt\"] if account else secrets.token_hex(\n            config.PASSWORD_SALT_BYTES\n        )\n        offered = hash_password(sign_in_request.password, salt)\n        stored = account[\"password_hash\"] if account else \"\"\n        if account is None or not hmac.compare_digest(offered, stored):\n            raise HTTPException(status_code=401, detail=config.SIGN_IN_FAILED_MESSAGE)\n        token = secrets.token_urlsafe(config.SESSION_TOKEN_BYTES)\n        update_session_token(session, account[\"username\"], token)\n        session.commit()\n    return {\n        \"username\": account[\"username\"],\n        \"display_name\": account[\"display_name\"],\n        \"role\": account[\"role\"],\n        \"session_token\": token,\n        \"pages\": list(config.ROLE_PAGE_ACCESS[account[\"role\"]]),\n        \"areas\": list(config.ROLE_AREA_ACCESS[account[\"role\"]]),\n    }\n\n\n@public_router.post(\"/auth/signout\", response_model=SignedOutResponse)\ndef sign_out_user(session_token: SessionTokenHeader = None):\n    \"\"\"End a session; the token opens nothing afterwards.\"\"\"\n    if not session_token:\n        raise HTTPException(status_code=401, detail=config.SIGN_IN_REQUIRED_MESSAGE)\n    with session_factory() as session:\n        account = fetch_user_account(session, UserAccount.session_token == session_token)\n        if account is None:\n            raise HTTPException(status_code=401, detail=config.SIGN_IN_REQUIRED_MESSAGE)\n        update_session_token(session, account[\"username\"], None)\n        session.commit()\n    return {\"username\": account[\"username\"], \"signed_out\": True}\n\n\n# ------------------------------------------------------------------------ queue and detail\n\n\n@guarded_router.get(\"/queue\", response_model=list[QueueRow])\ndef list_application_queue(technology: TechnologyFilter):\n    \"\"\"The ranked open applications, all of them or one technology's.\"\"\"\n    if technology == config.QUEUE_TECHNOLOGY_ALL:\n        return application_queue\n    return [row for row in application_queue if row[\"technology\"] == technology]\n\n\n@guarded_router.get(\"/queue/{application_reference}\", response_model=ApplicationDetailResponse)\ndef get_application_detail(application_reference: str):\n    \"\"\"One application with everything the review would work from.\"\"\"\n    detail = application_details.get(application_reference)\n    if detail is None:\n        raise HTTPException(\n            status_code=404,\n            detail=config.UNKNOWN_APPLICATION_MESSAGE.format(\n                application_reference=application_reference\n            ),\n        )\n    return detail\n\n\n# ------------------------------------------------------------------------ reviews\n\n\n@guarded_router.post(\"/reviews\", response_model=ReviewRecordResponse, status_code=201)\ndef start_application_review(review_request: ReviewRequest, signed_in_user: SignedInUser,\n                             request: Request):\n    \"\"\"Run the five reviewing agents and leave the application waiting for an engineer.\"\"\"\n    reference = review_request.application_reference\n    if reference not in application_details:\n        raise HTTPException(\n            status_code=404,\n            detail=config.UNKNOWN_APPLICATION_MESSAGE.format(application_reference=reference),\n        )\n    with application_locks[reference]:\n        with session_factory() as session:\n            existing = fetch_review_records(\n                session, ApplicationReview.application_reference == reference\n            )\n        if existing:\n            raise HTTPException(\n                status_code=409,\n                detail=config.APPLICATION_ALREADY_REVIEWED_MESSAGE.format(\n                    application_reference=reference\n                ),\n            )\n        thread_id = f\"{reference}-{_hex_identifier()}\"\n        request.state.opened_thread_id = thread_id\n        review_workflow.invoke(\n            {\n                \"application_reference\": reference,\n                \"coordinator_request\": review_request.coordinator_request,\n                \"coordinator_id\": signed_in_user[\"username\"],\n                \"thread_id\": thread_id,\n                \"llm_call_count\": 0,\n            },\n            _thread_config(thread_id),\n        )\n        review_id = review_workflow.get_state(_thread_config(thread_id)).values[\"review_id\"]\n        with session_factory() as session:\n            return _one_review(session, review_id)\n\n\n@guarded_router.get(\"/reviews\", response_model=list[ReviewRecordResponse])\ndef list_application_reviews(status_value: Annotated[list[ReviewStatusValue], Query()]):\n    \"\"\"Every review whose status is one of those asked for, by application reference.\"\"\"\n    with session_factory() as session:\n        return fetch_review_records(session, ApplicationReview.status.in_(list(status_value)))\n\n\n@guarded_router.post(\"/reviews/{review_id}/decision\", response_model=ReviewRecordResponse)\ndef submit_review_decision(review_id: str, decision_request: DecisionRequest,\n                           signed_in_user: SignedInUser):\n    \"\"\"Check the decision, then resume the paused run with it.\"\"\"\n    with session_factory() as session:\n        review = _one_review(session, review_id)\n    if review is None:\n        raise HTTPException(status_code=404, detail=config.REVIEW_NOT_FOUND_MESSAGE)\n    reference = review[\"application_reference\"]\n    if reference not in application_details:\n        raise ValueError(\n            config.REVIEW_OUTSIDE_QUEUE_MESSAGE.format(\n                review_id=review_id, application_reference=reference\n            )\n        )\n    review_decision = {\n        \"decision\": decision_request.decision,\n        \"decided_by\": signed_in_user[\"username\"],\n        \"decided_by_role\": signed_in_user[\"role\"],\n        \"decision_reason\": decision_request.decision_reason,\n    }\n    thread = _thread_config(review[\"thread_id\"])\n    with application_locks[reference]:\n        with session_factory() as session:\n            review = _one_review(session, review_id)\n        snapshot = review_workflow.get_state(thread)\n        if not snapshot.values:\n            raise ValueError(\n                config.CHECKPOINT_MISSING_MESSAGE.format(\n                    review_id=review_id, checkpoint_file=config.CHECKPOINT_DATABASE_FILE\n                )\n            )\n        pending = snapshot.values.get(\"review_decision\")\n        refusal = find_review_conflict(review[\"status\"], pending, review_decision, reference)\n        if refusal is None:\n            refusal = find_decision_refusal(\n                review_decision, snapshot.values[\"screening\"], snapshot.values[\"coordinator_id\"]\n            )\n        if refusal is not None:\n            raise HTTPException(status_code=409, detail=refusal)\n        if pending:\n            review_workflow.invoke(None, thread)\n        else:\n            review_workflow.invoke(Command(resume=review_decision), thread)\n        with session_factory() as session:\n            return _one_review(session, review_id)\n\n\n@guarded_router.get(\"/reviews/{review_id}/calls\", response_model=CallBudgetResponse)\ndef get_call_budget(review_id: str):\n    \"\"\"Every language model call the review's run made, against the number allowed.\"\"\"\n    with session_factory() as session:\n        review = _one_review(session, review_id)\n        if review is None:\n            raise HTTPException(status_code=404, detail=config.REVIEW_NOT_FOUND_MESSAGE)\n        calls = fetch_llm_calls(session, review[\"run_id\"])\n    if review[\"decision\"] is not None:\n        expected = config.LLM_CALLS_BY_DECISION[review[\"decision\"]]\n    else:\n        snapshot = review_workflow.get_state(_thread_config(review[\"thread_id\"]))\n        if not snapshot.values:\n            raise ValueError(\n                config.CHECKPOINT_MISSING_MESSAGE.format(\n                    review_id=review_id, checkpoint_file=config.CHECKPOINT_DATABASE_FILE\n                )\n            )\n        pending = snapshot.values.get(\"review_decision\")\n        expected = (\n            config.LLM_CALLS_BY_DECISION[pending[\"decision\"]]\n            if pending\n            else config.LLM_CALLS_BEFORE_DECISION\n        )\n    return {\n        \"review_id\": review_id,\n        \"run_id\": review[\"run_id\"],\n        \"calls\": calls,\n        \"call_count\": len(calls),\n        \"expected_call_count\": expected,\n        \"total_tokens\": sum(call[\"total_tokens\"] for call in calls),\n        \"total_latency_milliseconds\": sum(call[\"latency_milliseconds\"] for call in calls),\n    }\n\n\n# ------------------------------------------------------------------------ chat and audit\n\n\n@guarded_router.post(\"/chat/ask\", response_model=ChatResponse)\ndef ask_connection_assistant(chat_request: ChatRequest, signed_in_user: SignedInUser):\n    \"\"\"Answer one question from the documents or the records, or refuse, and record it.\"\"\"\n    with session_factory() as session:\n        conversation = recall_conversation(\n            session, signed_in_user[\"username\"], chat_request.question\n        )\n        reply = answer_from_documents(\n            nodes.knowledge_collection,\n            nodes.knowledge_documents,\n            chat_request.question,\n            conversation,\n        )\n        if reply[\"question_type\"] in config.CHAT_APPLICATION_TYPES:\n            reply[\"answer\"] = answer_application_record(\n                session,\n                signed_in_user,\n                nodes.open_applications,\n                reply[\"question_type\"],\n                reply[\"application_reference\"],\n            )\n        elif reply[\"question_type\"] == config.CHAT_TYPE_SUBSTATION_FIGURE:\n            reply[\"answer\"] = answer_substation_figure(\n                nodes.connection_history, reply[\"substation_reference\"], reply[\"technology\"]\n            )\n        insert_chat_turn(\n            session,\n            {\n                \"username\": signed_in_user[\"username\"],\n                \"user_role\": signed_in_user[\"role\"],\n                \"question_text\": chat_request.question,\n                \"question_type\": reply[\"question_type\"],\n                \"application_reference\": reply[\"application_reference\"],\n                \"substation_reference\": reply[\"substation_reference\"],\n                \"technology\": reply[\"technology\"],\n                \"answer_text\": reply[\"answer\"],\n                \"source_documents\": \", \".join(reply[\"source_documents\"]),\n                \"closest_distance\": reply[\"closest_distance\"],\n                \"was_refused\": reply[\"was_refused\"],\n            },\n        )\n        session.commit()\n    return reply\n\n\n@guarded_router.get(\"/chat/turns\", response_model=list[ChatTurnResponse])\ndef list_own_chat_turns(signed_in_user: SignedInUser,\n                        turn_limit: Annotated[int, Query(ge=1, le=config.CHAT_AUDIT_MAX_ROWS)]):\n    \"\"\"The signed-in person's own turns, newest first.\"\"\"\n    with session_factory() as session:\n        turns = fetch_chat_turns(\n            session, ChatTurn.username == signed_in_user[\"username\"], turn_limit\n        )\n    return [_turn_reply(turn) for turn in turns]\n\n\n@guarded_router.get(\"/audit/chat-turns\", response_model=list[ChatTurnResponse])\ndef list_recent_chat_turns(turn_limit: Annotated[int, Query(ge=1, le=config.CHAT_AUDIT_MAX_ROWS)]):\n    \"\"\"Every recent turn, whoever asked, newest first.\"\"\"\n    with session_factory() as session:\n        turns = fetch_chat_turns(session, ChatTurn.turn_id.is_not(None), turn_limit)\n    return [_turn_reply(turn) for turn in turns]\n\n\n# ------------------------------------------------------------------------ failures\n\n\ndef report_failed_request(request: Request, failure: Exception):\n    \"\"\"Turn every failure into one 502 reply, and never leave a failed run looking alive.\"\"\"\n    thread_id = getattr(request.state, \"opened_thread_id\", None)\n    if thread_id:\n        with session_factory() as session:\n            run = fetch_agent_run(session, AgentRun.thread_id == thread_id)\n            if run is not None:\n                calls = fetch_llm_calls(session, run[\"run_id\"])\n                update_agent_run(\n                    session, run[\"run_id\"], config.AGENT_RUN_STATUS_FAILED, len(calls)\n                )\n                session.commit()\n    return JSONResponse(\n        status_code=502,\n        content={\n            \"detail\": f\"{request.method} {request.url.path} could not be completed: {failure}\"\n        },\n    )\n\n\nservice_application = FastAPI(title=config.API_TITLE)\nservice_application.include_router(public_router)\nservice_application.include_router(guarded_router)\nservice_application.add_exception_handler(ValueError, report_failed_request)\nservice_application.add_exception_handler(genai_errors.APIError, report_failed_request)\nservice_application.add_exception_handler(httpx.HTTPError, report_failed_request)\n"}, {"path": "run_api_service.py", "explain": "Entry point 5. Checks every file the service needs (cleaned data, models, schemas, live files, documents, vector store, database) and names anything missing with the script that makes it; otherwise starts uvicorn on port 8081 with docs at /docs.", "code": "\"\"\"Entry point 5: starts the REST service on port 8081, after checking its inputs exist.\n\nRun from the Project folder:  python run_api_service.py   (leave it running)\n\"\"\"\n\nimport os\nimport sys\n\nfrom config import config\n\nREQUIRED_BEFORE_STARTING = [\n    (config.CLEAN_APPLICATION_HISTORY_TRAIN_FILE, \"run_data_pipeline.py\"),\n    (config.CLEAN_APPLICATION_HISTORY_EVAL_FILE, \"run_data_pipeline.py\"),\n    (config.NETWORK_WORK_MODEL_FILE, \"run_model_training.py\"),\n    (config.DURATION_MODEL_FILE, \"run_model_training.py\"),\n    (config.SENTENCE_MODEL_FILE, \"run_model_training.py\"),\n    (config.NETWORK_WORK_SCHEMA_FILE, \"run_model_training.py\"),\n    (config.DURATION_SCHEMA_FILE, \"run_model_training.py\"),\n    (config.OPEN_APPLICATIONS_FILE, \"the supplied project files\"),\n    (config.APPLICATION_DOCUMENTS_FILE, \"the supplied project files\"),\n    (config.DOCS_DIRECTORY, \"the supplied project files\"),\n    (os.path.join(config.VECTOR_STORE_DIRECTORY, config.VECTOR_STORE_FILE_NAME),\n     \"run_knowledge_indexing.py\"),\n    (config.APPLICATION_DATABASE_FILE, \"run_database_setup.py\"),\n]\n\n\ndef main():\n    \"\"\"Start the service where the earlier stages have run; explain what is missing otherwise.\"\"\"\n    missing = [(path, source) for path, source in REQUIRED_BEFORE_STARTING\n               if not os.path.exists(path)]\n    if missing:\n        print(\"The service cannot start.\")\n        for path, source in missing:\n            print(f\"  {path} is missing; it comes from {source}\")\n        return 1\n    import uvicorn\n\n    from api.routes import service_application\n\n    print(f\"Starting {config.API_TITLE} on port {config.API_PORT}.\")\n    print(f\"Interactive documentation: {config.API_BASE_URL}/docs\")\n    uvicorn.run(service_application, host=config.API_HOST, port=config.API_PORT)\n    return 0\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n"}], "commands": "git pull origin main\nmkdir -p api\n# paste today's files, then:\ngit add api/routes.py run_api_service.py\ngit commit -m \"Day 5 (FastAPI): The whole REST service and entry point 5\"\ngit push origin HEAD", "demo": "python run_api_service.py\n# open http://localhost:8081/docs  (leave it running)", "show": "The service starts on 8081. In /docs: sign in as ravi / 22222222, copy the session_token into X-Session-Token, call GET /queue?technology=All (40 ranked rows), POST /reviews (201 after 5 model calls), then sign in as lewis and POST the decision. megan deciding her own review gets 409."}, {"owner": "yash", "summary": "The ten workflow steps and the compiled, checkpointed graph.", "files": [{"path": "agentic/nodes.py", "explain": "Loads every shared resource once (live queue, statements, history, 16 documents, vector store, three models and schemas) and defines the ten workflow steps. Each agent node records its LLM call straight away. The prepare node stores the review AWAITING_DECISION with 5 calls; the gate node interrupts until an engineer decides; the record node writes the decision, notices or brief and closes the run COMPLETE.", "code": "\"\"\"The ten workflow steps, the router, and the context every node and the service share.\n\nEach node takes the state, does one thing and returns only the keys it wrote.\nA node that calls an agent records the call against the run as soon as the\nagent returns it, and returns llm_call_count as 1.\n\"\"\"\n\nimport secrets\n\nfrom langgraph.types import interrupt\n\nfrom agentic import agents\nfrom config import config\nfrom knowledge.pdf_extraction import extract_text_from_directory\nfrom knowledge.standard_reading import read_connection_standard\nfrom knowledge.vector_index import open_vector_index\nfrom modeling.model_registry import load_feature_schema, load_model\nfrom persistence.database import session_factory\nfrom persistence.repository import (\n    insert_agent_run,\n    insert_application_review,\n    insert_llm_call,\n    insert_review_decision,\n    record_review_outcome,\n    update_agent_run,\n)\nfrom tools.application_data_tools import (\n    fetch_application,\n    fetch_application_documents,\n    load_application_documents,\n    load_connection_history,\n    load_open_applications,\n)\nfrom tools.decision_tools import find_decision_refusal\nfrom tools.evidence_tools import (\n    find_disagreements,\n    link_evidence_to_requirements,\n    read_document_evidence,\n)\nfrom tools.notice_tools import (\n    build_approval_details,\n    build_assessment_brief,\n    build_household_notice_details,\n    build_rework_details,\n)\nfrom tools.prediction_tools import (\n    describe_expected_working_days,\n    estimate_expected_working_days,\n    estimate_network_work_likelihood,\n)\nfrom tools.retrieval_tools import (\n    read_connection_approval_guidance,\n    read_documentation_to_provide,\n    read_household_notice_guidance,\n    read_reviewer_checks,\n)\nfrom tools.screening_tools import screen_application\n\n# ---------------------------------------------------------------- module-level resources\nopen_applications = load_open_applications()\nopen_application_documents = load_application_documents()\nconnection_history = load_connection_history()\nknowledge_documents = extract_text_from_directory(config.DOCS_DIRECTORY)\nknowledge_collection = open_vector_index(config.VECTOR_STORE_DIRECTORY)\nnetwork_work_model = load_model(config.NETWORK_WORK_MODEL_FILE)\nnetwork_work_feature_names = load_feature_schema(config.NETWORK_WORK_SCHEMA_FILE)\nduration_model = load_model(config.DURATION_MODEL_FILE)\nduration_feature_names = load_feature_schema(config.DURATION_SCHEMA_FILE)\nsentence_model = load_model(config.SENTENCE_MODEL_FILE)\n\nREQUIREMENT_RECORD_KEYS = [\n    \"requirement_kind\",\n    \"requirement_name\",\n    \"requirement_sentence\",\n    \"result\",\n    \"blank_answers\",\n]\n\n\ndef _identifier(prefix):\n    return prefix + secrets.token_hex(config.IDENTIFIER_HEX_LENGTH // 2 + 1).upper()[\n        :config.IDENTIFIER_HEX_LENGTH\n    ]\n\n\ndef _record_call(run_id, call_record):\n    with session_factory() as session:\n        insert_llm_call(session, run_id, call_record)\n        session.commit()\n\n\ndef gather_application_context(application_reference):\n    \"\"\"Everything about one application that needs no language model.\"\"\"\n    application = fetch_application(open_applications, application_reference)\n    documents = fetch_application_documents(open_application_documents, application)\n    technology = application[config.TECHNOLOGY_COLUMN]\n    standard = read_connection_standard(technology, knowledge_documents)\n    screening = screen_application(application, standard)\n    findings = link_evidence_to_requirements(\n        read_document_evidence(sentence_model, documents), screening\n    )\n    disagreements = find_disagreements(findings, application)\n    likelihood = estimate_network_work_likelihood(\n        network_work_model, network_work_feature_names, application, screening\n    )\n    duration = estimate_expected_working_days(\n        duration_model, duration_feature_names, application, screening\n    )\n    return {\n        \"application_profile\": application,\n        \"application_documents\": documents,\n        \"screening\": screening,\n        \"evidence_findings\": findings,\n        \"disagreements\": disagreements,\n        \"likelihood\": likelihood,\n        \"duration\": duration,\n    }\n\n\ndef load_application_context_node(state):\n    \"\"\"Gather the application's context and open the run.\"\"\"\n    run_id = _identifier(config.RUN_ID_PREFIX)\n    review_id = _identifier(config.REVIEW_ID_PREFIX)\n    context = gather_application_context(state[\"application_reference\"])\n    with session_factory() as session:\n        insert_agent_run(\n            session,\n            {\n                \"run_id\": run_id,\n                \"thread_id\": state[\"thread_id\"],\n                \"application_reference\": state[\"application_reference\"],\n                \"coordinator_id\": state[\"coordinator_id\"],\n                \"coordinator_request\": state[\"coordinator_request\"],\n                \"status\": config.AGENT_RUN_STATUS_RUNNING,\n                \"llm_call_count\": 0,\n            },\n        )\n        session.commit()\n    return dict(context, run_id=run_id, review_id=review_id)\n\n\ndef plan_application_review_node(state):\n    \"\"\"Ask the planner what the review has to establish.\"\"\"\n    reply = agents.plan_review(\n        state[\"application_profile\"],\n        state[\"application_documents\"],\n        state[\"screening\"],\n        state[\"coordinator_request\"],\n    )\n    _record_call(state[\"run_id\"], reply[\"call_record\"])\n    return {\"review_plan\": reply[\"review_plan\"], \"llm_call_count\": 1}\n\n\ndef assess_connection_requirements_node(state):\n    \"\"\"Ask the requirements analyst to explain the screening.\"\"\"\n    reply = agents.analyse_requirements(\n        state[\"screening\"], state[\"application_profile\"], state[\"review_plan\"]\n    )\n    _record_call(state[\"run_id\"], reply[\"call_record\"])\n    return {\"requirements_analysis\": reply[\"requirements_analysis\"], \"llm_call_count\": 1}\n\n\ndef analyse_installer_statements_node(state):\n    \"\"\"Ask the evidence analyst to review the statements with the guides' checks in hand.\"\"\"\n    found_types = {finding[\"sentence_type\"] for finding in state[\"evidence_findings\"]}\n    reviewer_checks = {\n        sentence_type: read_reviewer_checks(knowledge_collection, sentence_type)\n        for sentence_type in config.SENTENCE_TYPE_GUIDE_DOCUMENTS\n        if sentence_type in found_types\n    }\n    reply = agents.review_evidence(\n        state[\"evidence_findings\"],\n        state[\"disagreements\"],\n        reviewer_checks,\n        state[\"application_profile\"],\n        state[\"screening\"],\n        state[\"review_plan\"],\n    )\n    _record_call(state[\"run_id\"], reply[\"call_record\"])\n    return {\"evidence_review\": reply[\"evidence_review\"], \"llm_call_count\": 1}\n\n\ndef interpret_model_predictions_node(state):\n    \"\"\"Ask the risk analyst to explain the two figures.\"\"\"\n    reply = agents.analyse_predictions(\n        state[\"likelihood\"],\n        state[\"duration\"],\n        state[\"application_profile\"],\n        state[\"screening\"],\n        state[\"review_plan\"],\n    )\n    _record_call(state[\"run_id\"], reply[\"call_record\"])\n    return {\"prediction_analysis\": reply[\"prediction_analysis\"], \"llm_call_count\": 1}\n\n\ndef prepare_review_recommendation_node(state):\n    \"\"\"Ask the writer for the recommendation and store the review waiting at the gate.\"\"\"\n    reply = agents.write_review_recommendation(\n        state[\"application_profile\"],\n        state[\"coordinator_request\"],\n        state[\"screening\"],\n        state[\"likelihood\"],\n        state[\"duration\"],\n        state[\"review_plan\"],\n        state[\"requirements_analysis\"],\n        state[\"evidence_review\"],\n        state[\"prediction_analysis\"],\n    )\n    screening = state[\"screening\"]\n    profile = state[\"application_profile\"]\n    recommendation = reply[\"review_recommendation\"]\n    calls_made = int(state.get(\"llm_call_count\") or 0) + 1\n    review_record = {\n        \"review_id\": state[\"review_id\"],\n        \"run_id\": state[\"run_id\"],\n        \"application_reference\": state[\"application_reference\"],\n        \"technology\": screening[\"technology\"],\n        \"urgency\": profile.get(config.URGENCY_COLUMN),\n        \"standard_document\": screening[\"standard_document\"],\n        \"coordinator_request\": state[\"coordinator_request\"],\n        \"status\": config.REVIEW_STATUS_AWAITING,\n        \"requirements\": [\n            {key: requirement[key] for key in REQUIREMENT_RECORD_KEYS}\n            for requirement in screening[\"requirements\"]\n        ],\n        \"requirements_met_count\": screening[config.REQUIREMENTS_MET_COUNT_COLUMN],\n        \"requirements_not_met_count\": screening[config.REQUIREMENTS_NOT_MET_COUNT_COLUMN],\n        \"requirements_not_documented_count\": screening[\n            config.REQUIREMENTS_NOT_DOCUMENTED_COUNT_COLUMN\n        ],\n        \"network_triggers\": list(screening[\"network_triggers\"]),\n        \"rating_stated\": bool(screening[\"rating_stated\"]),\n        \"assessment\": screening[\"assessment\"],\n        \"decisions_open\": list(screening[\"decisions_open\"]),\n        \"evidence\": state[\"evidence_findings\"],\n        \"disagreements\": state[\"disagreements\"],\n        \"network_work_likelihood\": state[\"likelihood\"][\"network_work_likelihood\"],\n        \"likelihood_band\": state[\"likelihood\"][\"likelihood_band\"],\n        \"expected_working_days\": state[\"duration\"][\"expected_working_days\"],\n        \"planned_working_days\": state[\"duration\"][\"planned_working_days\"],\n        \"delay_expected\": state[\"duration\"][\"delay_expected\"],\n        \"duration_text\": describe_expected_working_days(state[\"duration\"]),\n        \"review_plan_text\": agents.join_labelled_response(state[\"review_plan\"]),\n        \"requirements_analysis_text\": agents.join_labelled_response(\n            state[\"requirements_analysis\"]\n        ),\n        \"evidence_review_text\": agents.join_labelled_response(state[\"evidence_review\"]),\n        \"prediction_analysis_text\": agents.join_labelled_response(state[\"prediction_analysis\"]),\n        \"recommendation_text\": recommendation[\"RECOMMENDATION\"],\n        \"recommended_decision\": recommendation[\"RECOMMENDED DECISION\"],\n        \"installer_notice_text\": None,\n        \"notice_details\": None,\n        \"household_notice_text\": None,\n        \"assessment_brief\": None,\n    }\n    with session_factory() as session:\n        insert_llm_call(session, state[\"run_id\"], reply[\"call_record\"])\n        insert_application_review(session, review_record)\n        update_agent_run(\n            session, state[\"run_id\"], config.AGENT_RUN_STATUS_AWAITING_DECISION, calls_made\n        )\n        session.commit()\n    return {\"review_recommendation\": recommendation, \"llm_call_count\": 1}\n\n\ndef await_engineer_decision_node(state):\n    \"\"\"Stop until a Connections Engineer decides; accept only a decision that may be recorded.\"\"\"\n    review_decision = interrupt({\"review_id\": state[\"review_id\"]})\n    refusal = find_decision_refusal(review_decision, state[\"screening\"], state[\"coordinator_id\"])\n    if refusal is not None:\n        raise ValueError(refusal)\n    return {\"review_decision\": review_decision}\n\n\ndef route_engineer_decision(state):\n    \"\"\"The path out of the gate, and out of the installer notice, is named by the decision.\"\"\"\n    return state[\"review_decision\"][\"decision\"]\n\n\ndef draft_installer_notice_node(state):\n    \"\"\"Write the connection approval or the rework request.\"\"\"\n    decision = state[\"review_decision\"][\"decision\"]\n    profile = state[\"application_profile\"]\n    screening = state[\"screening\"]\n    technology = screening[\"technology\"]\n    if decision == config.DECISION_APPROVE:\n        details = build_approval_details(profile, screening)\n        guidance = read_connection_approval_guidance(knowledge_collection, technology)\n    else:\n        details = build_rework_details(\n            profile,\n            screening,\n            read_documentation_to_provide(knowledge_collection, technology),\n            state[\"disagreements\"],\n        )\n        guidance = config.REWORK_REQUEST_GUIDANCE\n    reply = agents.draft_installer_notice(decision, profile, details, guidance)\n    _record_call(state[\"run_id\"], reply[\"call_record\"])\n    return {\n        \"installer_notice\": reply[\"installer_notice\"],\n        \"notice_details\": details,\n        \"llm_call_count\": 1,\n    }\n\n\ndef draft_household_notice_node(state):\n    \"\"\"Write the household notice, after a connection approval.\"\"\"\n    profile = state[\"application_profile\"]\n    screening = state[\"screening\"]\n    details = build_household_notice_details(profile, screening)\n    guidance = read_household_notice_guidance(knowledge_collection, screening[\"technology\"])\n    reply = agents.draft_household_notice(profile, details, guidance)\n    _record_call(state[\"run_id\"], reply[\"call_record\"])\n    return {\"household_notice\": reply[\"household_notice\"], \"llm_call_count\": 1}\n\n\ndef record_connection_outcome_node(state):\n    \"\"\"Record the decision and everything it led to, and close the run.\"\"\"\n    review_decision = state[\"review_decision\"]\n    decision = review_decision[\"decision\"]\n    outcome = {\n        \"status\": config.REVIEW_STATUS_BY_DECISION[decision],\n        \"installer_notice_text\": None,\n        \"notice_details\": None,\n        \"household_notice_text\": None,\n        \"assessment_brief\": None,\n    }\n    if decision in (config.DECISION_APPROVE, config.DECISION_RETURN):\n        outcome[\"installer_notice_text\"] = agents.join_labelled_response(state[\"installer_notice\"])\n        outcome[\"notice_details\"] = state[\"notice_details\"]\n    if decision == config.DECISION_APPROVE:\n        outcome[\"household_notice_text\"] = agents.join_labelled_response(\n            state[\"household_notice\"]\n        )\n    if decision == config.DECISION_REFER:\n        outcome[\"assessment_brief\"] = build_assessment_brief(\n            state[\"application_profile\"],\n            state[\"screening\"],\n            state[\"likelihood\"],\n            state[\"duration\"],\n            state[\"disagreements\"],\n        )\n    with session_factory() as session:\n        insert_review_decision(\n            session,\n            {\n                \"review_id\": state[\"review_id\"],\n                \"decision\": decision,\n                \"decided_by\": review_decision[\"decided_by\"],\n                \"decided_by_role\": review_decision[\"decided_by_role\"],\n                \"decision_reason\": review_decision[\"decision_reason\"],\n            },\n        )\n        record_review_outcome(session, state[\"review_id\"], outcome)\n        update_agent_run(\n            session,\n            state[\"run_id\"],\n            config.AGENT_RUN_STATUS_COMPLETE,\n            int(state.get(\"llm_call_count\") or 0),\n        )\n        session.commit()\n    return {}\n"}, {"path": "agentic/graph.py", "explain": "build_workflow wires the ten nodes: seven in a straight line to the gate, then two conditional branches chosen by the decision (approve -> installer notice -> household notice; return -> installer notice -> record; refer -> record). Compiled with a SQLite checkpointer so a paused review survives a restart.", "code": "\"\"\"The order the nodes run in, the gate, the two branches and the checkpoint.\"\"\"\n\nimport os\nimport sqlite3\n\nfrom langgraph.checkpoint.sqlite import SqliteSaver\nfrom langgraph.graph import END, START, StateGraph\n\nfrom agentic.nodes import (\n    analyse_installer_statements_node,\n    assess_connection_requirements_node,\n    await_engineer_decision_node,\n    draft_household_notice_node,\n    draft_installer_notice_node,\n    interpret_model_predictions_node,\n    load_application_context_node,\n    plan_application_review_node,\n    prepare_review_recommendation_node,\n    record_connection_outcome_node,\n    route_engineer_decision,\n)\nfrom agentic.state import ApplicationReviewState\nfrom config import config\n\n\ndef build_workflow(checkpoint_path):\n    \"\"\"Assemble the ten nodes into a workflow that pauses at the gate and survives a restart.\"\"\"\n    folder = os.path.dirname(checkpoint_path)\n    if folder:\n        os.makedirs(folder, exist_ok=True)\n    graph = StateGraph(ApplicationReviewState)\n    graph.add_node(\"load_application_context\", load_application_context_node)\n    graph.add_node(\"plan_application_review\", plan_application_review_node)\n    graph.add_node(\"assess_connection_requirements\", assess_connection_requirements_node)\n    graph.add_node(\"analyse_installer_statements\", analyse_installer_statements_node)\n    graph.add_node(\"interpret_model_predictions\", interpret_model_predictions_node)\n    graph.add_node(\"prepare_review_recommendation\", prepare_review_recommendation_node)\n    graph.add_node(\"await_engineer_decision\", await_engineer_decision_node)\n    graph.add_node(\"draft_installer_notice\", draft_installer_notice_node)\n    graph.add_node(\"draft_household_notice\", draft_household_notice_node)\n    graph.add_node(\"record_connection_outcome\", record_connection_outcome_node)\n\n    graph.add_edge(START, \"load_application_context\")\n    graph.add_edge(\"load_application_context\", \"plan_application_review\")\n    graph.add_edge(\"plan_application_review\", \"assess_connection_requirements\")\n    graph.add_edge(\"assess_connection_requirements\", \"analyse_installer_statements\")\n    graph.add_edge(\"analyse_installer_statements\", \"interpret_model_predictions\")\n    graph.add_edge(\"interpret_model_predictions\", \"prepare_review_recommendation\")\n    graph.add_edge(\"prepare_review_recommendation\", \"await_engineer_decision\")\n    graph.add_conditional_edges(\n        \"await_engineer_decision\",\n        route_engineer_decision,\n        {\n            config.DECISION_APPROVE: \"draft_installer_notice\",\n            config.DECISION_RETURN: \"draft_installer_notice\",\n            config.DECISION_REFER: \"record_connection_outcome\",\n        },\n    )\n    graph.add_conditional_edges(\n        \"draft_installer_notice\",\n        route_engineer_decision,\n        {\n            config.DECISION_APPROVE: \"draft_household_notice\",\n            config.DECISION_RETURN: \"record_connection_outcome\",\n        },\n    )\n    graph.add_edge(\"draft_household_notice\", \"record_connection_outcome\")\n    graph.add_edge(\"record_connection_outcome\", END)\n\n    connection = sqlite3.connect(checkpoint_path, check_same_thread=False)\n    return graph.compile(checkpointer=SqliteSaver(connection))\n"}], "commands": "git pull origin main\nmkdir -p agentic\n# paste today's files, then:\ngit add agentic/nodes.py agentic/graph.py\ngit commit -m \"Day 5 (LangGraph): The ten workflow steps and the compiled, checkpointed graph\"\ngit push origin HEAD", "demo": "python - <<'EOF'\nfrom agentic import nodes\nfrom agentic.graph import build_workflow\nworkflow = build_workflow(\"database/checkpoint.db\")\nprint(sorted(workflow.builder.nodes))\nreference = nodes.open_applications[\"application_reference\"].iloc[0]\ncontext = nodes.gather_application_context(reference)\nprint(reference, context[\"screening\"][\"assessment\"], context[\"likelihood\"], context[\"duration\"])\nEOF", "show": "The ten nodes are registered; gather_application_context gives one application's screening, evidence, flags, likelihood and expected days with no model call. The gate pauses on disk and resumes after a restart."}, {"owner": "janavi", "summary": "One-call assistant answering only from the documents.", "files": [{"path": "chat/connection_assistant.py", "explain": "answer_from_documents: two searches (question + conversation), one Gemini call with the passages, all five standards' requirements and every guide's checks. It classifies the question into the seven types, reclassifies questions naming an application or substation, refuses anything out of scope or too far from the documents, and returns the cited source documents.", "code": "\"\"\"One question, one language model call, answered from the documents and nothing else.\"\"\"\n\nimport re\n\nfrom agentic.agents import call_language_model, parse_labelled_response\nfrom config import config\nfrom knowledge.standard_reading import read_connection_standard\nfrom knowledge.vector_index import search_documents\nfrom tools.retrieval_tools import read_documentation_to_provide, read_reviewer_checks\n\nFIELD_LABELS = [\"QUESTION TYPE\", \"APPLICATION\", \"ANSWER\"]\n\n\ndef _bare(value):\n    return re.sub(config.RESPONSE_DECORATION_EDGE_PATTERN, \"\", value.strip())\n\n\ndef _single_line(value, field):\n    if \"\\n\" in value.strip():\n        raise ValueError(\n            f\"{config.AGENT_NAME_CONNECTION_ASSISTANT} wrote {field} over more than one line\"\n        )\n    return value.strip()\n\n\ndef _offered_passages(collection, question_text, search_text):\n    found = search_documents(collection, [question_text, search_text])\n    offered = {}\n    for passages in found:\n        for passage in passages:\n            known = offered.get(passage[\"chunk_id\"])\n            if known is None or passage[\"distance\"] < known[\"distance\"]:\n                offered[passage[\"chunk_id\"]] = passage\n    return sorted(offered.values(), key=lambda passage: passage[\"distance\"])\n\n\ndef _standards_text(collection, document_entries):\n    blocks = []\n    for technology, document_name in config.CONNECTION_STANDARD_DOCUMENTS.items():\n        standard = read_connection_standard(technology, document_entries)\n        lines = [\n            f\"{config.TECHNOLOGY_NAMES[technology]} ({technology}), from {document_name}:\"\n        ]\n        lines.extend(\n            f\"- {requirement['requirement_name']}: {requirement['requirement_sentence']}\"\n            for requirement in standard[\"requirements\"]\n        )\n        lines.append(\n            \"- Documentation to provide: \" + read_documentation_to_provide(collection, technology)\n        )\n        blocks.append(\"\\n\".join(lines))\n    return \"\\n\\n\".join(blocks)\n\n\ndef _guides_text(collection):\n    return \"\\n\".join(\n        f\"- {sentence_type}, from {document_name}: \"\n        + read_reviewer_checks(collection, sentence_type)\n        for sentence_type, document_name in config.SENTENCE_TYPE_GUIDE_DOCUMENTS.items()\n    )\n\n\ndef _canonical_reference(reference):\n    match = re.match(config.APPLICATION_REFERENCE_PATTERN, reference.upper())\n    if match is None:\n        return reference\n    return config.APPLICATION_REFERENCE_PREFIX + match.group(1).zfill(\n        config.APPLICATION_REFERENCE_DIGITS\n    )\n\n\ndef _reference_is_named(reference, texts):\n    lowered = [text.lower() for text in texts]\n    if re.fullmatch(config.CANONICAL_APPLICATION_REFERENCE_PATTERN, reference):\n        if any(reference.lower() in text for text in lowered):\n            return True\n        number = str(int(reference[len(config.APPLICATION_REFERENCE_PREFIX):]))\n        pattern = config.NUMBER_IN_TEXT_PATTERN.format(number=number)\n        return any(re.search(pattern, text) for text in texts)\n    return any(reference.lower() in text for text in lowered)\n\n\ndef _substation_and_technology(question_text, previous_question):\n    substations = [\n        found.upper() for found in re.findall(config.SUBSTATION_IN_TEXT_PATTERN, question_text)\n    ]\n    if not substations and previous_question:\n        substations = [\n            found.upper()\n            for found in re.findall(config.SUBSTATION_IN_TEXT_PATTERN, previous_question)\n        ]\n\n    def technologies_in(text):\n        return [\n            technology\n            for technology, pattern in config.CHAT_TECHNOLOGY_PATTERNS.items()\n            if re.search(pattern, text.lower())\n        ]\n\n    technologies = technologies_in(question_text)\n    if not technologies and previous_question:\n        technologies = technologies_in(previous_question)\n    substations = list(dict.fromkeys(substations))\n    if len(substations) == 1 and len(technologies) == 1:\n        return substations[0], technologies[0]\n    return None, None\n\n\ndef answer_from_documents(collection, document_entries, question_text, conversation):\n    \"\"\"Classify the question and answer it from the documents, or refuse.\"\"\"\n    passages = _offered_passages(collection, question_text, conversation[\"search_text\"])\n    passage_text = \"\\n\\n\".join(\n        f\"[{passage['document_name']}, section {passage['section_number']}] \"\n        f\"{passage['chunk_text']}\"\n        for passage in passages\n    )\n    types_text = \"\\n\".join(f\"- {question_type}\" for question_type in config.CHAT_TYPE_OPTIONS)\n    prompt = (\n        f\"You are the connection assistant of {config.ORGANISATION_NAME}. You answer questions \"\n        \"from Merrowdale's own documents and from nothing else. You know nothing about any \"\n        \"individual application or substation: questions about those are answered from the \"\n        \"records by the service, not by you.\\n\\n\"\n        f\"QUESTION TYPES\\n{types_text}\\n\"\n        f\"- {config.CHAT_TYPE_CONNECTION_STANDARD}: what a technology's connection standard \"\n        \"requires or asks for.\\n\"\n        f\"- {config.CHAT_TYPE_CONNECTION_RULES}: how the Connection Rules or the Low-Carbon \"\n        \"Connections Policy work.\\n\"\n        f\"- {config.CHAT_TYPE_STATEMENT_GUIDANCE}: what the statement guides say.\\n\"\n        f\"- {config.CHAT_TYPE_APPLICATION_STATUS}: the status of a named application.\\n\"\n        f\"- {config.CHAT_TYPE_OUTCOME_PREDICTION}: whether an application will need network \"\n        \"work or how long it will take.\\n\"\n        f\"- {config.CHAT_TYPE_SUBSTATION_FIGURE}: how many of a technology are connected at a \"\n        \"substation.\\n\"\n        f\"- {config.CHAT_TYPE_OUT_OF_SCOPE}: anything the documents do not cover.\\n\\n\"\n        \"Keep each requirement to its own technology's standard.\\n\\n\"\n        f\"CONVERSATION SO FAR\\n{conversation['history_text']}\\n\\n\"\n        f\"PASSAGES FOUND\\n{passage_text or config.CHAT_NO_VALUE_REPLY}\\n\\n\"\n        f\"WHAT EACH CONNECTION STANDARD REQUIRES\\n{_standards_text(collection, document_entries)}\\n\\n\"\n        f\"WHAT EACH STATEMENT GUIDE SAYS THE REVIEWER CHECKS\\n{_guides_text(collection)}\\n\\n\"\n        f\"QUESTION\\n{question_text}\\n\\n\"\n        \"Reply with exactly these labelled fields, each label at the start of its own line \"\n        f\"followed by a colon. Write {config.CHAT_NO_VALUE_REPLY} in a field that does not apply.\\n\"\n        \"QUESTION TYPE: <one of the question types, on one line>\\n\"\n        \"APPLICATION: <the application reference the question is about, or \"\n        f\"{config.CHAT_NO_VALUE_REPLY}, on one line>\\n\"\n        \"ANSWER: <the answer, from the documents only>\"\n    )\n    reply = call_language_model(prompt, config.AGENT_NAME_CONNECTION_ASSISTANT)\n    agent_name = config.AGENT_NAME_CONNECTION_ASSISTANT\n    fields = parse_labelled_response(reply[\"response_text\"], FIELD_LABELS, agent_name)\n    question_type = _bare(_single_line(fields[\"QUESTION TYPE\"], \"QUESTION TYPE\")).upper()\n    application_field = _bare(_single_line(fields[\"APPLICATION\"], \"APPLICATION\"))\n    if question_type not in config.CHAT_TYPE_OPTIONS:\n        raise ValueError(f\"{agent_name} gave the question type {question_type}, which is unknown\")\n    if not application_field:\n        raise ValueError(f\"{agent_name} left APPLICATION empty\")\n    answer_text = fields[\"ANSWER\"].strip()\n\n    if question_type in config.CHAT_ANSWERED_TYPES:\n        if re.search(config.APPLICATION_REFERENCE_IN_TEXT_PATTERN, question_text):\n            question_type = config.CHAT_TYPE_APPLICATION_STATUS\n        elif re.search(config.SUBSTATION_IN_TEXT_PATTERN, question_text):\n            question_type = config.CHAT_TYPE_SUBSTATION_FIGURE\n\n    closest_distance = passages[0][\"distance\"] if passages else None\n    answered = (\n        question_type in config.CHAT_ANSWERED_TYPES\n        and closest_distance is not None\n        and closest_distance <= config.CHAT_MAX_RELEVANCE_DISTANCE\n    )\n    if answered and _bare(answer_text).lower() == config.CHAT_NO_VALUE_REPLY.lower():\n        raise ValueError(f\"{agent_name} answered {config.CHAT_NO_VALUE_REPLY} to an answerable question\")\n\n    application_reference = None\n    if question_type in config.CHAT_APPLICATION_TYPES:\n        named = re.findall(config.APPLICATION_REFERENCE_IN_TEXT_PATTERN, question_text)\n        if named:\n            candidate = named[0]\n        elif application_field.lower() != config.CHAT_NO_VALUE_REPLY.lower():\n            candidate = application_field\n        else:\n            candidate = None\n        if candidate is not None:\n            application_reference = _canonical_reference(candidate)\n            if not _reference_is_named(\n                application_reference, [question_text, conversation[\"history_text\"]]\n            ):\n                raise ValueError(\n                    f\"{agent_name} named the application {application_reference}, which neither \"\n                    \"the question nor the conversation names\"\n                )\n\n    substation_reference, technology = None, None\n    if question_type == config.CHAT_TYPE_SUBSTATION_FIGURE:\n        substation_reference, technology = _substation_and_technology(\n            question_text, conversation[\"previous_question\"]\n        )\n\n    source_documents = []\n    was_refused = False\n    if answered:\n        if question_type == config.CHAT_TYPE_CONNECTION_STANDARD:\n            source_documents.extend(config.CONNECTION_STANDARD_DOCUMENTS.values())\n        if question_type == config.CHAT_TYPE_STATEMENT_GUIDANCE:\n            source_documents.extend(config.SENTENCE_TYPE_GUIDE_DOCUMENTS.values())\n        source_documents.extend(passage[\"document_name\"] for passage in passages)\n        source_documents = list(dict.fromkeys(source_documents))\n    elif question_type not in config.CHAT_RECORD_TYPES:\n        question_type = config.CHAT_TYPE_OUT_OF_SCOPE\n        answer_text = config.CHAT_REFUSAL_MESSAGE\n        was_refused = True\n\n    return {\n        \"question_type\": question_type,\n        \"application_reference\": application_reference,\n        \"substation_reference\": substation_reference,\n        \"technology\": technology,\n        \"answer\": answer_text,\n        \"source_documents\": source_documents,\n        \"closest_distance\": closest_distance,\n        \"was_refused\": was_refused,\n    }\n"}], "commands": "git pull origin main\nmkdir -p chat\n# paste today's files, then:\ngit add chat/connection_assistant.py\ngit commit -m \"Day 5 (RAG): One-call assistant answering only from the documents\"\ngit push origin HEAD", "demo": "python - <<'EOF'\nfrom agentic import nodes\nfrom config import config\nfrom chat.connection_assistant import answer_from_documents\nconversation = {\"history_text\": config.CHAT_FIRST_QUESTION_TEXT,\n                \"search_text\": \"What does the heat pump connection standard ask for?\", \"previous_question\": \"\"}\nreply = answer_from_documents(nodes.knowledge_collection, nodes.knowledge_documents,\n                              conversation[\"search_text\"], conversation)\nprint(reply[\"question_type\"], reply[\"was_refused\"], reply[\"closest_distance\"])\nprint(reply[\"answer\"][:400])\nprint(reply[\"source_documents\"])\nEOF", "show": "The question is classified CONNECTION STANDARD, answered from the passages and the standards, and the answer cites the documents it came from - never the casebook."}, {"owner": "aparna", "summary": "Entry point 6: service check, sign-in and role-based navigation.", "files": [{"path": "run_dashboard.py", "explain": "Entry point 6. Checks the service answers on 8081, shows only the sign-in page until someone signs in, then a sidebar with name, role and Sign out, and exactly the pages the service returned for that role (st.navigation).", "code": "\"\"\"Entry point 6: the dashboard's front door - the service check, signing in and navigation.\n\nRun from the Project folder:  python -m streamlit run run_dashboard.py   (port 8080)\n\"\"\"\n\nimport httpx\nimport streamlit as st\n\nfrom config import config\nfrom dashboard.api_client import SESSION_USER_KEY, call_service, signed_in_user\nfrom dashboard.application_detail import render_application_detail_page\nfrom dashboard.application_queue import render_application_queue_page\nfrom dashboard.audit_trail import render_audit_trail_page\nfrom dashboard.connection_chat import render_connection_chat_page\nfrom dashboard.decision_queue import render_decision_queue_page\nfrom dashboard.sign_in import render_sign_in_page\n\nPAGE_RENDERERS = {\n    config.PAGE_QUEUE: render_application_queue_page,\n    config.PAGE_DETAIL: render_application_detail_page,\n    config.PAGE_DECISION: render_decision_queue_page,\n    config.PAGE_AUDIT: render_audit_trail_page,\n    config.PAGE_CHAT: render_connection_chat_page,\n}\nPAGE_ICONS = {\n    config.PAGE_QUEUE: \":material/format_list_numbered:\",\n    config.PAGE_DETAIL: \":material/description:\",\n    config.PAGE_DECISION: \":material/gavel:\",\n    config.PAGE_AUDIT: \":material/history:\",\n    config.PAGE_CHAT: \":material/forum:\",\n}\nPAGE_URL_PATHS = {\n    config.PAGE_QUEUE: \"queue\",\n    config.PAGE_DETAIL: \"detail\",\n    config.PAGE_DECISION: \"decisions\",\n    config.PAGE_AUDIT: \"audit\",\n    config.PAGE_CHAT: \"chat\",\n}\n\n\ndef _service_answers():\n    try:\n        httpx.get(config.API_BASE_URL + \"/docs\", timeout=5)\n        return True\n    except httpx.HTTPError:\n        return False\n\n\ndef main():\n    \"\"\"Draw only the pages the signed-in person's role is offered.\"\"\"\n    st.set_page_config(page_title=config.DASHBOARD_TITLE, layout=\"wide\")\n    st.markdown(config.DASHBOARD_PAGE_STYLE, unsafe_allow_html=True)\n    if not _service_answers():\n        st.error(\n            f\"The service is not answering at {config.API_BASE_URL}. Start it from the Project \"\n            \"folder with: python run_api_service.py\"\n        )\n        return\n    user = signed_in_user()\n    if user is None:\n        render_sign_in_page()\n        return\n    with st.sidebar:\n        st.markdown(f\"**{user['display_name']}**  \\n{user['role']}\")\n        if st.button(\"Sign out\", use_container_width=True):\n            call_service(\"POST\", \"/auth/signout\")\n            st.session_state.pop(SESSION_USER_KEY, None)\n            st.rerun()\n    pages = [\n        st.Page(\n            PAGE_RENDERERS[name],\n            title=name,\n            icon=PAGE_ICONS[name],\n            url_path=PAGE_URL_PATHS[name],\n            default=(position == 0),\n        )\n        for position, name in enumerate(user[\"pages\"])\n    ]\n    st.navigation(pages).run()\n\n\nif __name__ == \"__main__\":\n    main()\n"}], "commands": "git pull origin main\n# paste today's files, then:\ngit add run_dashboard.py\ngit commit -m \"Day 5 (Streamlit): Entry point 6: service check, sign-in and role-based navigation\"\ngit push origin HEAD", "demo": "python -m streamlit run run_dashboard.py\n# open http://localhost:8080  (service must be running)", "show": "Sign in as ravi (coordinator): queue, detail, audit and chat. Open a review from the detail page. Sign in as lewis (engineer): the decision queue appears and he records the decision. zara (advisor) sees only the chat."}, {"owner": "karthik", "summary": "Full end-to-end run and the test suite.", "files": [], "commands": "git status\ngit pull origin main", "demo": "rm -f database/phasewise.db database/checkpoint.db\npython run_database_setup.py\npython run_data_pipeline.py\npython run_model_training.py\npython run_knowledge_indexing.py\npython -m pytest tests.py -q", "show": "Start from an empty database (the suite opens exactly one review), run the four build steps, then the 50 tests. The workflow and chat tests need GEMINI_API_KEY and GEMINI_MODEL in .env."}]}], "files": {"persistence/database.py": {"owner": "yashwanth", "day": 1}, "persistence/models.py": {"owner": "yashwanth", "day": 1}, "persistence/repository.py": {"owner": "yashwanth", "day": 1}, "access/password_security.py": {"owner": "yashwanth", "day": 1}, "run_database_setup.py": {"owner": "yashwanth", "day": 1}, "agentic/state.py": {"owner": "yash", "day": 1}, "tools/decision_tools.py": {"owner": "yash", "day": 1}, "knowledge/pdf_extraction.py": {"owner": "janavi", "day": 1}, "knowledge/chunk_splitting.py": {"owner": "janavi", "day": 1}, "dashboard/api_client.py": {"owner": "aparna", "day": 1}, "dashboard/sign_in.py": {"owner": "aparna", "day": 1}, "data_pipeline/dataset_loader.py": {"owner": "karthik", "day": 1}, "data_pipeline/common_cleaning.py": {"owner": "karthik", "day": 1}, "data_pipeline/application_cleaning.py": {"owner": "karthik", "day": 1}, "data_pipeline/document_cleaning.py": {"owner": "karthik", "day": 1}, "tools/application_data_tools.py": {"owner": "yashwanth", "day": 2}, "tools/screening_tools.py": {"owner": "yash", "day": 2}, "tools/notice_tools.py": {"owner": "yash", "day": 2}, "knowledge/standard_reading.py": {"owner": "janavi", "day": 2}, "knowledge/vector_index.py": {"owner": "janavi", "day": 2}, "dashboard/application_queue.py": {"owner": "aparna", "day": 2}, "dashboard/application_detail.py": {"owner": "aparna", "day": 2}, "data_pipeline/history_cleaning.py": {"owner": "karthik", "day": 2}, "data_pipeline/connection_log_cleaning.py": {"owner": "karthik", "day": 2}, "data_pipeline/sentence_cleaning.py": {"owner": "karthik", "day": 2}, "data_pipeline/quality_profiler.py": {"owner": "karthik", "day": 2}, "run_data_pipeline.py": {"owner": "karthik", "day": 2}, "api/schemas.py": {"owner": "yashwanth", "day": 3}, "tools/evidence_tools.py": {"owner": "yash", "day": 3}, "tools/retrieval_tools.py": {"owner": "janavi", "day": 3}, "run_knowledge_indexing.py": {"owner": "janavi", "day": 3}, "dashboard/decision_queue.py": {"owner": "aparna", "day": 3}, "dashboard/audit_trail.py": {"owner": "aparna", "day": 3}, "data_pipeline/feature_builder.py": {"owner": "karthik", "day": 3}, "modeling/model_registry.py": {"owner": "karthik", "day": 3}, "modeling/model_evaluation.py": {"owner": "karthik", "day": 3}, "modeling/network_work_model.py": {"owner": "karthik", "day": 3}, "tools/prediction_tools.py": {"owner": "karthik", "day": 3}, "access/permissions.py": {"owner": "yashwanth", "day": 4}, "agentic/agents.py": {"owner": "yash", "day": 4}, "chat/conversation_memory.py": {"owner": "janavi", "day": 4}, "chat/record_answer.py": {"owner": "janavi", "day": 4}, "dashboard/connection_chat.py": {"owner": "aparna", "day": 4}, "modeling/duration_model.py": {"owner": "karthik", "day": 4}, "modeling/sentence_model.py": {"owner": "karthik", "day": 4}, "run_model_training.py": {"owner": "karthik", "day": 4}, "api/routes.py": {"owner": "yashwanth", "day": 5}, "run_api_service.py": {"owner": "yashwanth", "day": 5}, "agentic/nodes.py": {"owner": "yash", "day": 5}, "agentic/graph.py": {"owner": "yash", "day": 5}, "chat/connection_assistant.py": {"owner": "janavi", "day": 5}, "run_dashboard.py": {"owner": "aparna", "day": 5}}, "flow": ["Pull main into your branch so you have everyone's merged work (git pull origin main).", "Open each of today's files below, copy the code and paste it into the same path in the Project folder.", "Run your 'Show in review' demo once to be sure it works, then commit and push to your own branch.", "Yashwanth opens a pull request from each branch into main and merges them.", "Everyone pulls main again and the end-of-day check is run for the review. Tick your files."], "faq": {"answer": ["No branch updates itself. When a pull request is merged, only main changes; the other four branches keep their old copy of main until their owner pulls it. So yes - each member pulls main into their own branch, once at the start of every day, before pasting new files.", "You do not have to pull right before every push for git to accept it: pushing to your own branch only needs your branch to be up to date with itself. But today's demos import files written by teammates on earlier days, so without the pull your code will not run.", "Because every file has exactly one owner, merging main into a branch never conflicts on code. If git ever opens an editor for a merge message, save and close it."], "lead": ["When a member has pushed, open a pull request from their branch into main.", "Merge it (use a normal merge, not 'squash', so branches stay in step).", "Repeat for each branch; on Day 5 merge Yash and Janavi before your own routes.py.", "Pull main into your own branch and run the end-of-day check before the review.", "Tell the team to run the start-of-day commands below."], "syncCommands": "git config pull.rebase false   # once: pulling main merges it in\ngit status                 # confirm you are on your own branch\ngit pull origin main       # bring in everything merged so far\ngit push origin HEAD       # optional: keep your remote branch in step"}};
